PROPERTIES.forEach((property) => {
  const gallery = SAMPLE_PROPERTY_GALLERIES[property.id];
  if (!gallery || !gallery.length || Array.isArray(property.images)) return;
  property.images = gallery.map((item, index) => ({
    ...item,
    name: item.name || `Photo ${index + 1}`,
    type: "image/jpeg"
  }));
  property.main_photo_index = Math.max(0, property.images.findIndex((item) => item.is_main));
  if (!property.img && property.images[0]?.url) property.img = property.images[0].url;
  property.photoCount = Math.max(property.photoCount || 0, property.images.length);
});

