function mapRemoteAgentForUi(agent = {}) {
  const covered = Array.isArray(agent.districts_covered) ? agent.districts_covered.filter(Boolean) : [];
  const area = covered.length ? covered.slice(0, 3).join(" • ") : (agent.area || "Uganda");
  const specializations = Array.isArray(agent.specializations) ? agent.specializations.filter(Boolean) : [];
  const socials = normalizeBrokerSocialLinks(agent);
  return {
    id: String(agent.id || ""),
    makaug_agent_number: agent.makaug_agent_number || agent.agent_number || "",
    name: agent.full_name || agent.name || "makaug agent",
    company: agent.company_name || agent.company || "makaug",
    phone: agent.phone || "",
    email: agent.email || "",
    whatsapp: String(agent.whatsapp || agent.phone || "").replace(/\D/g, ""),
    area,
    rating: Number(agent.rating || 0) || 0,
    listings: Number(agent.listings_count || agent.total_listings || agent.listings || 0) || 0,
    live_listings: Number(agent.live_listings || agent.listings_count || 0) || 0,
    pending_listings: Number(agent.pending_listings || agent.pending_listings_count || 0) || 0,
    rejected_listings: Number(agent.rejected_listings || 0) || 0,
    lead_enquiries: Number(agent.lead_enquiries || agent.inquiry_count || 0) || 0,
    sales: Number(agent.sales_count || agent.sales || 0) || 0,
    emoji: agent.profile_photo_url ? "" : "👔",
    photo: agent.profile_photo_url || "",
    profile_photo_url: agent.profile_photo_url || "",
    registration_status: String(agent.registration_status || "not_registered").toLowerCase(),
    experience: agent.experience || (agent.experience_years || agent.experience_years === 0 ? `${agent.experience_years} year${Number(agent.experience_years) === 1 ? "" : "s"}` : ""),
    experience_years: Number(agent.experience_years || 0) || 0,
    licence: agent.licence_number || agent.licence || "",
    languages: Array.isArray(agent.languages) ? agent.languages.filter(Boolean) : ["English"],
    specialties: specializations,
    bio: agent.bio || "Professional makaug agent profile.",
    featured_homepage: agent.featured_homepage === true,
    featured_at: agent.featured_at || null,
    status: agent.status || "approved",
    districts_covered: covered,
    specializations,
    socials,
    youtube_url: agent.youtube_url || socials.find((item) => item.key === "youtube")?.url || "",
    tiktok_url: agent.tiktok_url || socials.find((item) => item.key === "tiktok")?.url || "",
    website_url: agent.website_url || socials.find((item) => item.key === "website")?.url || "",
    instagram_url: agent.instagram_url || socials.find((item) => item.key === "instagram")?.url || "",
    facebook_url: agent.facebook_url || socials.find((item) => item.key === "facebook")?.url || "",
    user_id: agent.user_id || "",
    nin: agent.nin || "",
    id_expiry_date: agent.id_expiry_date || "",
    identity_document_name: agent.identity_document_name || "",
    identity_document_url: agent.identity_document_url || "",
    identity_document_type: agent.identity_document_type || "",
    identity_document_uploaded_at: agent.identity_document_uploaded_at || "",
    verification_reason: agent.verification_reason || "",
    privacy_consent_accepted: agent.privacy_consent_accepted === true,
    privacy_consent_at: agent.privacy_consent_at || "",
    data_retention_notice_accepted: agent.data_retention_notice_accepted === true,
    data_retention_notice_at: agent.data_retention_notice_at || "",
    contact_phone_verified_at: agent.contact_phone_verified_at || "",
    agent_application_channel: agent.agent_application_channel || "",
    approved_at: agent.approved_at || ""
  };
}

function normalizeBrokerSocialUrl(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (/^https?:\/\//i.test(raw)) return raw;
  if (/^[\w.-]+\.[a-z]{2,}/i.test(raw)) return `https://${raw}`;
  return "";
}

function normalizeBrokerSocialLinks(agent = {}) {
  const links = [
    { key: "website", label: "Website", icon: "fas fa-globe", url: agent.website_url || agent.website || agent.url },
    { key: "youtube", label: "YouTube", icon: "fab fa-youtube", url: agent.youtube_url || agent.youtube || agent.youtube_channel_url },
    { key: "tiktok", label: "TikTok", icon: "fab fa-tiktok", url: agent.tiktok_url || agent.tiktok },
    { key: "instagram", label: "Instagram", icon: "fab fa-instagram", url: agent.instagram_url || agent.instagram },
    { key: "facebook", label: "Facebook", icon: "fab fa-facebook", url: agent.facebook_url || agent.facebook },
    { key: "x", label: "X", icon: "fab fa-x-twitter", url: agent.x_url || agent.twitter_url || agent.twitter }
  ];
  return links
    .map((item) => ({ ...item, url: normalizeBrokerSocialUrl(item.url) }))
    .filter((item, index, arr) => item.url && arr.findIndex((other) => other.url === item.url) === index);
}

function renderBrokerSocialLinks(broker = {}) {
  const socials = Array.isArray(broker.socials) ? broker.socials : normalizeBrokerSocialLinks(broker);
  if (!socials.length) return "";
  return `
    <div class="mt-4 flex flex-wrap gap-2">
      ${socials.map((item) => `<a href="${adminAttr(item.url)}" target="_blank" rel="noopener noreferrer" class="inline-flex items-center gap-1.5 rounded-full border border-green-100 bg-white px-3 py-1.5 text-xs font-bold text-green-800 hover:bg-green-50"><i class="${adminAttr(item.icon)}"></i>${adminEscape(item.label)}</a>`).join("")}
    </div>`;
}

function getBrokerDirectory() {
  return remoteBrokersLoaded ? REMOTE_BROKERS : BROKERS;
}

function findBrokerById(id) {
  const key = String(id || "");
  return getBrokerDirectory().find((broker) => String(broker.id || "") === key) || null;
}

function findBrokerByIdIncludingLoadedProfile(id) {
  const key = String(id || "");
  if (!key) return null;
  return findBrokerById(key)
    || REMOTE_BROKERS.find((broker) => String(broker.id || "") === key)
    || null;
}

function getFeaturedBrokers(list = getBrokerDirectory()) {
  const rows = Array.isArray(list) ? [...list] : [];
  rows.sort((a, b) => {
    const af = a?.featured_homepage === true ? 1 : 0;
    const bf = b?.featured_homepage === true ? 1 : 0;
    if (af !== bf) return bf - af;
    const ar = Number(a?.rating || 0);
    const br = Number(b?.rating || 0);
    if (ar !== br) return br - ar;
    return Number(b?.listings || 0) - Number(a?.listings || 0);
  });
  return rows;
}

async function refreshBrokersFromApi({ silent = true } = {}) {
  try {
    const response = await apiRequest("/api/agents?status=approved&limit=100", { skipAuth: true });
    const rows = Array.isArray(response?.data) ? response.data : [];
    const existingById = new Map(REMOTE_BROKERS.map((broker) => [String(broker.id || ""), broker]));
    const nextBrokers = rows.map(mapRemoteAgentForUi).filter((broker) => broker.id).map((broker) => {
      const existing = existingById.get(String(broker.id || ""));
      return existing?.remote_profile_loaded ? { ...broker, ...existing, listings: broker.listings || existing.listings } : broker;
    });
    const nextIds = new Set(nextBrokers.map((broker) => String(broker.id || "")));
    existingById.forEach((existing, id) => {
      if (existing?.remote_profile_loaded && id && !nextIds.has(id)) {
        nextBrokers.push(existing);
      }
    });
    REMOTE_BROKERS = nextBrokers;
    remoteBrokersLoaded = true;
    populateBrokerFilterOptions();
    renderAll();
    setBrokerMapMarkers(getBrokerDirectory());
    return true;
  } catch (error) {
    if (!silent) toast(`Agent refresh failed: ${error.message || "error"}`);
    return false;
  }
}

async function loadRemoteBrokerProfileForUi(id) {
  const brokerId = String(id || "").trim();
  if (!brokerId) return null;
  const response = await apiRequest(`/api/agents/${encodeURIComponent(brokerId)}`, { skipAuth: true });
  const agent = response?.data || {};
  const broker = mapRemoteAgentForUi(agent);
  broker.remote_profile_loaded = true;
  broker.remote_listings = Array.isArray(agent.listings)
    ? agent.listings.map((row) => mapRemotePropertyForUi(row)).filter((listing) => listing.id)
    : [];
  const idx = REMOTE_BROKERS.findIndex((item) => String(item.id || "") === String(broker.id || brokerId));
  if (idx >= 0) {
    REMOTE_BROKERS[idx] = { ...REMOTE_BROKERS[idx], ...broker };
  } else if (broker.id) {
    REMOTE_BROKERS.push(broker);
  }
  remoteBrokersLoaded = true;
  return broker;
}

function getHierarchyPointForArea(district, area) {
  const districtName = String(district || "").trim();
  const areaName = String(area || "").trim().toLowerCase();
  if (!districtName || !areaName) return null;
  const tree = getDistrictLocationTree(districtName);
  for (const node of tree) {
    if (String(node.city || "").trim().toLowerCase() === areaName) {
      return getCityPoint(districtName, node.city);
    }
    const neighborhood = (node.neighborhoods || []).find((item) => String(item.name || "").trim().toLowerCase() === areaName);
    if (neighborhood && Number.isFinite(neighborhood.lat) && Number.isFinite(neighborhood.lng)) {
      return { lat: neighborhood.lat, lng: neighborhood.lng };
    }
  }
  return null;
}

