function homeAssistantTr(key) {
  const lang = currentLang || "en";
  const fallback = LANG_FALLBACK[lang] || "en";
  return HOME_ASSISTANT_I18N[lang]?.[key]
    || HOME_ASSISTANT_I18N[fallback]?.[key]
    || HOME_ASSISTANT_I18N.en?.[key]
    || "";
}

function applyHomeAssistantLanguageUI() {
  const titleEl = document.getElementById("home-assistant-title");
  if (titleEl) titleEl.innerHTML = homeAssistantTr("titleHtml");
  const pillEl = document.getElementById("home-assistant-pill");
  if (pillEl) pillEl.innerHTML = `<i class="fas fa-robot"></i> ${homeAssistantTr("pill")}`;
  setTextById("home-assistant-sub", homeAssistantTr("sub"));
  setTextById("home-assistant-detail", homeAssistantTr("detail"));
  const discoverBtn = document.getElementById("home-assistant-discover-btn");
  if (discoverBtn) discoverBtn.innerHTML = `<i class="fas fa-circle-info"></i> ${homeAssistantTr("discoverCta")}`;
}

function footerTr(key) {
  const lang = currentLang || "en";
  const fallback = LANG_FALLBACK[lang] || "en";
  return FOOTER_I18N[lang]?.[key]
    || FOOTER_I18N[fallback]?.[key]
    || FOOTER_I18N.en?.[key]
    || "";
}

