function mortgageTr(key) {
  const lang = currentLang || "en";
  const fallback = LANG_FALLBACK[lang] || "en";
  return MORTGAGE_I18N[lang]?.[key]
    || MORTGAGE_I18N[fallback]?.[key]
    || MORTGAGE_I18N.en?.[key]
    || key;
}

