function normalizeHeroOpportunityStats(raw = {}) {
  const source = raw?.public_opportunities || raw?.category_counts || raw?.by_type || raw || {};
  const nested = source.by_type || source.category_counts || {};
  const numberFrom = (...keys) => {
    for (const key of keys) {
      const value = Number(source[key] ?? nested[key] ?? 0);
      if (Number.isFinite(value) && value > 0) return value;
    }
    return 0;
  };
  const stats = {
    total: Number(source.total ?? raw?.total ?? 0) || 0,
    sale: numberFrom("sale", "for_sale", "buy"),
    rent: numberFrom("rent", "to_rent", "rental"),
    student: numberFrom("student", "students", "student_accommodation", "student_housing"),
    commercial: numberFrom("commercial", "commercial_property"),
    land: numberFrom("land", "plots"),
    other: numberFrom("other"),
    social: numberFrom("social", "found_online")
  };
  const categoryTotal = stats.sale + stats.rent + stats.student + stats.commercial + stats.land + stats.other;
  if (!stats.total) stats.total = categoryTotal;
  return stats.total || categoryTotal ? stats : null;
}

function getHeroPropertyOpportunityStats() {
  if (publicListingsApiStats) {
    return { ...publicListingsApiStats };
  }
  let publicListings = [];
  try {
    publicListings = typeof getPublicListings === "function"
      ? getPublicListings()
      : PROPERTIES.filter((p) => isListingPublicVisible(p));
  } catch (error) {
    publicListings = [];
  }
  const stats = {
    total: 0,
    sale: 0,
    rent: 0,
    student: 0,
    commercial: 0,
    land: 0,
    other: 0,
    social: 0
  };
  publicListings.forEach((property) => {
    const bucket = getHeroPropertyOpportunityBucket(property);
    stats[bucket] = (stats[bucket] || 0) + 1;
    if (isFoundOnlineListing(property)) stats.social += 1;
  });
  const bucketTotal = stats.sale + stats.rent + stats.student + stats.commercial + stats.land;
  const apiTotal = Number(publicListingsApiTotal ?? 0) || 0;
  const authoritativeTotal = apiTotal || publicListings.length || bucketTotal;
  const unresolvedPublicListings = Math.max(0, authoritativeTotal - bucketTotal);
  if (unresolvedPublicListings) stats.sale += unresolvedPublicListings;
  stats.other = 0;
  stats.total = authoritativeTotal;
  return stats;
}

function publicOpportunityStatForCategory(category) {
  const key = category === "students" ? "student" : normalizeType(category);
  if (!key || !publicListingsApiStats) return null;
  const value = Number(publicListingsApiStats[key]);
  return Number.isFinite(value) && value >= 0 ? value : null;
}

function getPublicCategoryDisplayCount(category, localCount = 0, { filtered = false } = {}) {
  const safeLocalCount = Math.max(0, Number(localCount) || 0);
  if (filtered) return safeLocalCount;
  const apiCount = publicOpportunityStatForCategory(category);
  return apiCount == null ? safeLocalCount : apiCount;
}

function setPublicCategoryCount(category, localCount = 0, options = {}) {
  const idMap = {
    sale: "sale-count",
    rent: "rent-count"
  };
  const el = document.getElementById(idMap[category]);
  if (!el) return;
  el.textContent = getPublicCategoryDisplayCount(category, localCount, options);
}

function getHeroPropertyOpportunityBucket(property) {
  const extra = property?.extra_fields && typeof property.extra_fields === "object" ? property.extra_fields : {};
  const directType = normalizeType(String(property?.listing_type || property?.type || property?.category || extra.listing_type || "").toLowerCase().trim());
  if (["sale", "rent", "student", "commercial", "land"].includes(directType)) return directType;
  if (directType === "students") return "student";

  const propertyType = String(property?.property_type || property?.subtype || extra.property_type || "").toLowerCase();
  if (/\b(land|plot|acre|decimal|estate plots?)\b/.test(propertyType)) return "land";
  if (/\b(commercial|office|shop|retail|warehouse|showroom|restaurant|industrial)\b/.test(propertyType)) return "commercial";

  const period = String(property?.period || property?.price_period || extra.price_period || "").toLowerCase();
  const text = [
    property?.title,
    property?.desc,
    property?.description,
    propertyType,
    period
  ].filter(Boolean).join(" ").toLowerCase();
  if (/\b(student|hostel|university|campus|bedsitter)\b/.test(text)) return "student";
  if (/\b(commercial|office|shop|retail|warehouse|showroom|restaurant|industrial)\b/.test(text)) return "commercial";
  if (/\b(land|plot|acre|decimal|estate plots?)\b/.test(text)) return "land";
  if (["mo", "month", "monthly", "per_month"].includes(period) || /\b(rent|rental|lease|per month|monthly)\b/.test(text)) return "rent";
  if (/\b(for sale|sale|selling|buy)\b/.test(text)) return "sale";
  return "sale";
}

function heroOpportunityStatRow(labelKey, value) {
  return `
    <div class="flex items-center justify-between gap-3 rounded-lg bg-white/10 px-2.5 py-1.5">
      <span class="text-white/80">${adminEscape(tr(labelKey))}</span>
      <strong class="text-green-200">${Number(value || 0).toLocaleString()}</strong>
    </div>`;
}

function renderHeroPropertyOpportunityCounter() {
  const subtitle = document.getElementById("hero-subtitle");
  if (!subtitle) return;
  const prefix = document.getElementById("hero-subtitle-prefix");
  const suffix = document.getElementById("hero-subtitle-suffix");
  const counter = document.getElementById("hero-property-counter");
  const count = document.getElementById("hero-property-count");
  const countLabel = document.getElementById("hero-property-count-label");
  const tooltip = document.getElementById("hero-property-counter-tooltip");
  const stats = getHeroPropertyOpportunityStats();
  const totalLabelKey = stats.total === 1 ? "heroSubtitleCountLabelSingular" : "heroSubtitleCountLabelPlural";
  if (prefix) prefix.textContent = tr("heroSubtitlePrefix");
  if (suffix) suffix.textContent = tr("heroSubtitleSuffix");
  if (count) count.textContent = Number(stats.total || 0).toLocaleString();
  if (countLabel) countLabel.textContent = tr(totalLabelKey);
  const tooltipText = [
    `${tr("heroCounterForSale")}: ${stats.sale}`,
    `${tr("heroCounterToRent")}: ${stats.rent}`,
    `${tr("heroCounterStudent")}: ${stats.student}`,
    `${tr("heroCounterCommercial")}: ${stats.commercial}`,
    `${tr("heroCounterLand")}: ${stats.land}`,
    ...(stats.other ? [`${tr("heroCounterOther")}: ${stats.other}`] : [])
  ].join(" · ");
  if (counter) {
    counter.setAttribute("title", tooltipText);
    counter.setAttribute("aria-label", `${Number(stats.total || 0).toLocaleString()} ${tr(totalLabelKey)}. ${tooltipText}`);
  }
  if (tooltip) {
    tooltip.innerHTML = `
      <div class="font-black text-green-100">${adminEscape(tr("heroCounterBreakdownTitle"))}</div>
      <div class="mt-2 grid gap-1.5">
        ${heroOpportunityStatRow("heroCounterForSale", stats.sale)}
        ${heroOpportunityStatRow("heroCounterToRent", stats.rent)}
        ${heroOpportunityStatRow("heroCounterStudent", stats.student)}
        ${heroOpportunityStatRow("heroCounterCommercial", stats.commercial)}
        ${heroOpportunityStatRow("heroCounterLand", stats.land)}
        ${stats.other ? heroOpportunityStatRow("heroCounterOther", stats.other) : ""}
      </div>
      <div class="mt-2 text-[11px] text-white/65">${adminEscape(tr("heroCounterTooltipNote"))}</div>`;
  }
}

