function applyMapAssistLanguageUI() {
  const pageLabels = {
    sale: "sale properties",
    rent: "rental properties",
    students: "student accommodation",
    commercial: "commercial property",
    land: "land",
    brokers: "brokers"
  };
  Object.keys(pageLabels).forEach((kind) => {
    const card = document.querySelector(`[data-map-assist-name="${kind}"]`)?.closest(".map-assist-card");
    if (card) {
      const title = card.querySelector(".font-bold");
      const copy = card.querySelector("p");
      const btn = card.querySelector("button");
      if (title) title.textContent = translateListingLabel(kind === "brokers" ? "Need help finding a broker?" : "Can't find what you're looking for?");
      if (copy) copy.textContent = translateListingLabel(kind === "brokers" ? "Tell us the district, property type, and how to reach you. makaug will help match you." : "Tell makaug what you need and we will follow up with matching homes or agents.");
      if (btn) btn.textContent = translateListingLabel("Ask makaug to help");
    }
    const setPlaceholder = (selector, text) => {
      const el = document.querySelector(selector);
      if (el && !el.value) el.placeholder = translateListingLabel(text);
    };
    setPlaceholder(`[data-map-assist-name="${kind}"]`, "Your name");
    setPlaceholder(`[data-map-assist-phone="${kind}"]`, "WhatsApp / phone");
    setPlaceholder(`[data-map-assist-email="${kind}"]`, "Email address");
    setPlaceholder(`[data-map-assist-location="${kind}"]`, kind === "brokers" ? "District or area" : "Location, district or street");
    setPlaceholder(`[data-map-assist-budget="${kind}"]`, kind === "rent" ? "Monthly budget (USh)" : kind === "students" ? "Budget per semester (USh)" : "Budget (USh)");
    setPlaceholder(`[data-map-assist-details="${kind}"]`, kind === "brokers" ? "What should the broker help with?" : "What are you looking for?");
    const wa = document.querySelector(`[data-map-assist-whatsapp="${kind}"]`);
    if (wa) {
      const current = wa.value || "yes";
      wa.innerHTML = [
        `<option value="yes">${translateListingLabel("This is my WhatsApp number")}</option>`,
        `<option value="no">${translateListingLabel("I use a different WhatsApp number")}</option>`
      ].join("");
      wa.value = current === "no" ? "no" : "yes";
    }
    const need = document.querySelector(`[data-map-assist-need="${kind}"]`);
    if (need) {
      const current = need.value || "";
      const options = [
        ["", "What are you looking for?"],
        ["For sale", "For sale"],
        ["To rent", "To rent"],
        ["Student accommodation", "Student accommodation"],
        ["Commercial property", "Commercial property"],
        ["Land", "Land"],
        ["Agent", "Agent"]
      ];
      need.innerHTML = options.map(([value, label]) => `<option value="${value}">${translateListingLabel(label)}</option>`).join("");
      need.value = options.some(([value]) => value === current) ? current : "";
    }
  });
}

function formatCompact(v) {
  if (v >= 1000000000) return (v / 1000000000).toFixed(1) + "B";
  if (v >= 1000000) return Math.round(v / 1000000) + "M";
  return v.toLocaleString();
}

function localizePricePeriod(period = "") {
  const raw = String(period || "").trim();
  if (!raw) return "";
  const key = raw.toLowerCase().replace(/[_-]/g, " ");
  const periodLabels = {
    mo: "month",
    monthly: "month",
    "per month": "month",
    month: "month",
    wk: "week",
    weekly: "week",
    "per week": "week",
    week: "week",
    yr: "year",
    yearly: "year",
    "per year": "year",
    year: "year",
    once: "once",
    total: "once",
    acre: "acre",
    plot: "plot",
    semester: "semester",
    sem: "semester"
  };
  return translateListingLabel(periodLabels[key] || raw);
}

function fmtP(v, p) {
  const numeric = Number(v);
  if (!Number.isFinite(numeric) || numeric <= 0) return translateListingLabel("Price upon application");
  return (CURRENCIES[activeCur] || CURRENCIES.UGX).fmt(numeric, localizePricePeriod(p));
}

