function persistAdminApiKey(value) {
  const next = String(value || "").trim();
  adminApiKey = next;
  try {
    if (next) localStorage.setItem(ADMIN_API_KEY_STORAGE_KEY, next);
    else localStorage.removeItem(ADMIN_API_KEY_STORAGE_KEY);
  } catch (e) {}
}

