function setBrokerDashboardActiveTab(targetHash = "#broker-overview-panel") {
  document.querySelectorAll("#broker-dashboard-tabs a[href^='#broker-']").forEach((link) => {
    const active = link.getAttribute("href") === targetHash;
    link.classList.toggle("bg-green-700", active);
    link.classList.toggle("text-white", active);
    link.classList.toggle("bg-gray-50", !active);
    link.classList.toggle("text-gray-700", !active);
  });
}

function wireBrokerDashboardTabs() {
  const tabs = document.getElementById("broker-dashboard-tabs");
  if (!tabs || tabs.dataset.wired === "true") {
    setBrokerDashboardActiveTab(window.location.hash && window.location.hash.startsWith("#broker-") ? window.location.hash : "#broker-overview-panel");
    return;
  }
  tabs.dataset.wired = "true";
  tabs.querySelectorAll("a[href^='#broker-']").forEach((link) => {
    link.addEventListener("click", (event) => {
      event.preventDefault();
      const targetHash = link.getAttribute("href") || "#broker-overview-panel";
      const target = document.querySelector(targetHash);
      setBrokerDashboardActiveTab(targetHash);
      if (target) target.scrollIntoView({ behavior: "smooth", block: "start" });
      try {
        window.history.replaceState({ page: "broker-dashboard", source: "broker_dashboard_tab" }, "", `/broker-dashboard${targetHash}`);
      } catch (_) {}
    });
  });
  setBrokerDashboardActiveTab(window.location.hash && window.location.hash.startsWith("#broker-") ? window.location.hash : "#broker-overview-panel");
}

function openBrokerBoostPlanner(listingId = "") {
  renderBrokerBoostPanel(listingId);
  setBrokerDashboardActiveTab("#broker-boost-panel");
  document.getElementById("broker-boost-panel")?.scrollIntoView({ behavior: "smooth", block: "start" });
}

async function shareBrokerListing(id) {
  const listing = (brokerDashboardCache?.listings || []).find((item) => String(item.id) === String(id));
  if (!listing) {
    toast("Listing not found.");
    return;
  }
  const text = `${listing.title || "makaug property"}\n${[listing.area, listing.district].filter(Boolean).join(", ")}\n${fmtP(listing.price || 0, listing.period || listing.price_period || "")}\n${getPropertyShareUrl(listing)}`;
  try {
    if (navigator.share) {
      await navigator.share({ title: listing.title || "makaug property", text, url: getPropertyShareUrl(listing) });
      return;
    }
    const copied = await copyTextToClipboard(text);
    toast(copied ? "Listing share text copied." : "Unable to copy listing right now.");
  } catch (_) {
    toast("Unable to share listing right now.");
  }
}

function editBrokerListing(id) {
  const listing = (brokerDashboardCache?.listings || []).find((item) => String(item.id) === String(id));
  startBrokerOnlineListing();
  toast(listing ? `Opening broker upload for edits to ${listing.title || "this listing"}. makaug review still applies.` : "Opening broker upload. makaug review still applies.");
}

function requestBrokerListingRemoval(id) {
  const listing = (brokerDashboardCache?.listings || []).find((item) => String(item.id) === String(id));
  const title = listing?.title || "this listing";
  toast(`Removal request noted for ${title}. makaug admin approval is required before public changes.`);
}

function polishBrokerBioDraft() {
  const name = (document.getElementById("broker-settings-full-name")?.value || brokerDashboardCache?.broker?.name || "I").trim();
  const company = (document.getElementById("broker-settings-company")?.value || "independent broker").trim();
  const areas = (document.getElementById("broker-settings-areas")?.value || "Uganda").trim();
  const specs = (document.getElementById("broker-settings-specializations")?.value || "rentals, sales, and verified property support").trim();
  const draft = `${name} is a ${company} on makaug.com, helping property seekers across ${areas}. I specialise in ${specs}, respond quickly on WhatsApp, and keep listings clear, current, and ready for makaug review.`;
  const bio = document.getElementById("broker-settings-bio");
  if (bio) bio.value = draft;
  renderBrokerSettingsLivePreview(brokerDashboardCache?.broker || {}, brokerDashboardCache?.listings || [], brokerDashboardCache?.payload?.stats || {});
  toast("Bio draft polished. Review it before saving.");
}

function hydrateBrokerSettingsForm(broker = {}) {
  const set = (id, value) => {
    const el = document.getElementById(id);
    if (el && document.activeElement !== el) el.value = value || "";
  };
  set("broker-settings-full-name", broker.name || "");
  set("broker-settings-company", broker.company || "");
  set("broker-settings-whatsapp", brokerDisplayPhone(broker));
  set("broker-settings-areas", Array.isArray(broker.districts_covered) ? broker.districts_covered.join(", ") : (broker.area || ""));
  set("broker-settings-specializations", Array.isArray(broker.specializations) ? broker.specializations.join(", ") : (broker.specialties || []).join(", "));
  set("broker-settings-bio", broker.bio || "");
  const preview = document.getElementById("broker-settings-photo-preview");
  const photo = brokerSettingsPhotoDataUrl || broker.photo || broker.profile_photo_url || "";
  if (preview) {
    preview.innerHTML = photo
      ? `<img src="${adminAttr(photo)}" alt="Broker profile photo" class="w-full h-full object-cover">`
      : adminEscape(brokerInitials(broker.name));
  }
  renderBrokerSettingsLivePreview(broker, brokerDashboardCache?.listings || [], brokerDashboardCache?.payload?.stats || {});
}

async function handleBrokerSettingsPhoto(event) {
  const file = event?.target?.files?.[0];
  if (!file) return;
  if (!file.type || !file.type.startsWith("image/")) {
    toast("Choose an image for your broker profile photo.");
    event.target.value = "";
    return;
  }
  try {
    brokerSettingsPhotoDataUrl = await compressPhotoForSubmission(file, { maxSide: 700, quality: 0.76 });
    hydrateBrokerSettingsForm(brokerDashboardCache?.broker || {});
  } catch (error) {
    toast("Could not read that profile photo. Please try another image.");
    event.target.value = "";
  }
}

async function saveBrokerProfileSettings() {
  const statusEl = document.getElementById("broker-settings-status");
  const payload = {
    full_name: (document.getElementById("broker-settings-full-name")?.value || "").trim(),
    company_name: (document.getElementById("broker-settings-company")?.value || "").trim(),
    whatsapp: normalizePhoneInput(document.getElementById("broker-settings-whatsapp")?.value || ""),
    districts_covered: (document.getElementById("broker-settings-areas")?.value || "").trim(),
    specializations: (document.getElementById("broker-settings-specializations")?.value || "").trim(),
    bio: (document.getElementById("broker-settings-bio")?.value || "").trim(),
    profile_photo_url: brokerSettingsPhotoDataUrl || brokerDashboardCache?.broker?.photo || ""
  };
  if (statusEl) {
    statusEl.className = "rounded-xl border border-blue-100 bg-blue-50 px-3 py-2 text-sm text-blue-900";
    statusEl.textContent = "Saving broker profile...";
    statusEl.classList.remove("hidden");
  }
  try {
    const res = await apiRequest("/api/agents/me", { method: "PATCH", body: payload });
    brokerSettingsPhotoDataUrl = "";
    const updated = mapRemoteAgentForUi(res?.data || {});
    brokerDashboardCache = { ...(brokerDashboardCache || {}), broker: updated };
    if (statusEl) {
      statusEl.className = "rounded-xl border border-green-100 bg-green-50 px-3 py-2 text-sm text-green-900";
      statusEl.textContent = "Broker profile saved. Public card updates after makaug review rules are applied.";
    }
    await renderAgentDashboard();
  } catch (error) {
    if (statusEl) {
      statusEl.className = "rounded-xl border border-red-100 bg-red-50 px-3 py-2 text-sm text-red-900";
      statusEl.textContent = error.message || "Could not save broker profile.";
    }
    toast(error.message || "Could not save broker profile.");
  }
}

