function staffSourceImportUrlCount(text = "") {
  return (String(text || "").match(/https?:\/\/[^\s<>"']+/gi) || []).length;
}

function staffSourceImportPayload(dryRun = true) {
  const rawText = document.getElementById("staff-source-quick-paste")?.value || "";
  const metadataEnabled = staffSourceImportUrlCount(rawText) <= 20;
  return {
    raw_text: rawText,
    dry_run: dryRun,
    fetch_oembed: metadataEnabled,
    fetch_public_metadata: metadataEnabled
  };
}

function renderStaffSourceImportResult(data = {}, dryRun = true) {
  const wrap = document.getElementById("staff-source-import-result");
  if (!wrap) return;
  const result = data || {};
  if (result.async_job) {
    const summary = result.result_summary || {};
    const status = String(result.status || "queued").toLowerCase();
    const completed = status === "completed";
    const failed = status === "failed";
    const toneClass = failed
      ? { box: "border-red-100 bg-red-50", text: "text-red-900" }
      : completed
        ? { box: "border-emerald-100 bg-emerald-50", text: "text-emerald-900" }
        : { box: "border-amber-100 bg-amber-50", text: "text-amber-900" };
    const title = failed
      ? "Background import failed"
      : completed
        ? "Background import complete"
        : "Background import running";
    wrap.innerHTML = `
      <div class="rounded-xl border ${toneClass.box} p-3 text-xs">
        <div class="font-black ${toneClass.text}">${title}</div>
        <div class="mt-1 ${toneClass.text}">${adminEscape(result.message || "Source intake job is being processed.")}</div>
        <div class="mt-2 grid sm:grid-cols-2 gap-2 text-gray-700">
          <div>Job ID: <strong>${adminEscape(result.job_id || "-")}</strong></div>
          <div>Status: <strong>${adminEscape(result.status || "queued")}</strong></div>
          <div>Batch inputs: <strong>${staffNumber(result.exact_input_count || 0)}</strong></div>
          <div>Source batch: <strong>${staffNumber(result.requested_source_count || 0)}</strong></div>
          <div>Discovered posts: <strong>${staffNumber(summary.discovered_posts_count || 0)}</strong></div>
          <div>Auto-live properties: <strong>${staffNumber(summary.auto_live_properties || 0)}</strong></div>
          <div>Created properties: <strong>${staffNumber(summary.created_properties || 0)}</strong></div>
          <div>Existing/duplicates blocked: <strong>${staffNumber(summary.existing_properties || 0)}</strong></div>
          <div>Review queue rows: <strong>${staffNumber(summary.review_queue_properties || 0)}</strong></div>
          <div>Low-signal source rows: <strong>${staffNumber(summary.low_signal_source_location_count || 0)}</strong></div>
          <div>Source-review only: <strong>${staffNumber(summary.source_review_count || 0)}</strong></div>
        </div>
        ${result.error ? `<div class="mt-2 rounded-lg bg-white border border-red-100 p-2 text-red-800">${adminEscape(result.error)}</div>` : ""}
        <div class="mt-2 text-gray-600">${completed ? "Refresh the queue when ready; the click path stayed async so the dashboard does not freeze." : "Keep working. makaug will poll this job without blocking the dashboard."}</div>
      </div>`;
    return;
  }
  const importResult = result.import_result || result;
  const autoLiveCount = importResult.auto_live_properties || result.auto_live_properties || 0;
  const metadataNote = result.metadata_skipped_for_large_batch
    ? `<div class="mt-2 rounded-lg border border-amber-100 bg-amber-50 p-2 text-amber-900">Large batch mode: external metadata fetches were skipped for speed. Paste title, location, price, posted date, phone, and visible source text under each exact link before queueing.</div>`
    : "";
  wrap.innerHTML = `
    <div class="rounded-xl border ${dryRun ? "border-violet-100 bg-violet-50" : "border-emerald-100 bg-emerald-50"} p-3 text-xs">
      <div class="font-black ${dryRun ? "text-violet-900" : "text-emerald-900"}">${dryRun ? "Preview complete" : "Import complete"}</div>
      <div class="grid sm:grid-cols-2 gap-2 mt-2 text-gray-700">
        <div>Exact social URLs: <strong>${staffNumber(result.exact_social_url_count || result.exact_video_url_count || 0)}</strong></div>
        <div>Batch inputs: <strong>${staffNumber(result.exact_input_count || result.exact_social_url_count || 0)}</strong> / 500</div>
        <div>Created properties: <strong>${staffNumber(importResult.created_properties || result.created_properties || 0)}</strong></div>
        <div>Auto-live properties: <strong>${staffNumber(autoLiveCount)}</strong></div>
        <div>Existing/duplicates blocked: <strong>${staffNumber(importResult.existing_properties || result.existing_properties || 0)}</strong></div>
        <div>Review queue rows: <strong>${staffNumber(importResult.review_queue_properties || result.review_queue_properties || 0)}</strong></div>
        <div>Source-review only: <strong>${staffNumber(importResult.source_review_count || result.source_review_count || 0)}</strong></div>
        <div>Discovered posts: <strong>${staffNumber(result.discovered_posts_count || 0)}</strong></div>
      </div>
      ${metadataNote}
      <div class="mt-2 text-gray-600">${dryRun ? "If the preview looks right, queue it. Hashtag rows that pass location/date/category/source-contact checks can go live immediately." : "Auto-live rows are public now; pending rows stay in shared review."}</div>
    </div>`;
}

function scheduleStaffSourceJobPoll(jobId = "", attempt = 0) {
  if (staffSourceIntakePollTimer) window.clearTimeout(staffSourceIntakePollTimer);
  const id = String(jobId || "").trim();
  if (!id || attempt > 40) return;
  staffSourceIntakePollTimer = window.setTimeout(() => {
    staffPollSourceIntakeJob(id, attempt + 1);
  }, STAFF_SOURCE_INTAKE_POLL_MS);
}

async function staffPollSourceIntakeJob(jobId = "", attempt = 0) {
  const id = String(jobId || "").trim();
  if (!id) return;
  try {
    const res = await staffApiRequestWithTimeout(
      `/api/staff/source-intake/jobs/${encodeURIComponent(id)}`,
      {},
      STAFF_SOURCE_INTAKE_POLL_TIMEOUT_MS,
      "Staff source intake job status"
    );
    const data = res?.data || {};
    renderStaffSourceImportResult(data, false);
    const status = String(data.status || "").toLowerCase();
    if (status === "completed") {
      toast("Source import completed in the background.");
      return;
    }
    if (status === "failed") {
      toast(`Source import failed: ${data.error || "check job status"}`);
      return;
    }
    scheduleStaffSourceJobPoll(id, attempt);
  } catch (error) {
    if (attempt < 8) {
      scheduleStaffSourceJobPoll(id, attempt);
    } else {
      toast(`Source import status check timed out: ${error.message || "request failed"}`);
    }
  }
}

async function staffPreviewSourceImport() {
  const payload = staffSourceImportPayload(true);
  if (!payload.raw_text.trim()) {
    toast("Paste exact social links or copied source text first.");
    return;
  }
  try {
    const res = await apiRequest("/api/staff/source-intake/exact-social/import", {
      method: "POST",
      body: payload
    });
    renderStaffSourceImportResult(res?.data || {}, true);
    toast("Source preview ready.");
  } catch (error) {
    toast(`Source preview failed: ${error.message || "request failed"}`);
  }
}

async function staffQueueSourceImport() {
  const payload = staffSourceImportPayload(false);
  if (!payload.raw_text.trim()) {
    toast("Paste exact social links or copied source text first.");
    return;
  }
  payload.async_job = true;
  renderStaffSourceImportResult({
    async_job: true,
    status: "queued",
    exact_input_count: staffSourceImportUrlCount(payload.raw_text),
    message: "Submitting background source import..."
  }, false);
  try {
    const res = await staffApiRequestWithTimeout(
      "/api/staff/source-intake/exact-social/import",
      {
        method: "POST",
        body: payload
      },
      STAFF_SOURCE_INTAKE_SUBMIT_TIMEOUT_MS,
      "Staff source import submit"
    );
    const data = res?.data || {};
    renderStaffSourceImportResult(data, false);
    if (data.job_id) scheduleStaffSourceJobPoll(data.job_id, 0);
    toast(data.job_id ? "Source import accepted in the background." : "Source rows queued into shared review.");
  } catch (error) {
    toast(`Source queue failed: ${error.message || "request failed"}`);
  }
}

function staffSweepOffsetKey(mode = "") {
  const suffix = String(mode || "agency").replace(/[^a-z0-9_-]+/gi, "_").toLowerCase() || "agency";
  return `${STAFF_SOURCE_SWEEP_OFFSET_KEY}.${suffix}`;
}

function staffStoredSweepOffset(mode = "") {
  try {
    const key = staffSweepOffsetKey(mode);
    const shouldReadLegacyCursor = !mode || mode === "agency";
    const raw = localStorage.getItem(key) || (shouldReadLegacyCursor ? localStorage.getItem(STAFF_SOURCE_SWEEP_OFFSET_KEY) : "");
    const parsed = Number(raw);
    return Number.isFinite(parsed) && parsed >= 0 ? Math.round(parsed) : 0;
  } catch (_) {
    return 0;
  }
}

function staffStoreSweepOffset(value = 0, mode = "") {
  try {
    localStorage.setItem(staffSweepOffsetKey(mode), String(Math.max(0, Math.round(Number(value) || 0))));
  } catch (_) {}
}

function staffAdvanceSweepOffsetFromResult(result = {}, currentOffset = 0, mode = "", fallbackStep = STAFF_SOURCE_SWEEP_BATCH_SIZE) {
  const youtube = result.youtube || {};
  const sourceCount = Number(youtube.source_count || 0);
  const jobCount = Number(youtube.search_job_count || result.requested_source_count || fallbackStep);
  if (!jobCount) return currentOffset;
  const nextOffset = sourceCount > 0
    ? (Number(currentOffset || 0) + jobCount) % sourceCount
    : Number(currentOffset || 0) + jobCount;
  staffStoreSweepOffset(nextOffset, mode);
  return nextOffset;
}

function staffSourceSweepProfile(profile = "agency") {
  const normalized = String(profile || "agency").toLowerCase();
  if (normalized === "deep_agency" || normalized === "deep") {
    return {
      key: "deep_agency",
      label: "Deep agency uploads",
      platform: "youtube",
      youtubeJobMode: "channel_uploads",
      maxSources: STAFF_SOURCE_DEEP_SWEEP_BATCH_SIZE,
      maxResults: STAFF_SOURCE_DEEP_SWEEP_MAX_RESULTS,
      maxPages: STAFF_SOURCE_DEEP_SWEEP_MAX_PAGES,
    };
  }
  if (normalized === "broad_search" || normalized === "search") {
    return {
      key: "broad_search",
      label: "Broad hashtag/search",
      platform: "youtube",
      youtubeJobMode: "search",
      maxSources: STAFF_SOURCE_SEARCH_SWEEP_BATCH_SIZE,
      maxResults: STAFF_SOURCE_SEARCH_SWEEP_MAX_RESULTS,
      maxPages: STAFF_SOURCE_SEARCH_SWEEP_MAX_PAGES,
    };
  }
  return {
    key: "agency",
    label: "High-yield agency uploads",
    platform: document.getElementById("staff-source-sweep-platform")?.value || "all",
    youtubeJobMode: document.getElementById("staff-source-sweep-youtube-mode")?.value || "channel_uploads",
    maxSources: STAFF_SOURCE_SWEEP_BATCH_SIZE,
    maxResults: STAFF_SOURCE_SWEEP_MAX_RESULTS,
    maxPages: STAFF_SOURCE_SWEEP_MAX_PAGES,
  };
}

async function staffRunSourceSweep(dryRun = true, profile = "agency") {
  const sweepProfile = staffSourceSweepProfile(profile);
  const platform = sweepProfile.platform;
  const focus = document.getElementById("staff-source-sweep-focus")?.value || "";
  const youtubeJobMode = sweepProfile.youtubeJobMode;
  const sourceOffset = staffStoredSweepOffset(sweepProfile.key);
  const requestedSourceCount = dryRun ? Math.min(12, sweepProfile.maxSources) : sweepProfile.maxSources;
  renderStaffSourceImportResult({
    async_job: !dryRun,
    status: dryRun ? "running" : "queued",
    requested_source_count: requestedSourceCount,
    message: dryRun
      ? `Previewing ${sweepProfile.label.toLowerCase()} from source offset ${sourceOffset}...`
      : `Submitting ${sweepProfile.label.toLowerCase()} from source offset ${sourceOffset}...`
  }, dryRun);
  try {
    const res = await staffApiRequestWithTimeout(
      "/api/staff/source-intake/social-sweep",
      {
        method: "POST",
        body: {
          platform,
          focus,
          dry_run: dryRun,
          async_job: !dryRun,
          max_sources: requestedSourceCount,
          source_offset: sourceOffset,
          max_results: dryRun ? Math.min(10, sweepProfile.maxResults) : sweepProfile.maxResults,
          max_pages: dryRun ? 1 : sweepProfile.maxPages,
          published_after: "2026-01-01T00:00:00.000Z",
          youtube_job_mode: youtubeJobMode
        }
      },
      dryRun ? STAFF_SOURCE_INTAKE_POLL_TIMEOUT_MS : STAFF_SOURCE_INTAKE_SUBMIT_TIMEOUT_MS,
      "Staff source sweep submit"
    );
    const data = res?.data || {};
    renderStaffSourceImportResult(data, dryRun);
    if (dryRun) {
      staffAdvanceSweepOffsetFromResult(data, sourceOffset, sweepProfile.key, requestedSourceCount);
    } else if (data.job_id) {
      scheduleStaffSourceJobPoll(data.job_id, 0);
      staffStoreSweepOffset(sourceOffset + requestedSourceCount, sweepProfile.key);
    }
    toast(dryRun ? "Sweep preview ready." : "Source sweep accepted in the background.");
  } catch (error) {
    toast(`Source sweep failed: ${error.message || "request failed"}`);
  }
}

