async function submitAdvertiserDashboardCampaign(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const status = document.getElementById("advertiser-dashboard-campaign-status");
  const data = new FormData(form);
  const goal = String(data.get("goal") || "listing_promotion");
  const payload = {
    full_name: String(data.get("full_name") || "").trim(),
    business_name: String(data.get("business_name") || "").trim(),
    email: String(data.get("email") || authState?.user?.email || "").trim(),
    phone: normalizePhoneInput(data.get("phone") || authState?.user?.phone || ""),
    preferred_contact_channel: "whatsapp",
    product_interests: [goal],
    target_locations: String(data.get("target_locations") || "").trim(),
    target_listing_types: goal,
    budget_ugx: String(data.get("budget_ugx") || "").trim(),
    desired_duration_days: String(data.get("desired_duration_days") || "").trim(),
    message: String(data.get("message") || "").trim(),
    source: "advertiser_dashboard"
  };
  if (!payload.email && !payload.phone) {
    toast("Add an email or WhatsApp number so makaug can reply.");
    return;
  }
  try {
    const submit = form.querySelector("button[type='submit']");
    if (submit) {
      submit.disabled = true;
      submit.textContent = "Submitting...";
    }
    const result = await apiRequest("/api/advertising/campaigns", {
      method: "POST",
      body: {
        ...payload,
        campaign_name: `${payload.business_name || payload.full_name || "Advertiser"} makaug campaign`,
        package_key: goal,
        creative_brief: payload.message
      }
    });
    let paymentState = "";
    try {
      const campaignId = result?.data?.campaign?.id;
      if (campaignId) {
        const payment = await apiRequest(`/api/advertising/campaigns/${encodeURIComponent(campaignId)}/payment-link`, {
          method: "POST",
          body: { amount: payload.budget_ugx || result?.data?.campaign?.quoted_amount_ugx || 0 }
        });
        paymentState = payment?.data?.providerMissing
          ? "<br>Payment: provider not configured yet, manual invoice logged for admin."
          : `<br>Payment link: <a class="underline font-bold" href="${adminAttr(payment?.data?.paymentLink?.checkout_url || "#")}" target="_blank" rel="noopener noreferrer">Open payment</a>`;
        const payments = document.getElementById("advertiser-dashboard-payments");
        if (payments) payments.innerHTML = payment?.data?.providerMissing ? "Manual invoice logged. makaug will confirm payment instructions." : "Payment link generated.";
      }
    } catch (paymentError) {
      paymentState = "<br>Payment: request logged; makaug will confirm payment details.";
    }
    if (status) {
      status.classList.remove("hidden");
      status.innerHTML = `Campaign request received.<br>Reference: <strong>${adminEscape(result?.data?.campaign?.id || result?.data?.inquiry?.id || "pending")}</strong>${paymentState}<br>makaug will review the creative before any placement goes live.`;
    }
    setTextById("advertiser-stat-campaigns", "1");
    setTextById("advertiser-stat-payment", "Pending review");
    toast("Advertising campaign request submitted.");
    form.reset();
  } catch (e) {
    toast(`Campaign request failed: ${e.message || "error"}`);
  } finally {
    const submit = form.querySelector("button[type='submit']");
    if (submit) {
      submit.disabled = false;
      submit.textContent = "Submit Campaign Request";
    }
  }
}

function normalizeModerationStatus(status) {
  const raw = String(status || "").toLowerCase();
  if (["approved", "live", "published"].includes(raw)) return "approved";
  if (["sold", "completed"].includes(raw)) return "sold";
  if (["rejected", "declined", "fraud"].includes(raw)) return "rejected";
  if (["pending", "pending_review", "test_pending_review", "pending_review_hidden", "under_review", "submitted", "draft", "in_review"].includes(raw)) return "pending";
  if (["hidden", "off_market", "paused", "archived"].includes(raw)) return "hidden";
  if (["deleted", "removed", "trash"].includes(raw)) return "deleted";
  return raw || "unknown";
}

function isListingPublicVisible(property) {
  if (adminRecordLooksLikeTest(property)) return false;
  const status = normalizeModerationStatus(property?.status);
  return status === "approved";
}

function adminIsPublicLiveAdminListing(property = {}) {
  if (property.public_visible === false) return false;
  return isListingPublicVisible(property);
}

function adminLiveEndpointRows(listings = []) {
  const rows = Array.isArray(listings) ? listings : [];
  if (rows.some((row) => row?.admin_live_endpoint === true)) {
    return rows.filter((row) => row?.public_visible !== false);
  }
  return adminApplyLaunchCleanFilter(rows).filter(adminIsPublicLiveAdminListing);
}

function isLocalDevelopmentHost() {
  try {
    const host = String(window.location.hostname || "").toLowerCase();
    return !host || host === "localhost" || host === "127.0.0.1" || host === "0.0.0.0" || host === "::1";
  } catch (error) {
    return false;
  }
}

function publicSampleListingsEnabled() {
  try {
    return window.MAKAUG_ALLOW_SAMPLE_LISTINGS === true && isLocalDevelopmentHost();
  } catch (error) {
    return false;
  }
}

function isBackendControlledListing(property) {
  const backendId = String(property?.backend_id || "").trim();
  return property?.remote_source === "api"
    || property?.backend_controlled === true
    || property?.owner_preview_visible === true
    || backendId.length > 0;
}

function getPublicListings() {
  return PROPERTIES.filter((p) => (
    isListingPublicVisible(p)
    && (isBackendControlledListing(p) || publicSampleListingsEnabled())
  ));
}

function isFeaturedListing(property) {
  return property?.featured === true || String(property?.extra_fields?.featured || "").toLowerCase() === "true";
}

function getFeaturedListings(listings) {
  const source = publicListingsFromApiLoaded
    ? listings.filter((p) => p.remote_source === "api" || isFeaturedListing(p))
    : listings;
  return source
    .filter((p) => isFeaturedListing(p))
    .sort((a, b) => {
      const ad = parseDateSafe(a.featured_at || a.extra_fields?.featured_at || a.updated_at || a.created_at)?.getTime() || 0;
      const bd = parseDateSafe(b.featured_at || b.extra_fields?.featured_at || b.updated_at || b.created_at)?.getTime() || 0;
      return bd - ad;
    });
}

function getHomepageFeaturedListings(publicListings = []) {
  const featuredListings = publicFeaturedListingsFromApi.length
    ? publicFeaturedListingsFromApi
    : getFeaturedListings(publicListings);
  return featuredListings.length
    ? featuredListings
    : publicListings.slice().sort(sortListingsByNewest);
}

function getKnownUsersForAdmin() {
  const map = {};
  PROPERTIES.forEach((p) => {
    const email = String(p?.lister_email || "").toLowerCase();
    const phone = normalizePhoneInput(p?.lister_phone || "");
    const key = email || phone;
    if (!key) return;
    if (!map[key]) {
      map[key] = {
        id: key,
        first_name: p?.contact_display_name || p?.lister_display_name || p?.lister_name || "Property",
        last_name: "Lister",
        email: email || "",
        phone: phone || "",
        role: "property_owner",
        status: "active",
        created_at: p?.created_at || null
      };
    }
  });
  if (authState?.user?.id) {
    map[authState.user.id] = {
      id: authState.user.id,
      first_name: authState.user.first_name || "",
      last_name: authState.user.last_name || "",
      phone: authState.user.phone || "",
      email: authState.user.email || "",
      role: authState.user.role || "buyer_renter",
      status: authState.user.status || "active",
      marketing_opt_in: authState.user.marketing_opt_in !== false,
      weekly_tips_opt_in: authState.user.weekly_tips_opt_in !== false,
      preferred_contact_channel: authState.user.preferred_contact_channel || "whatsapp",
      created_at: authState.user.created_at || null
    };
  }
  return Object.values(map);
}

function buildLocalAdminSnapshot() {
  const allListings = PROPERTIES
    .filter((p) => isBackendControlledListing(p) || publicSampleListingsEnabled())
    .map((p) => ({
      ...p,
      moderation_status: normalizeModerationStatus(p.status)
    }));
  allListings.sort((a, b) => {
    const ad = parseDateSafe(a.created_at || a.updated_at)?.getTime() || 0;
    const bd = parseDateSafe(b.created_at || b.updated_at)?.getTime() || 0;
    return bd - ad;
  });
  const listings = allListings.filter((p) => p.moderation_status !== "deleted");
  const pendingListings = listings.filter(adminIsPendingReviewSeedItem).slice(0, 50);
  const approvedListings = listings.filter((p) => p.moderation_status === "approved");
  const rejectedListings = listings.filter((p) => p.moderation_status === "rejected");
  const hiddenListings = listings.filter((p) => p.moderation_status === "hidden");
  const deletedListings = allListings.filter((p) => p.moderation_status === "deleted");
  const users = getKnownUsersForAdmin();
  const totalViews = listings.reduce((sum, p) => sum + getPropertyViewCount(p.id), 0);
  const totalSaves = listings.reduce((sum, p) => sum + getPropertySaveCount(p.id), 0);
  const totalBrokerViews = Object.values(siteMetrics?.brokerProfileViews || {}).reduce((sum, n) => sum + (parseInt(n || 0, 10) || 0), 0);
  const privateListings = listings.filter((p) => listingSourceMeta(p).key === "private").length;
  const agentListings = listings.length - privateListings;
  const studentDiscoverableListings = listings.filter((p) => isStudentDiscoverable(p)).length;
  const brokerDirectory = getBrokerDirectory();
  const registeredAgents = brokerDirectory.filter((b) => String(b.registration_status || "").toLowerCase() === "registered").length;
  const notRegisteredAgents = Math.max(0, brokerDirectory.length - registeredAgents);
  const approvalRate = listings.length ? Math.round((approvedListings.length / listings.length) * 100) : 0;
  const rejectionRate = listings.length ? Math.round((rejectedListings.length / listings.length) * 100) : 0;
  const avgViewsPerListing = listings.length ? Math.round((totalViews / listings.length) * 10) / 10 : 0;
  const saveToViewRatio = totalViews ? Math.round((totalSaves / totalViews) * 100) : 0;
  return {
    summary: {
      totalListings: listings.length,
      pendingListings: pendingListings.length,
      approvedListings: approvedListings.length,
      rejectedListings: rejectedListings.length,
      hiddenListings: hiddenListings.length,
      deletedListings: deletedListings.length,
      totalAgents: brokerDirectory.length,
      totalUsers: users.length,
      totalViews,
      totalSaves,
      totalBrokerViews,
      privateListings,
      agentListings,
      studentDiscoverableListings,
      registeredAgents,
      notRegisteredAgents,
      approvalRate,
      rejectionRate,
      avgViewsPerListing,
      saveToViewRatio
    },
    users,
    pendingListings,
    liveListings: approvedListings.slice(0, 50),
    allListings,
    recentUsers: users.slice(0, 10),
    recentAgents: brokerDirectory.slice(0, 10),
    recentReports: [],
    agents: brokerDirectory,
    fieldAgents: users.filter((user) => user.role === "field_agent").slice(0, 20),
    propertyRequests: [],
    whatsappSummary: {
      total_conversations: 0,
      active_7d: 0,
      needs_human: 0,
      resolved: 0,
      autopilot: 0,
      copilot: 0,
      manual_only: 0
    },
    whatsappConversations: []
  };
}

function buildLocalAdminAreaInsights(listings = []) {
  const counts = {};
  (listings || []).forEach((p) => {
    const key = [p.area, p.district].filter(Boolean).join(", ") || "Unknown area";
    counts[key] = (counts[key] || 0) + getPropertyViewCount(p.id);
  });
  return Object.entries(counts)
    .map(([area, events]) => ({ area, events }))
    .sort((a, b) => b.events - a.events)
    .slice(0, 5);
}

function buildAdminAiSnapshot(remoteSnap, localSnap, sourceLabel = "") {
  const summary = remoteSnap?.summary || {};
  const insights = summary?.ai_insights || {};
  const users = summary?.users || {};
  const engagement = summary?.engagement || {};
  const localSummary = localSnap?.summary || {};
  const topAreas = Array.isArray(insights.top_areas) && insights.top_areas.length
    ? insights.top_areas
    : buildLocalAdminAreaInsights(localSnap?.allListings || []);
  const topListingTypes = Array.isArray(insights.top_listing_types) ? insights.top_listing_types : [];
  return {
    source: sourceLabel || "Dashboard data",
    views48h: Number(insights.last_48h?.property_views ?? 0),
    visitors48h: Number(insights.last_48h?.unique_visitors ?? 0),
    routeEvents48h: Number(insights.last_48h?.route_events ?? 0),
    inquiries48h: Number(insights.last_48h?.property_inquiries ?? 0),
    totalViews: Number(engagement.property_views ?? localSummary.totalViews ?? 0),
    totalSaves: Number(engagement.property_saves ?? localSummary.totalSaves ?? 0),
    weeklyTips: Number(users.weekly_tips_opt_in ?? (localSnap?.recentUsers || []).filter((u) => u.weekly_tips_opt_in !== false).length ?? 0),
    totalUsers: Number(users.total ?? localSummary.totalUsers ?? 0),
    pendingListings: Number(summary?.properties?.pending ?? localSummary.pendingListings ?? 0),
    approvedListings: Number(summary?.properties?.public_live ?? summary?.properties?.approved ?? localSummary.approvedListings ?? 0),
    topAreas,
    topListingTypes
  };
}

function renderAdminAiAssistant(remoteSnap, localSnap, sourceLabel = "") {
  adminAiSnapshot = buildAdminAiSnapshot(remoteSnap, localSnap, sourceLabel);
  const setText = (id, value) => {
    const el = document.getElementById(id);
    if (el) el.textContent = String(value);
  };
  setText("admin-ai-views-48h", adminAiSnapshot.views48h);
  setText("admin-ai-visitors-48h", adminAiSnapshot.visitors48h);
  setText("admin-ai-weekly-tips", adminAiSnapshot.weeklyTips);
  setText("admin-ai-top-area", adminAiSnapshot.topAreas[0]?.area || "-");
  setText("admin-ai-source", remoteSnap ? "Live data" : "Local data");
  const answer = document.getElementById("admin-ai-answer");
  if (answer) {
    answer.innerHTML = `
      <div class="font-semibold text-gray-900">Snapshot ready.</div>
      <div class="mt-1">Last 48h: <strong>${adminAiSnapshot.views48h}</strong> property views, <strong>${adminAiSnapshot.visitors48h}</strong> visitors, <strong>${adminAiSnapshot.routeEvents48h}</strong> direction opens, and <strong>${adminAiSnapshot.inquiries48h}</strong> enquiries.</div>
      <div class="mt-1">Top area: <strong>${adminEscape(adminAiSnapshot.topAreas[0]?.area || "not enough data yet")}</strong>.</div>`;
  }
}

function adminFormatUgx(value) {
  return `UGX ${Number(value || 0).toLocaleString("en-UG")}`;
}

function adminCommandSelectorForTab(tab = "review") {
  const map = {
    review: "#admin-review-queue-control",
    actioned: "#admin-actioned-listings-control",
    live: "#admin-live-followup-control",
    accounts: "#admin-accounts-control",
    staff: "#admin-staff-control",
    "field-agents": "#admin-field-agent-control",
    ads: "#admin-advertising-control",
    whatsapp: "#admin-whatsapp-control",
    notifications: "#admin-notifications-control",
    listings: "#admin-listings-control"
  };
  return map[tab] || "#admin-workflow-tabs";
}

function adminBuildCommandCentre(remoteSnap, localSnap) {
  const command = remoteSnap?.commandCentre || {};
  const metrics = command.metrics || {};
  const summary = remoteSnap?.summary || {};
  const localSummary = localSnap?.summary || {};
  const advertising = remoteSnap?.advertisingSummary || {};
  const crm = remoteSnap?.crmSummary || {};
  const whatsapp = remoteSnap?.whatsappSummary || {};
  const fallbackMetrics = {
    pending_listings: Number(summary?.properties?.pending ?? localSummary.pendingListings ?? 0),
    live_listings: Number(summary?.properties?.public_live ?? summary?.properties?.approved ?? localSummary.approvedListings ?? 0),
    hidden_listings: Number(summary?.properties?.hidden ?? localSummary.hiddenListings ?? 0),
    deleted_listings: Number(summary?.properties?.deleted ?? localSummary.deletedListings ?? 0),
    broker_pending: Number(summary?.agents?.pending ?? localSummary.notRegisteredAgents ?? 0),
    broker_approved: Number(summary?.agents?.approved ?? localSummary.registeredAgents ?? 0),
    open_leads: Number(crm?.leads?.open ?? crm?.summary?.open_leads ?? adminCrmLeads.length ?? 0),
    hot_leads: Number(crm?.leads?.hot ?? crm?.summary?.hot_leads ?? 0),
    overdue_tasks: Number(crm?.tasks?.overdue ?? crm?.summary?.overdue_followups ?? 0),
    whatsapp_needs_human: Number(whatsapp?.needs_human ?? 0),
    failed_emails: adminEmailLogs.filter((row) => ["failed", "provider_missing", "bounced", "error"].includes(String(row.status || "").toLowerCase())).length,
    failed_whatsapp: adminWhatsappLogs.filter((row) => ["failed", "provider_missing", "error"].includes(String(row.status || "").toLowerCase())).length,
    advertising_open_leads: Number(advertising.open_inquiries ?? 0),
    live_ads: Number(advertising.live_campaigns ?? 0),
    paid_revenue_ugx: Number(advertising.paid_revenue_ugx ?? 0),
    quoted_pipeline_ugx: Number(advertising.quoted_pipeline_ugx ?? 0),
    test_records: 0,
    property_requests: Array.isArray(remoteSnap?.propertyRequests) ? remoteSnap.propertyRequests.length : 0
  };
  const merged = { ...fallbackMetrics, ...metrics };
  const decisions = Array.isArray(command.decisions) && command.decisions.length ? command.decisions : [
    { key: "listing_review", label: "Listings waiting for approval", value: merged.pending_listings, priority: merged.pending_listings ? "high" : "clear", tab: "review", action: "Approve, reject, hide, or request changes." },
    { key: "lead_follow_up", label: "Open CRM leads", value: merged.open_leads, priority: merged.hot_leads || merged.overdue_tasks ? "high" : merged.open_leads ? "medium" : "clear", tab: "notifications", action: "Work hot leads and overdue follow-ups first." },
    { key: "broker_review", label: "Broker accounts needing review", value: merged.broker_pending, priority: merged.broker_pending ? "high" : "clear", tab: "accounts", action: "Review broker ID, consent, and approval state." },
    { key: "whatsapp_handoff", label: "WhatsApp needs human", value: merged.whatsapp_needs_human, priority: merged.whatsapp_needs_human ? "high" : "clear", tab: "whatsapp", action: "Resolve, reply, or hand off conversations." },
    { key: "advertising_revenue", label: "Advertising pipeline", value: merged.advertising_open_leads, priority: merged.advertising_open_leads ? "medium" : "clear", tab: "ads", action: "Move advertiser interest to campaign and payment." }
  ];
  return { metrics: merged, decisions };
}

function adminPriorityClass(priority = "clear") {
  const key = String(priority || "clear").toLowerCase();
  if (key === "high") return "border-red-100 bg-red-50 text-red-800";
  if (key === "medium") return "border-amber-100 bg-amber-50 text-amber-900";
  return "border-green-100 bg-green-50 text-green-800";
}

function renderAdminCommandCentre(remoteSnap, localSnap, sourceLabel = "") {
  const { metrics, decisions } = adminBuildCommandCentre(remoteSnap, localSnap);
  const source = document.getElementById("admin-command-source");
  if (source) source.textContent = sourceLabel.replace(/^Data source:\s*/i, "") || "live admin data";

  const cleanMode = document.getElementById("admin-clean-mode-status");
  if (cleanMode) {
    cleanMode.textContent = adminCleanModeEnabled()
      ? `Clean launch view on - ${Number(metrics.test_records || 0)} QA/test record${Number(metrics.test_records || 0) === 1 ? "" : "s"} hidden from default lists`
      : "Clean launch view off - showing every backend record";
  }

  const metricsGrid = document.getElementById("admin-command-metrics-grid");
  if (metricsGrid) {
    const cards = [
      ["Listings to decide", metrics.pending_listings, "text-amber-700", "review", "admin-review-queue-control"],
      ["Live on site", metrics.live_listings, "text-green-700", "live", "admin-live-followup-control"],
      ["Open leads", metrics.open_leads, "text-blue-700", "notifications", "admin-notifications-control"],
      ["WhatsApp handoffs", metrics.whatsapp_needs_human, "text-red-700", "whatsapp", "admin-whatsapp-control"],
      ["Broker reviews", metrics.broker_pending, "text-amber-700", "accounts", "admin-broker-accounts-table"],
      ["Ad leads", metrics.advertising_open_leads, "text-emerald-700", "ads", "admin-advertising-control"],
      ["Revenue paid", adminFormatUgx(metrics.paid_revenue_ugx), "text-gray-900", "ads", "admin-advertising-control"],
      ["Pipeline quote", adminFormatUgx(metrics.quoted_pipeline_ugx), "text-fuchsia-700", "ads", "admin-advertising-control"]
    ];
    metricsGrid.innerHTML = cards.map(([label, value, tone, tab, selector]) => `
      <button type="button" onclick="adminOpenDecision('${adminAttr(tab)}', '#${adminAttr(selector)}')" class="text-left rounded-2xl border border-gray-200 bg-white hover:border-green-300 hover:bg-green-50 p-4 transition">
        <div class="text-[11px] font-black uppercase tracking-wide text-gray-500">${adminEscape(label)}</div>
        <div class="mt-1 text-2xl font-black ${tone}">${adminEscape(value)}</div>
      </button>
    `).join("");
  }

  const queue = document.getElementById("admin-decision-queue");
  if (queue) {
    queue.innerHTML = decisions.map((decision) => {
      const tab = decision.tab || "review";
      const selector = adminCommandSelectorForTab(tab);
      return `
        <button type="button" onclick="adminOpenDecision('${adminAttr(tab)}', '${adminAttr(selector)}')" class="w-full text-left border rounded-2xl p-4 transition hover:shadow-sm ${adminPriorityClass(decision.priority)}">
          <div class="flex items-start justify-between gap-3">
            <div>
              <div class="text-sm font-black text-gray-950">${adminEscape(decision.label || "Decision")}</div>
              <div class="text-xs mt-1 opacity-80">${adminEscape(decision.action || "Open the matching control panel.")}</div>
            </div>
            <div class="text-2xl font-black">${adminEscape(decision.value ?? 0)}</div>
          </div>
        </button>`;
    }).join("");
  }

  const revenue = document.getElementById("admin-revenue-focus");
  if (revenue) {
    const pipeline = Number(metrics.quoted_pipeline_ugx || 0);
    const paid = Number(metrics.paid_revenue_ugx || 0);
    const openAdLeads = Number(metrics.advertising_open_leads || 0);
    revenue.innerHTML = `
      <div class="rounded-2xl border border-amber-100 bg-amber-50 p-4">
        <div class="text-xs font-black uppercase tracking-wide text-amber-800">Money focus</div>
        <div class="mt-2 text-sm text-amber-950">Open ad leads: <strong>${adminEscape(openAdLeads)}</strong>. Quoted pipeline: <strong>${adminEscape(adminFormatUgx(pipeline))}</strong>. Paid: <strong>${adminEscape(adminFormatUgx(paid))}</strong>.</div>
        <button type="button" onclick="adminOpenDecision('ads', '#admin-advertising-control')" class="mt-3 rounded-xl bg-amber-700 px-4 py-2 text-xs font-black text-white">Open Advertising Desk</button>
      </div>`;
  }

  const liveStatus = document.getElementById("admin-live-site-status");
  if (liveStatus) {
    liveStatus.innerHTML = `
      <div class="rounded-2xl border border-green-100 bg-green-50 p-4">
        <div class="text-xs font-black uppercase tracking-wide text-green-800">Launch hygiene</div>
        <div class="mt-2 text-sm text-green-950">Live listings: <strong>${adminEscape(metrics.live_listings || 0)}</strong>. Hidden: <strong>${adminEscape(metrics.hidden_listings || 0)}</strong>. Deleted: <strong>${adminEscape(metrics.deleted_listings || 0)}</strong>. Test/QA hidden by default: <strong>${adminEscape(metrics.test_records || 0)}</strong>.</div>
        <button type="button" onclick="adminOpenDecision('listings', '#admin-listings-control')" class="mt-3 rounded-xl bg-green-800 px-4 py-2 text-xs font-black text-white">Open Listing Motherboard</button>
      </div>`;
  }
}

function adminRunCommandSearch() {
  const input = document.getElementById("admin-command-search");
  const result = document.getElementById("admin-command-search-result");
  const q = String(input?.value || "").toLowerCase().trim();
  if (!result) return;
  if (!q) {
    result.textContent = "Type a plain-English admin question or task, for example: show leads, review brokers, check failed emails, or open ads.";
    return;
  }
  const routes = [
    { terms: ["lead", "crm", "callback", "viewing", "mortgage", "enquiry", "enquiries"], tab: "notifications", selector: "#admin-notifications-control", label: "Leads & Notifications" },
    { terms: ["whatsapp", "chat", "handoff", "conversation", "language"], tab: "whatsapp", selector: "#admin-whatsapp-control", label: "WhatsApp Inbox" },
    { terms: ["ad", "advert", "revenue", "payment", "invoice", "boost", "campaign"], tab: "ads", selector: "#admin-advertising-control", label: "Advertising Desk" },
    { terms: ["broker", "agent account", "account", "password", "user", "student"], tab: "accounts", selector: "#admin-accounts-control", label: "Accounts & Outreach" },
    { terms: ["field", "payout", "pin", "territory"], tab: "field-agents", selector: "#admin-field-agent-control", label: "Field Agent Control Centre" },
    { terms: ["listing", "property", "delete", "hide", "approve", "pending", "live"], tab: "listings", selector: "#admin-listings-control", label: "All Listings" },
    { terms: ["review", "queue", "moderate"], tab: "review", selector: "#admin-review-queue-control", label: "Review Queue" }
  ];
  const match = routes.find((route) => route.terms.some((term) => q.includes(term))) || routes[0];
  result.innerHTML = `Best panel: <strong>${adminEscape(match.label)}</strong>. Opening it now.`;
  adminOpenDecision(match.tab, match.selector);
}

function askAdminAiAssistant() {
  if (!adminAiSnapshot) {
    toast("Refresh admin data first.");
    return;
  }
  const q = (document.getElementById("admin-ai-question")?.value || "").toLowerCase().trim();
  const answer = document.getElementById("admin-ai-answer");
  if (!answer) return;
  let html = "";
  if (q.includes("two") || q.includes("2") || q.includes("48") || q.includes("visit")) {
    html = `In the last 48 hours the site recorded <strong>${adminAiSnapshot.views48h}</strong> property views from <strong>${adminAiSnapshot.visitors48h}</strong> visitors, plus <strong>${adminAiSnapshot.routeEvents48h}</strong> direction opens and <strong>${adminAiSnapshot.inquiries48h}</strong> enquiries.`;
  } else if (q.includes("area") || q.includes("target") || q.includes("where")) {
    const rows = adminAiSnapshot.topAreas.length
      ? adminAiSnapshot.topAreas.map((row, idx) => `<li>${idx + 1}. ${adminEscape(row.area || "Unknown")} - ${adminEscape(row.events || 0)} events</li>`).join("")
      : "<li>No area data yet.</li>";
    html = `<div>Best current areas to target:</div><ol class="list-decimal pl-5 mt-1">${rows}</ol>`;
  } else if (q.includes("tips") || q.includes("account") || q.includes("users")) {
    html = `<strong>${adminAiSnapshot.weeklyTips}</strong> users are opted in for weekly tips out of <strong>${adminAiSnapshot.totalUsers}</strong> accounts.`;
  } else {
    html = `Current platform snapshot: <strong>${adminAiSnapshot.approvedListings}</strong> live listings, <strong>${adminAiSnapshot.pendingListings}</strong> pending listings, <strong>${adminAiSnapshot.totalViews}</strong> total views, and <strong>${adminAiSnapshot.totalSaves}</strong> saves.`;
  }
  answer.innerHTML = html;
}

async function runManagingDirectorAgent() {
  const target = document.getElementById("admin-ai-agent-results");
  if (!canUseLiveAdminApi()) {
    toast("Sign in as admin or save ADMIN_API_KEY first.");
    if (target) target.innerHTML = "Sign in as admin or save ADMIN_API_KEY first.";
    return;
  }
  if (target) target.innerHTML = "Running the makaug Managing Director now...";
  try {
    const response = await apiRequest("/api/admin/ai-agents/run", {
      method: "POST",
      headers: adminAuthHeaders(),
      body: {
        agent_code: "managing_director_ceo",
        trigger_source: "admin_dashboard",
        created_by: authState?.user?.email || "founder_dashboard",
        limit: 40
      }
    });
    const result = response?.data || {};
    const findings = Array.isArray(result.findings) ? result.findings : [];
    const runStatus = result.run?.status || "completed";
    const findingRows = findings.length
      ? findings.slice(0, 5).map((finding) => `
        <li class="mt-2">
          <strong>${adminEscape(finding.severity || "info")}:</strong>
          ${adminEscape(finding.message || finding.finding_type || "Finding")}
          ${finding.recommendation ? `<div class="text-xs text-green-800 mt-1">${adminEscape(finding.recommendation).slice(0, 220)}</div>` : ""}
        </li>`).join("")
      : "<li class=\"mt-2\">No urgent findings in this run.</li>";
    if (target) {
      target.innerHTML = `
        <div class="font-bold">Managing Director run: ${adminEscape(runStatus)}</div>
        <div class="text-xs mt-1">Findings created: ${adminEscape(findings.length)}</div>
        <ul class="list-disc pl-5 mt-2">${findingRows}</ul>`;
    }
    toast(`Managing Director run finished: ${findings.length} finding${findings.length === 1 ? "" : "s"}.`);
    loadAiCeoStatus({ silent: true });
  } catch (error) {
    if (target) target.innerHTML = `Managing Director run failed: ${adminEscape(error.message || "Unknown error")}`;
    toast(error.message || "Managing Director run failed.");
  }
}

function renderAiCeoStatus(data) {
  const statusPill = document.getElementById("admin-ai-ceo-status-pill");
  const switchesEl = document.getElementById("admin-ai-ceo-kill-switches");
  const outputEl = document.getElementById("admin-ai-ceo-output");
  const approvalsEl = document.getElementById("admin-ai-ceo-approvals");
  if (!statusPill && !switchesEl && !outputEl && !approvalsEl) return;

  const killSwitches = data?.kill_switches || {};
  const lastReport = data?.last_report || null;
  const pendingActions = Array.isArray(data?.pending_actions) ? data.pending_actions : [];
  const openFindings = Array.isArray(data?.open_findings) ? data.open_findings : [];
  const recentCommands = Array.isArray(data?.recent_commands) ? data.recent_commands : [];
  const deliveryChannels = Array.isArray(data?.delivery_channels) ? data.delivery_channels : [];
  const guardrails = Array.isArray(data?.guardrails) ? data.guardrails : [];

  if (statusPill) {
    statusPill.textContent = data?.enabled ? `Active • ${adminEscape(data.run_mode || "recommend")}` : "Paused";
    statusPill.className = data?.enabled
      ? "rounded-full bg-green-100 px-3 py-1 text-xs font-black text-green-800"
      : "rounded-full bg-amber-100 px-3 py-1 text-xs font-black text-amber-800";
  }

  if (switchesEl) {
    const switchRows = Object.entries(killSwitches).map(([key, value]) => {
      const blocked = value === false;
      const label = key.replace(/_/g, " ");
      return `<span class="rounded-full ${blocked ? "bg-red-50 text-red-700 border-red-100" : "bg-green-50 text-green-800 border-green-100"} border px-3 py-1 font-bold">${blocked ? "Blocked" : "On"}: ${adminEscape(label)}</span>`;
    }).join("");
    switchesEl.innerHTML = switchRows || "<span class=\"text-gray-500\">No kill switches loaded yet.</span>";
  }

  if (outputEl) {
    const reportSummary = lastReport?.summary || "No saved morning report yet. Run one before live operations begin.";
    const channels = deliveryChannels.length ? deliveryChannels.join(", ") : "dashboard";
    const latestCommand = recentCommands[0]?.response_summary || "";
    outputEl.innerHTML = `
      <div class="font-black text-gray-900">Latest AI CEO view</div>
      <p class="mt-1">${adminEscape(reportSummary)}</p>
      <div class="mt-3 grid sm:grid-cols-3 gap-2 text-xs">
        <div class="rounded-xl bg-white border border-gray-200 p-3"><strong>${adminEscape(openFindings.length)}</strong><br>open finding(s)</div>
        <div class="rounded-xl bg-white border border-gray-200 p-3"><strong>${adminEscape(pendingActions.length)}</strong><br>pending action(s)</div>
        <div class="rounded-xl bg-white border border-gray-200 p-3"><strong>${adminEscape(channels)}</strong><br>delivery channels</div>
      </div>
      ${latestCommand ? `<div class="mt-3 rounded-xl border border-green-100 bg-green-50 p-3 text-green-900"><strong>Last command:</strong> ${adminEscape(latestCommand)}</div>` : ""}
      ${guardrails.length ? `<ul class="mt-3 list-disc pl-5 text-xs text-gray-600">${guardrails.slice(0, 4).map((item) => `<li>${adminEscape(item)}</li>`).join("")}</ul>` : ""}`;
  }

  if (approvalsEl) {
    const actionCards = pendingActions.length
      ? pendingActions.slice(0, 4).map((action) => `
        <div class="rounded-xl border border-amber-100 bg-amber-50 p-3">
          <div class="text-xs font-black uppercase text-amber-800">${adminEscape(action.risk_level || "medium")} risk</div>
          <div class="mt-1 font-bold text-gray-900">${adminEscape(action.action_type || "AI action")}</div>
          <p class="mt-1 text-xs text-gray-600">${adminEscape(action.approval_reason || "Founder review required before external action.")}</p>
        </div>`).join("")
      : `<div class="rounded-xl border border-green-100 bg-green-50 p-3 text-green-900">No pending AI CEO approvals right now.</div>`;
    approvalsEl.innerHTML = actionCards;
  }
}

async function loadAiCeoStatus({ silent = false } = {}) {
  if (!canUseLiveAdminApi()) {
    if (!silent) toast("Sign in as admin or save ADMIN_API_KEY first.");
    renderAiCeoStatus({ enabled: false, kill_switches: {}, pending_actions: [], open_findings: [] });
    return null;
  }
  try {
    const response = await apiRequest("/api/admin/ai-agents/ceo/status", {
      headers: adminAuthHeaders()
    });
    renderAiCeoStatus(response?.data || {});
    return response?.data || {};
  } catch (error) {
    const outputEl = document.getElementById("admin-ai-ceo-output");
    if (outputEl) outputEl.innerHTML = `AI CEO status failed: ${adminEscape(error.message || "Unknown error")}`;
    if (!silent) toast(error.message || "AI CEO status failed.");
    return null;
  }
}

async function runAiCeoMorningReport() {
  const outputEl = document.getElementById("admin-ai-ceo-output");
  if (!canUseLiveAdminApi()) {
    toast("Sign in as admin or save ADMIN_API_KEY first.");
    return;
  }
  if (outputEl) outputEl.innerHTML = "Running the AI CEO morning report now...";
  try {
    const response = await apiRequest("/api/admin/ai-agents/ceo/morning-report", {
      method: "POST",
      headers: adminAuthHeaders(),
      body: {
        trigger_source: "admin_dashboard_morning_report",
        created_by: authState?.user?.email || "founder_dashboard",
        limit: 40
      }
    });
    const data = response?.data || {};
    const report = data.report || {};
    if (outputEl) {
      outputEl.innerHTML = `
        <div class="font-black text-gray-900">Morning report saved</div>
        <p class="mt-1">${adminEscape(report.summary || "Report generated.")}</p>
        <div class="mt-3 text-xs text-gray-600">Findings created: ${adminEscape((data.findings || []).length)}</div>`;
    }
    await loadAiCeoStatus({ silent: true });
    toast("AI CEO morning report generated.");
  } catch (error) {
    if (outputEl) outputEl.innerHTML = `AI CEO morning report failed: ${adminEscape(error.message || "Unknown error")}`;
    toast(error.message || "AI CEO morning report failed.");
  }
}

async function askAiCeoCommand() {
  const input = document.getElementById("admin-ai-ceo-command");
  const outputEl = document.getElementById("admin-ai-ceo-output");
  const command = (input?.value || "").trim();
  if (!command) {
    toast("Type a command for the AI CEO first.");
    return;
  }
  if (!canUseLiveAdminApi()) {
    toast("Sign in as admin or save ADMIN_API_KEY first.");
    return;
  }
  if (outputEl) outputEl.innerHTML = "Asking the AI CEO...";
  try {
    const response = await apiRequest("/api/admin/ai-agents/ceo/command", {
      method: "POST",
      headers: adminAuthHeaders(),
      body: {
        command_text: command,
        channel: "dashboard",
        requested_by: authState?.user?.email || "founder_dashboard"
      }
    });
    const data = response?.data || {};
    const summary = data.response?.summary || data.command?.response_summary || "AI CEO answered.";
    if (outputEl) {
      outputEl.innerHTML = `
        <div class="font-black text-gray-900">AI CEO response</div>
        <p class="mt-1">${adminEscape(summary)}</p>
        ${data.response?.requires_founder_approval ? `<div class="mt-3 rounded-xl border border-amber-100 bg-amber-50 p-3 text-xs font-bold text-amber-800">Founder approval guardrail is active for this request.</div>` : ""}`;
    }
    await loadAiCeoStatus({ silent: true });
    toast("AI CEO response ready.");
  } catch (error) {
    if (outputEl) outputEl.innerHTML = `AI CEO command failed: ${adminEscape(error.message || "Unknown error")}`;
    toast(error.message || "AI CEO command failed.");
  }
}

function adminAuthHeaders() {
  const headers = {};
  if (adminApiKey) headers["x-api-key"] = adminApiKey;
  if (authState?.token && derivePortalMode(authState.user, authState.user?.portal_mode) === "admin") {
    headers.Authorization = `Bearer ${authState.token}`;
  }
  return headers;
}

function hasAdminIdentity() {
  return derivePortalMode(authState?.user, authState?.user?.portal_mode) === "admin";
}

function canUseLiveAdminApi() {
  return !!(adminApiKey || hasAdminIdentity());
}

function normalizeRemoteAdminListing(p) {
  const id = String(p?.id || "");
  return {
    ...p,
    id,
    backend_id: id,
    type: normalizeType(p?.listing_type || p?.type),
    subtype: p?.property_type || p?.subtype,
    img: p?.primary_image_url || p?.img,
    moderation_status: normalizeModerationStatus(p?.status)
  };
}

function adminListingMatchesId(item = {}, listingId = "") {
  const target = String(listingId || "").trim();
  if (!target) return false;
  return [item.id, item.backend_id, item.property_id, item.inquiry_reference]
    .some((value) => String(value || "").trim() === target);
}

function adminUpsertListingById(list = [], listing = {}, listingId = "") {
  const source = Array.isArray(list) ? list : [];
  const id = String(listingId || listing.id || listing.backend_id || "").trim();
  if (!id) return source;
  const idx = source.findIndex((item) => adminListingMatchesId(item, id));
  if (idx >= 0) {
    source[idx] = { ...source[idx], ...listing };
  } else {
    source.unshift({ ...listing, id: listing.id || id, backend_id: listing.backend_id || id });
  }
  return source;
}

function adminRemoveListingById(list = [], listingId = "") {
  const source = Array.isArray(list) ? list : [];
  const id = String(listingId || "").trim();
  if (!id) return source;
  return source.filter((item) => !adminListingMatchesId(item, id));
}

function adminSetNumericText(id, value) {
  const el = document.getElementById(id);
  if (!el) return;
  el.textContent = String(Math.max(0, Number(value) || 0));
}

function adminAdjustNumericText(id, delta) {
  const el = document.getElementById(id);
  if (!el) return;
  const current = Number(String(el.textContent || "0").replace(/[^\d.-]/g, "")) || 0;
  adminSetNumericText(id, current + Number(delta || 0));
}

function adminEscape(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function adminAttr(value) {
  return adminEscape(value);
}

function normalizeImageSrcForDisplay(value) {
  const raw = String(value ?? "").trim();
  if (!raw) return "";
  const svgMatch = raw.match(/^data:image\/svg\+xml(?:;charset=[^,;]+)?(?:;utf8)?,(.*)$/i);
  if (!svgMatch) return raw;
  const payload = svgMatch[1] || "";
  let svg = payload;
  if (!payload.includes("<")) {
    try { svg = decodeURIComponent(payload); } catch (error) {}
  }
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
}

function publicImageSrc(value, fallback = "") {
  return normalizeImageSrcForDisplay(value) || fallback;
}

function adminCleanModeEnabled() {
  const toggle = document.getElementById("admin-live-clean-mode");
  return !toggle || toggle.checked !== false;
}

function adminRecordLooksLikeTest(row = {}) {
  const extra = row?.extra_fields && typeof row.extra_fields === "object" ? row.extra_fields : {};
  if (extra.is_test === true || extra.qa_test_delete === true || extra.soft_launch_test === true || extra.launch_proof === true || extra.non_public_test === true) return true;
  const hay = [
    row.title,
    row.description,
    row.source,
    row.listed_via,
    row.full_name,
    row.name,
    row.first_name,
    row.last_name,
    row.company_name,
    row.company,
    row.email,
    row.lister_email,
    row.phone,
    row.lister_phone,
    row.inquiry_reference,
    row.reference
  ].filter(Boolean).join(" ").toLowerCase();
  return /soft launch test - delete|qa test - delete|(^|\s)(qa|dummy|sample)(\s|$)|qa-test|qa production|slt-\d|delete|makaug\.invalid|launch proof|non_public_test|xcv|fgfgf|hssjjk|dkskdk|akdk|fsbf|bxb/.test(hay);
}

function adminApplyLaunchCleanFilter(rows = []) {
  const source = Array.isArray(rows) ? rows : [];
  if (!adminCleanModeEnabled()) return source;
  return source.filter((row) => !adminRecordLooksLikeTest(row));
}

function adminPublicControlVisibilityBadge(row = {}) {
  if (!adminRecordLooksLikeTest(row)) return "";
  return `<span class="ml-2 inline-flex align-middle rounded-full bg-amber-100 px-2 py-0.5 text-[11px] font-black text-amber-800">Test-like public listing</span>`;
}

function adminIsSourcedInventoryCandidate(row = {}) {
  const extra = row?.extra_fields && typeof row.extra_fields === "object" ? row.extra_fields : {};
  const source = String(row.source || extra.source || "").toLowerCase();
  const listedVia = String(row.listed_via || extra.listed_via || "").toLowerCase();
  return row.sourced_inventory_candidate === true
    || row.found_online_candidate === true
    || extra.sourced_inventory_candidate === true
    || extra.found_online_candidate === true
    || extra.found_online === true
    || source === "sourced_inventory_candidate_v1"
    || source === "found_online_property_source_v1"
    || listedVia === "sourced_inventory"
    || listedVia === "found_online";
}

function adminIsFoundOnlineSourcedListing(row = {}) {
  const extra = row?.extra_fields && typeof row.extra_fields === "object" ? row.extra_fields : {};
  const source = String(row.source || extra.source || "").toLowerCase();
  const listedVia = String(row.listed_via || extra.listed_via || "").toLowerCase();
  const badge = String(extra.source_badge || extra.source_discovery_label || "").toLowerCase();
  return row.found_online_candidate === true
    || extra.found_online_candidate === true
    || extra.found_online === true
    || extra.social_search_candidate === true
    || source === "found_online_property_source_v1"
    || listedVia === "found_online"
    || badge === "found_online"
    || badge === "found online";
}

function adminIsBrokerSubmissionListing(row = {}) {
  const extra = row?.extra_fields && typeof row.extra_fields === "object" ? row.extra_fields : {};
  const source = String(row.source || extra.source || "").toLowerCase();
  const listedVia = String(row.listed_via || extra.listed_via || "").toLowerCase();
  const listerType = String(row.lister_type || extra.lister_type || "").toLowerCase();
  return extra.broker_submission === true
    || String(extra.broker_submission || "").toLowerCase() === "true"
    || Boolean(extra.broker_agent_id)
    || Boolean(row.agent_id)
    || listerType === "agent"
    || listerType === "broker"
    || listedVia.includes("broker")
    || source.includes("broker");
}

function adminSourcedCandidateSourceLinks(row = {}) {
  const extra = row?.extra_fields && typeof row.extra_fields === "object" ? row.extra_fields : {};
  const images = Array.isArray(row.images) ? row.images : [];
  const addArray = (value) => Array.isArray(value) ? value : (value ? [value] : []);
  const raw = [
    row.source_url,
    row.source_link,
    row.original_url,
    extra.source_url,
    extra.source_link,
    extra.original_url,
    ...addArray(row.source_urls),
    ...addArray(row.photo_source_urls),
    ...addArray(extra.source_urls),
    ...addArray(extra.photo_source_urls),
    ...images.flatMap((image) => [image.source_url, image.source_link, image.original_url, image.url])
  ];
  return [...new Set(raw
    .map((value) => String(value || "").trim())
    .filter((value) => /^https?:\/\//i.test(value)))];
}

function adminSourcedInventoryCandidateBadge(row = {}) {
  if (adminIsFoundOnlineSourcedListing(row)) {
    return `<span class="ml-2 inline-flex align-middle rounded-full bg-blue-100 px-2 py-0.5 text-[11px] font-black text-blue-800">Found online</span>`;
  }
  return "";
}

function adminBrokerSubmissionBadge(row = {}) {
  if (!adminIsBrokerSubmissionListing(row)) return "";
  return `<span class="ml-2 inline-flex align-middle rounded-full bg-emerald-100 px-2 py-0.5 text-[11px] font-black text-emerald-800">Broker listing</span>`;
}

function adminPendingQueueCounts(rows = []) {
  const source = Array.isArray(rows) ? rows : [];
  const foundOnlinePending = source.filter(adminIsFoundOnlineSourcedListing).length;
  const broker = source.filter(adminIsBrokerSubmissionListing).length;
  const student = source.filter((row) => !adminIsFoundOnlineSourcedListing(row) && !adminIsBrokerSubmissionListing(row) && normalizeType(row?.listing_type || row?.type) === "student").length;
  return {
    all: source.length,
    found_online: foundOnlinePending,
    found_online_pending: foundOnlinePending,
    broker,
    student,
  };
}

function adminPendingQueueFilterLabel(filter = adminPendingQueueFilter) {
  if (filter === "found_online") return "Found online";
  if (filter === "broker") return "Broker listings";
  if (filter === "student") return "Student";
  return "All pending";
}

function adminFoundOnlineAllRows() {
  const source = adminUniqueSeedItems(Array.isArray(adminCurrentPendingListings) ? adminCurrentPendingListings : []);
  return adminApplyLaunchCleanFilter(source)
    .filter(adminIsFoundOnlineSourcedListing)
    .filter(adminIsPendingReviewSeedItem)
    .filter((row) => {
      const status = normalizeModerationStatus(row?.status || row?.moderation_status);
      return status === "pending";
    });
}

function adminFilterPendingQueueRows(rows = []) {
  const source = Array.isArray(rows) ? rows : [];
  if (adminPendingQueueFilter === "found_online") {
    return source.filter(adminIsFoundOnlineSourcedListing).filter(adminIsPendingReviewSeedItem);
  }
  if (adminPendingQueueFilter === "broker") {
    return source.filter(adminIsBrokerSubmissionListing).filter(adminIsPendingReviewSeedItem);
  }
  if (adminPendingQueueFilter === "student") return source.filter((row) => !adminIsFoundOnlineSourcedListing(row) && !adminIsBrokerSubmissionListing(row) && normalizeType(row?.listing_type || row?.type) === "student");
  return source;
}

function adminPendingQueueFilterButton(filter, label, count) {
  const active = adminPendingQueueFilter === filter;
  return `<button type="button" onclick="adminSetPendingQueueFilter('${adminAttr(filter)}')" class="${active ? "bg-gray-900 text-white" : "bg-white text-gray-700 hover:bg-gray-50"} border border-gray-300 px-3 py-1.5 rounded-lg text-xs font-black">${adminEscape(label)} <span class="${active ? "text-gray-200" : "text-gray-500"}">${adminEscape(count)}</span></button>`;
}

function adminFoundOnlineSourceSummaryHtml(row = {}, options = {}) {
  if (!adminIsFoundOnlineSourcedListing(row)) return "";
  const extra = row?.extra_fields && typeof row.extra_fields === "object" ? row.extra_fields : {};
  const links = adminSourcedCandidateSourceLinks(row);
  const dateNeedsConfirmation = sourcePostDateNeedsPlatformConfirmation(extra);
  const firstPosted = String(
    dateNeedsConfirmation
      ? (extra.original_publish_date_status || "Original post date is being confirmed from the source platform.")
      : (extra.first_posted_online_label
        || extra.source_published_label
        || extra.youtube_source_published_label
        || extra.first_seen_online_label
        || extra.original_publish_date_status
        || "")
  ).trim();
  const sourceName = String(extra.source_name || row.lister_name || "Found-online source").trim();
  const platform = String(extra.source_platform || extra.source_contact_platform || "").trim();
  const primaryLink = links[0] || "";
  const compact = options.compact !== false;
  return `
    <div class="${compact ? "mt-1" : "mt-3"} rounded-lg border border-blue-100 bg-blue-50 px-3 py-2 text-xs text-blue-950">
      <div><strong>Source:</strong> ${adminEscape([sourceName, platform].filter(Boolean).join(" • ") || "Found online")}</div>
      ${firstPosted ? `<div class="mt-1"><strong>First posted/seen:</strong> ${adminEscape(firstPosted)}</div>` : ""}
      ${primaryLink ? `<div class="mt-1"><a href="${adminAttr(primaryLink)}" target="_blank" rel="noopener" class="font-black text-blue-700 underline">Open source</a></div>` : ""}
    </div>`;
}

function adminPendingQueueToolbarHtml(rows = [], filteredRows = [], visibleRows = filteredRows) {
  const counts = adminPendingQueueCounts(rows);
  const isFoundOnlineView = adminPendingQueueFilter === "found_online";
  const isBrokerView = adminPendingQueueFilter === "broker";
  const visibleCount = Array.isArray(visibleRows) ? visibleRows.length : Number(visibleRows || 0);
  const hasMore = filteredRows.length > visibleCount;
  const statusText = isFoundOnlineView
    ? `${adminEscape(visibleCount)} of ${adminEscape(filteredRows.length)} found-online source property records shown. Approved, live, sold, hidden, rejected, and deleted records are excluded from this queue.`
    : isBrokerView
      ? `${adminEscape(visibleCount)} of ${adminEscape(filteredRows.length)} broker-submitted listings shown. These are agent listings waiting for King or staff approval before going public.`
    : `${adminEscape(visibleCount)} of ${adminEscape(filteredRows.length)} matching records shown from ${adminEscape(rows.length)} pending review records. Approved/live records move to Live & Featured and do not stay in Review Queue.`;
  return `
    <div class="mb-4 rounded-xl border border-blue-100 bg-blue-50 p-3 text-xs text-blue-950">
      <div class="flex items-start justify-between gap-3 flex-wrap">
        <div>
          <div class="font-black">Pending queue view: ${adminEscape(adminPendingQueueFilterLabel())}</div>
          <div class="mt-1">${statusText}</div>
        </div>
        <div class="flex gap-2 flex-wrap">
          ${adminPendingQueueFilterButton("all", "All", counts.all)}
          ${adminPendingQueueFilterButton("found_online", "Found online", counts.found_online)}
          ${adminPendingQueueFilterButton("broker", "Broker", counts.broker)}
          ${adminPendingQueueFilterButton("student", "Student", counts.student)}
          ${hasMore ? `<button type="button" onclick="adminShowMorePendingQueueRows()" class="bg-white text-blue-700 hover:bg-blue-50 border border-blue-200 px-3 py-1.5 rounded-lg text-xs font-black">Show more</button>` : ""}
        </div>
      </div>
    </div>`;
}

function adminSetPendingQueueFilter(filter = "all") {
  const allowed = new Set(["all", "found_online", "broker", "student"]);
  adminPendingQueueFilter = allowed.has(String(filter)) ? String(filter) : "all";
  adminPendingQueueVisibleLimit = ADMIN_PENDING_QUEUE_RENDER_STEP;
  renderAdminPendingRows(adminCurrentPendingListings);
}

function adminShowMorePendingQueueRows() {
  adminPendingQueueVisibleLimit += ADMIN_PENDING_QUEUE_RENDER_STEP;
  renderAdminPendingRows(adminCurrentPendingListings);
}

function adminScrollTo(selector) {
  const target = selector ? document.querySelector(selector) : null;
  if (target) target.scrollIntoView({ behavior: "smooth", block: "start" });
}

function adminOpenDecision(tab = "review", selector = "") {
  setAdminWorkflowTab(tab);
  setTimeout(() => adminScrollTo(selector || `[data-admin-tab-panel="${tab}"]`), 40);
}

function adminDashboardActiveTabNeedsRows(tab = activeAdminWorkflowTab) {
  const normalized = String(tab || "review");
  return {
    reviewQueue: ["review", "student-sweep", "youtube-sweep"].includes(normalized),
    liveListings: ["live", "listings"].includes(normalized),
    actionedListings: ["actioned", "listings"].includes(normalized),
    accounts: normalized === "accounts",
    fieldAgents: normalized === "field-agents",
    ads: normalized === "ads",
    whatsapp: normalized === "whatsapp",
    notifications: normalized === "notifications",
    staff: normalized === "staff"
  };
}

function adminScheduleDashboardRefreshForTab() {
  if (adminDashboardRendering || !canUseLiveAdminApi()) return;
  const body = document.getElementById("admin-body");
  if (!body || body.classList.contains("hidden")) return;
  if (adminDashboardTabRefreshTimer) clearTimeout(adminDashboardTabRefreshTimer);
  adminDashboardTabRefreshTimer = setTimeout(() => {
    adminDashboardTabRefreshTimer = null;
    renderAdminDashboard({ source: "tab_switch" }).catch((error) => {
      console.warn("Unable to refresh admin tab", error?.message || error);
    });
  }, 80);
}

function adminListingIdArg(value) {
  return adminEscape(JSON.stringify(String(value || "")));
}

function propertyIdArg(value) {
  return adminListingIdArg(value);
}

function adminStatusBadge(status) {
  const st = normalizeModerationStatus(status);
  if (st === "approved") return { cls: "bg-green-100 text-green-700", label: "Live" };
  if (st === "sold") return { cls: "bg-blue-100 text-blue-700", label: "Sold" };
  if (st === "pending") return { cls: "bg-amber-100 text-amber-700", label: "Pending" };
  if (st === "rejected") return { cls: "bg-red-100 text-red-700", label: "Rejected" };
  if (st === "hidden") return { cls: "bg-yellow-100 text-yellow-800", label: "Hidden" };
  if (st === "deleted") return { cls: "bg-gray-200 text-gray-700", label: "Deleted" };
  return { cls: "bg-gray-100 text-gray-700", label: st || "Unknown" };
}

function adminVerificationBadge(status) {
  const st = String(status || "").toLowerCase() === "registered" ? "registered" : "not_registered";
  if (st === "registered") return { cls: "bg-green-100 text-green-700", label: "Verified / Registered" };
  return { cls: "bg-gray-100 text-gray-700", label: "Review needed" };
}

function setAdminWorkflowTab(tab = "review") {
  const allowed = ["review", "student-sweep", "youtube-sweep", "actioned", "live", "accounts", "staff", "field-agents", "ads", "whatsapp", "notifications", "listings"];
  const previousTab = activeAdminWorkflowTab;
  activeAdminWorkflowTab = allowed.includes(String(tab)) ? String(tab) : "review";
  document.querySelectorAll("[data-admin-tab-panel]").forEach((panel) => {
    panel.classList.toggle("hidden", panel.dataset.adminTabPanel !== activeAdminWorkflowTab);
  });
  document.querySelectorAll("[data-admin-tab-button]").forEach((button) => {
    const active = button.dataset.adminTabButton === activeAdminWorkflowTab;
    button.classList.toggle("bg-gray-900", active);
    button.classList.toggle("text-white", active);
    button.classList.toggle("bg-gray-100", !active);
    button.classList.toggle("text-gray-700", !active);
  });
  if (activeAdminWorkflowTab !== "review") closeAdminReviewPanel();
  if (previousTab !== activeAdminWorkflowTab) adminScheduleDashboardRefreshForTab();
}

async function fetchAdminPaginatedRows(path, headers, options = {}) {
  const limit = Math.min(Math.max(Number(options.limit || 100), 1), 100);
  const maxPages = Math.min(Math.max(Number(options.maxPages || 10), 1), 500);
  const rows = [];
  let firstResponse = null;
  let lastResponse = null;
  let page = 1;
  let totalPages = 1;
  do {
    const separator = path.includes("?") ? "&" : "?";
    const response = await apiRequest(`${path}${separator}limit=${limit}&page=${page}`, { headers });
    if (!firstResponse) firstResponse = response;
    lastResponse = response;
    rows.push(...(Array.isArray(response?.data) ? response.data : []));
    totalPages = Math.max(1, Number(response?.pagination?.totalPages || 1));
    page += 1;
  } while (page <= totalPages && page <= maxPages);
  Object.defineProperties(rows, {
    adminPagination: { value: lastResponse?.pagination || null },
    adminSummary: { value: lastResponse?.summary || firstResponse?.summary || null },
    adminMeta: { value: lastResponse?.meta || firstResponse?.meta || null }  });
  return rows;
}

let adminAllListingsHydrationInFlight = null;

function hydrateAdminAllListingsInBackground(headers) {
  if (adminAllListingsHydrationInFlight || !canUseLiveAdminApi()) return;
  adminAllListingsHydrationInFlight = fetchAdminPaginatedRows("/api/properties?status=all", headers, { maxPages: 500 })
    .then((rows) => {
      const allListings = (rows || []).map(normalizeRemoteAdminListing);
      if (!allListings.length) return;
      adminRemoteListings = allListings;
      renderAdminActionedRows(allListings);
      renderAdminAllListingsRows(allListings);
    })
    .catch(() => {})
    .finally(() => {
      adminAllListingsHydrationInFlight = null;
    });
}

async function adminSafeSnapshotRequest(label, requestFn, fallback) {
  try {
    return await requestFn();
  } catch (error) {
    if (Number(error?.status || 0) === 401) {
      adminLiveAuthFailure = error;
    }
    console.warn(`Admin dashboard ${label} unavailable`, error?.message || error);
    return fallback;
  }
}

function buildAdminAuthFailureError() {
  if (!adminLiveAuthFailure) return null;
  const error = new Error(adminApiKey
    ? "Saved ADMIN_API_KEY was rejected by the live server. Sign in as admin or save the current live key."
    : "Admin session expired. Sign in again to reconnect live King dashboard data.");
  error.status = 401;
  error.adminAuthFailure = true;
  return error;
}

async function fetchRemoteAdminSnapshot(options = {}) {
  if (!canUseLiveAdminApi()) return null;
  const headers = adminAuthHeaders();
  adminLiveAuthFailure = null;
  const activeTab = String(options.activeTab || activeAdminWorkflowTab || "review");
  const tabNeeds = adminDashboardActiveTabNeedsRows(activeTab);
  const userSearch = (document.getElementById("admin-users-q")?.value || "").trim();
  const userRole = (document.getElementById("admin-users-role")?.value || "").trim();
  const weeklyOnly = (document.getElementById("admin-users-tips")?.value || "") === "weekly";
  const whatsappSearch = (document.getElementById("admin-whatsapp-search")?.value || "").trim();
  const whatsappStatus = (document.getElementById("admin-whatsapp-status")?.value || "").trim();
  const whatsappCategory = (document.getElementById("admin-whatsapp-category")?.value || "").trim();
  const whatsappAiMode = (document.getElementById("admin-whatsapp-ai-mode")?.value || "").trim();
  const userParams = new URLSearchParams({ limit: "100" });
  const propertyRequestParams = new URLSearchParams({ limit: "100" });
  const fieldAgentParams = new URLSearchParams({ limit: "10000", role: "field_agent" });
  const whatsappParams = new URLSearchParams({ limit: "50" });
  if (userSearch) userParams.set("search", userSearch);
  if (userRole) userParams.set("role", userRole);
  if (weeklyOnly) userParams.set("weekly_tips_only", "true");
  if (whatsappSearch) whatsappParams.set("search", whatsappSearch);
  if (whatsappStatus) whatsappParams.set("status", whatsappStatus);
  if (whatsappCategory) whatsappParams.set("category", whatsappCategory);
  if (whatsappAiMode) whatsappParams.set("ai_mode", whatsappAiMode);
  const shouldLoadReviewQueue = tabNeeds.reviewQueue;
  const shouldLoadLiveListings = tabNeeds.liveListings;
  const shouldLoadAgents = tabNeeds.accounts || tabNeeds.liveListings;
  const shouldLoadAccounts = tabNeeds.accounts;
  const shouldLoadCampaigns = tabNeeds.accounts || tabNeeds.ads;
  const shouldLoadFieldAgents = tabNeeds.fieldAgents;
  const shouldLoadAds = tabNeeds.ads;
  const shouldLoadWhatsapp = tabNeeds.whatsapp;
  const shouldLoadNotifications = tabNeeds.notifications;
  const [summaryRes, commandCentreRes, recentRes, pendingRows, liveRows, usersRes, agentsRes, propertyRequestsRes, fieldAgentsRes, campaignsRes, adPackagesRes, adPlacementsRes, adSummaryRes, adInquiriesRes, adCampaignsRes, whatsappInsightsRes, whatsappConversationsRes, crmSummaryRes, crmLeadsRes, notificationsRes, emailsRes, outlookStatusRes, outlookActionsRes, whatsappLogsRes] = await Promise.all([
    adminSafeSnapshotRequest("summary", () => apiRequest("/api/admin/summary", { headers }), { data: {} }),
    adminSafeSnapshotRequest("command centre", () => apiRequest("/api/admin/command-centre", { headers }), { data: {} }),
    adminSafeSnapshotRequest("recent activity", () => apiRequest("/api/admin/recent", { headers }), { data: {} }),
    shouldLoadReviewQueue ? adminSafeSnapshotRequest("review queue", () => fetchAdminPaginatedRows("/api/admin/properties/review-queue", headers, { maxPages: 500 }), []) : null,
    shouldLoadLiveListings ? adminSafeSnapshotRequest("live listings", () => fetchAdminPaginatedRows("/api/admin/properties/live", headers, { maxPages: 10 }), []) : null,
    shouldLoadAccounts ? adminSafeSnapshotRequest("users", () => apiRequest(`/api/admin/users?${userParams.toString()}`, { headers }), { data: [] }) : null,
    shouldLoadAgents ? adminSafeSnapshotRequest("agents", () => apiRequest("/api/admin/agents?limit=100", { headers }), { data: [] }) : null,
    shouldLoadAccounts ? adminSafeSnapshotRequest("property requests", () => apiRequest(`/api/admin/property-requests?${propertyRequestParams.toString()}`, { headers }), { data: [] }) : null,
    shouldLoadFieldAgents ? adminSafeSnapshotRequest("field agents", () => apiRequest(`/api/admin/users?${fieldAgentParams.toString()}`, { headers }), { data: [] }) : null,
    shouldLoadCampaigns ? adminSafeSnapshotRequest("campaigns", () => apiRequest("/api/admin/campaigns?limit=20", { headers }), { data: [] }) : null,
    shouldLoadAds ? adminSafeSnapshotRequest("advertising packages", () => apiRequest("/api/admin/advertising/packages", { headers }), { data: [] }) : null,
    shouldLoadAds ? adminSafeSnapshotRequest("advertising placements", () => apiRequest("/api/admin/advertising/placements", { headers }), { data: [] }) : null,
    shouldLoadAds ? adminSafeSnapshotRequest("advertising summary", () => apiRequest("/api/admin/advertising/summary", { headers }), { data: {} }) : null,
    shouldLoadAds ? adminSafeSnapshotRequest("advertising inquiries", () => apiRequest("/api/admin/advertising/inquiries?limit=100", { headers }), { data: [] }) : null,
    shouldLoadAds ? adminSafeSnapshotRequest("advertising campaigns", () => apiRequest("/api/admin/advertising/campaigns?limit=100", { headers }), { data: [] }) : null,
    shouldLoadWhatsapp ? adminSafeSnapshotRequest("whatsapp insights", () => apiRequest("/api/admin/whatsapp/insights", { headers }), { data: {} }) : null,
    shouldLoadWhatsapp ? adminSafeSnapshotRequest("whatsapp conversations", () => apiRequest(`/api/admin/whatsapp/conversations?${whatsappParams.toString()}`, { headers }), { data: [], summary: {} }) : null,
    shouldLoadNotifications ? adminSafeSnapshotRequest("crm summary", () => apiRequest("/api/admin/crm/summary", { headers }), { data: {} }) : null,
    shouldLoadNotifications ? adminSafeSnapshotRequest("crm leads", () => apiRequest("/api/admin/leads?limit=50", { headers }), { data: [] }) : null,
    shouldLoadNotifications ? adminSafeSnapshotRequest("notifications", () => apiRequest("/api/admin/notifications?limit=50", { headers }), { data: [] }) : null,
    shouldLoadNotifications ? adminSafeSnapshotRequest("emails", () => apiRequest("/api/admin/emails?limit=50", { headers }), { data: [] }) : null,
    shouldLoadNotifications ? adminSafeSnapshotRequest("outlook status", () => apiRequest("/api/admin/outlook-agent/status", { headers }), { data: {} }) : null,
    shouldLoadNotifications ? adminSafeSnapshotRequest("outlook actions", () => apiRequest("/api/admin/outlook-agent/actions?limit=50", { headers }), { data: [] }) : null,
    shouldLoadNotifications ? adminSafeSnapshotRequest("whatsapp logs", () => apiRequest("/api/admin/whatsapp-message-logs?limit=50", { headers }), { data: [] }) : null
  ]);
  const authFailure = buildAdminAuthFailureError();
  if (authFailure) throw authFailure;
  const pendingListings = Array.isArray(pendingRows)
    ? pendingRows.map(normalizeRemoteAdminListing).filter(adminIsPendingReviewSeedItem)
    : adminCurrentPendingListings;
  const liveListings = Array.isArray(liveRows)
    ? liveRows.map((row) => normalizeRemoteAdminListing({ ...row, admin_live_endpoint: true }))
    : adminLiveListings;
  if (Array.isArray(liveRows)) {
    adminPublicInventoryParity = liveRows?.adminMeta?.public_parity || liveRows?.adminSummary?.public_inventory || adminPublicInventoryParity || {};
  }
  const allListings = adminUniqueSeedItems([...pendingListings, ...liveListings]);
  if (Array.isArray(pendingRows) || Array.isArray(liveRows)) adminRemoteListings = allListings;
  if (Array.isArray(liveRows)) adminLiveListings = liveListings;
  if (tabNeeds.actionedListings) hydrateAdminAllListingsInBackground(headers);
  if (Array.isArray(agentsRes?.data)) adminRemoteAgents = agentsRes.data.map(mapRemoteAgentForUi);
  if (Array.isArray(propertyRequestsRes?.data)) adminPropertyRequests = propertyRequestsRes.data;
  if (Array.isArray(fieldAgentsRes?.data)) adminFieldAgents = fieldAgentsRes.data;
  if (Array.isArray(campaignsRes?.data)) adminCurrentCampaigns = campaignsRes.data;
  if (Array.isArray(adPackagesRes?.data)) adminAdvertisingPackages = adPackagesRes.data;
  if (Array.isArray(adPlacementsRes?.data)) adminAdvertisingPlacements = adPlacementsRes.data;
  if (adSummaryRes?.data) adminAdvertisingSummary = adSummaryRes.data;
  if (Array.isArray(adInquiriesRes?.data)) adminAdvertisingInquiries = adInquiriesRes.data;
  if (Array.isArray(adCampaignsRes?.data)) adminAdvertisingCampaigns = adCampaignsRes.data;
  if (whatsappInsightsRes?.data || whatsappConversationsRes?.summary) {
    adminWhatsappSummary = {
      ...(whatsappInsightsRes?.data || {}),
      ...(whatsappConversationsRes?.summary || {}),
      webBridge: whatsappInsightsRes?.data?.webBridge || adminWhatsappSummary.webBridge || {}
    };
  }
  if (Array.isArray(whatsappConversationsRes?.data)) adminWhatsappConversations = whatsappConversationsRes.data;
  if (crmSummaryRes?.data) adminCrmSummary = crmSummaryRes.data;
  if (Array.isArray(crmLeadsRes?.data)) adminCrmLeads = crmLeadsRes.data;
  if (Array.isArray(crmSummaryRes?.data?.openTasks)) adminCrmTasks = crmSummaryRes.data.openTasks;
  if (Array.isArray(notificationsRes?.data)) adminNotificationLogs = notificationsRes.data;
  if (Array.isArray(emailsRes?.data)) adminEmailLogs = emailsRes.data;
  if (Array.isArray(whatsappLogsRes?.data)) adminWhatsappLogs = whatsappLogsRes.data;
  const outlookAgentStatus = outlookStatusRes?.data || {};
  const outlookAgentActions = Array.isArray(outlookActionsRes?.data) ? outlookActionsRes.data : [];
  return {
    summary: summaryRes?.data || {},
    commandCentre: commandCentreRes?.data || {},
    recent: recentRes?.data || {},
    pendingListings,
    liveListings,
    publicInventoryParity: adminPublicInventoryParity,    allListings,
    users: usersRes?.data || [],
    agents: adminRemoteAgents,
    propertyRequests: adminPropertyRequests,
    fieldAgents: adminFieldAgents,
    campaigns: adminCurrentCampaigns,
    advertisingPackages: adminAdvertisingPackages,
    advertisingPlacements: adminAdvertisingPlacements,
    advertisingSummary: adminAdvertisingSummary,
    advertisingInquiries: adminAdvertisingInquiries,
    advertisingCampaigns: adminAdvertisingCampaigns,
    whatsappSummary: adminWhatsappSummary,
    whatsappConversations: adminWhatsappConversations,
    crmSummary: adminCrmSummary,
    crmLeads: adminCrmLeads,
    crmTasks: adminCrmTasks,
    notificationLogs: adminNotificationLogs,
    emailLogs: adminEmailLogs,
    outlookAgentStatus,
    outlookAgentActions,
    whatsappLogs: adminWhatsappLogs
  };
}

function renderAdminPendingRows(listings) {
  const wrap = document.getElementById("admin-pending-table");
  if (!wrap) return;
  ensureAdminFoundOnlineControls();
  adminScrubPendingSeedStatusPanel();
  const cleanListings = adminApplyLaunchCleanFilter(listings).filter(adminIsPendingReviewSeedItem);
  adminCurrentPendingListings = cleanListings;
  const filteredListings = adminFilterPendingQueueRows(cleanListings);
  const visibleListings = filteredListings.slice(0, adminPendingQueueVisibleLimit);
  const toolbarHtml = adminPendingQueueToolbarHtml(cleanListings, filteredListings, visibleListings);
  if (!cleanListings.length && !filteredListings.length) {
    wrap.innerHTML = `<div class="text-sm text-gray-500 bg-gray-50 border border-gray-200 rounded-xl p-4">No pending listings in the current snapshot.</div>`;
    return;
  }
  if (!filteredListings.length) {
    wrap.innerHTML = `${toolbarHtml}<div class="text-sm text-gray-500 bg-gray-50 border border-gray-200 rounded-xl p-4">No ${adminEscape(adminPendingQueueFilterLabel().toLowerCase())} records match the current pending queue.</div>`;
    return;
  }
  wrap.innerHTML = `${toolbarHtml}${visibleListings.map((p) => {
    const statusMeta = adminStatusBadge(p.status);
    const locationText = [p.area, p.district].filter(Boolean).join(", ") || "-";
    const createdText = listingDateMeta(p);
    const localId = String(p.id || "");
    const backendId = String(p.backend_id || p.id || "");
    const reviewId = backendId || localId;
    const reviewArg = adminListingIdArg(reviewId);
    const isPendingReview = adminIsPendingReviewSeedItem(p);
    const publicUrl = String(p.url || (backendId ? `/property/${backendId}` : "") || "").trim();
    const featured = isFeaturedListing(p);
    const sourceBadge = adminSourcedInventoryCandidateBadge(p);
    const brokerBadge = adminBrokerSubmissionBadge(p);
    const listingBadges = `${sourceBadge}${brokerBadge}`;
    return `
      <div class="border border-gray-200 rounded-xl p-4 bg-white">
        <div class="flex justify-between items-start gap-3 flex-wrap">
          <div>
            <div class="font-bold text-gray-800">${adminEscape(p.title || "Untitled listing")}${listingBadges}</div>
            <div class="text-xs text-gray-500 mt-1">${adminEscape(locationText)}</div>
            <div class="text-xs text-gray-500 mt-1">${adminEscape(createdText)} • Ref: ${adminEscape(p.inquiry_reference || reviewId || "-")}</div>
            ${sourceBadge ? `<div class="text-xs text-blue-800 font-semibold mt-1">Location is required before approval. Other found-online checks can be reviewed and overridden by King.</div>` : ""}
            ${brokerBadge ? `<div class="text-xs text-emerald-800 font-semibold mt-1">Broker submission: verify details, then approve to publish.</div>` : ""}
            ${sourceBadge ? adminFoundOnlineSourceSummaryHtml(p) : ""}
          </div>
          <span class="text-xs font-semibold px-2 py-1 rounded ${statusMeta.cls}">${statusMeta.label}</span>
        </div>
        <div class="mt-3 flex gap-2 flex-wrap">
          <button onclick="openAdminListingReview(${reviewArg})" class="bg-gray-900 hover:bg-gray-800 text-white px-3 py-1.5 rounded-lg text-xs font-semibold">Open Review</button>
          ${isPendingReview ? `<button onclick="adminQuickRejectListing(${reviewArg})" class="border border-red-200 text-red-600 hover:bg-red-50 px-3 py-1.5 rounded-lg text-xs font-semibold">Reject</button>` : ""}
          ${!isPendingReview && publicUrl ? `<a href="${adminAttr(publicUrl)}" target="_blank" rel="noopener" class="border border-green-200 text-green-700 hover:bg-green-50 px-3 py-1.5 rounded-lg text-xs font-semibold">Open Public</a>` : ""}
          ${!isPendingReview ? `<button onclick="openAdminListingLivePreview(${reviewArg})" class="border border-blue-200 text-blue-700 hover:bg-blue-50 px-3 py-1.5 rounded-lg text-xs font-semibold">Live-style Preview</button>` : ""}
        </div>
      </div>`;
	  }).join("")}`;
}

function adminRenderListingStatusLocally(updatedListing = {}, normalizedStatus = "", listingId = "", options = {}) {
  const id = String(listingId || updatedListing.id || updatedListing.backend_id || "").trim();
  if (!id) return false;
  const finalStatuses = new Set(["approved", "sold", "rejected", "hidden", "deleted"]);
  const status = normalizeModerationStatus(normalizedStatus || updatedListing.status);
  const wasPending = options.wasPending === true
    || adminCurrentPendingListings.some((item) => adminListingMatchesId(item, id));
  const mergedListing = normalizeRemoteAdminListing({
    ...updatedListing,
    id: updatedListing.id || id,
    backend_id: updatedListing.backend_id || id,
    status,
    moderation_status: status,
    reviewed_at: updatedListing.reviewed_at || new Date().toISOString()
  });

  if (status === "pending") {
    adminCurrentPendingListings = adminUpsertListingById(adminCurrentPendingListings, mergedListing, id);
  } else {
    adminCurrentPendingListings = adminRemoveListingById(adminCurrentPendingListings, id);
  }

  if (finalStatuses.has(status)) {
    adminRemoteListings = adminUpsertListingById(adminRemoteListings, mergedListing, id);
  } else {
    adminRemoteListings = adminRemoveListingById(adminRemoteListings, id);
  }

  if (status === "approved") {
    adminLiveListings = adminUpsertListingById(adminLiveListings, mergedListing, id);
  } else {
    adminLiveListings = adminRemoveListingById(adminLiveListings, id);
  }

  renderAdminPendingRows(adminCurrentPendingListings);
  renderAdminActionedRows(adminRemoteListings);
  renderAdminLiveParitySummary(adminPublicInventoryParity, adminLiveListings);
  renderAdminLiveListingsRows(adminLiveListings);
  renderAdminFeaturedRows(adminLiveListings);
  adminSetNumericText("admin-stat-pending", adminCurrentPendingListings.length);
  if (wasPending && status !== "pending") {
    if (status === "approved") adminAdjustNumericText("admin-stat-approved", 1);
    if (status === "rejected") adminAdjustNumericText("admin-stat-rejected", 1);
    if (status === "hidden") adminAdjustNumericText("admin-stat-hidden", 1);
    if (status === "deleted") adminAdjustNumericText("admin-stat-deleted", 1);
  }
  return true;
}

