async function adminSeedSocialSearchAuthorisedListings() {
  if (!canUseLiveAdminApi()) {
    toast("Sign in as admin or save ADMIN_API_KEY first.");
    return;
  }
  const ok = window.confirm("Scan reviewed social source pages/feeds and queue curated YouTube plus public social found-online property candidates from 1 January 2026 onward. Location is required, missing price becomes Price upon application, and website-only sources are ignored. Source-only broker profiles are not created automatically; the source owner must register or claim one.");
  if (!ok) return;
  const statusEl = document.getElementById("admin-found-online-status");
  const button = document.getElementById("admin-seed-social-search-listings-btn");
  if (button) {
    button.disabled = true;
    button.classList.add("opacity-60", "cursor-wait");
  }
  if (statusEl) {
    statusEl.classList.remove("hidden");
    statusEl.innerHTML = "Checking reviewed social source pages/feeds and queuing curated YouTube plus public social 2026+ found-online property candidates now...";
  }
  try {
    const response = await apiRequest("/api/admin/social-search-authorised-listings/seed", {
      method: "POST",
      headers: adminAuthHeaders(),
      body: { replace: true }
    });
    const data = response?.data || {};
    const samples = Array.isArray(data.listings) ? data.listings : [];
    const alreadyPresent = Array.isArray(data.already_present_properties) ? data.already_present_properties : [];
    const reviewQueueListings = Array.isArray(data.review_queue_listings)
      ? data.review_queue_listings
      : Array.isArray(data.queued_listings)
        ? data.queued_listings
        : samples;
    const visibleSamples = adminUniqueSeedItems(reviewQueueListings.filter(adminIsPendingReviewSeedItem));
    const leakedFinalQueueItems = reviewQueueListings.filter(adminIsFinalReviewSeedItem);
    const alreadyLiveOrApproved = adminUniqueSeedItems([
      ...(Array.isArray(data.already_live_or_approved_properties)
        ? data.already_live_or_approved_properties
        : alreadyPresent.filter(adminIsFinalReviewSeedItem)),
      ...leakedFinalQueueItems,
    ]);
    const alreadyPendingReview = adminUniqueSeedItems(
      (Array.isArray(data.already_present_review_queue_properties)
        ? data.already_present_review_queue_properties
        : alreadyPresent.filter(adminIsPendingReviewSeedItem)).filter(adminIsPendingReviewSeedItem)
    );
    const sourceReviewRecords = Array.isArray(data.source_review_records)
      ? data.source_review_records
      : [];
    const agentCount = Array.isArray(data.agents) ? data.agents.length : 0;
    const skipped = Array.isArray(data.skipped_listings) ? data.skipped_listings : [];
    const alreadyPresentAll = Array.isArray(data.already_present_all_properties)
      ? data.already_present_all_properties
      : [
          ...alreadyPresent,
          ...(Array.isArray(data.already_live_or_approved_properties) ? data.already_live_or_approved_properties : [])
        ];
    const alreadyQueuedCount = Number(data.existing_properties_total ?? data.existing_properties ?? 0)
      || alreadyPresentAll.length
      || skipped.filter((item) => item?.reason === "already_queued" || item?.reason === "already_live_or_approved").length;
    const targetStatus = data.daily_target_status || {};
    const targetHtml = targetStatus.target ? `
        <div class="mt-2 rounded-xl border ${targetStatus.meets_daily_minimum ? "border-emerald-200 bg-emerald-50 text-emerald-900" : "border-amber-200 bg-amber-50 text-amber-900"} p-3">
          <div class="font-black">Morning sweep target: ${adminEscape(targetStatus.eligible_to_queue_count || 0)} / ${adminEscape(targetStatus.target)} found-online properties</div>
          <div class="mt-1">Gap to today's minimum: ${adminEscape(targetStatus.target_gap || 0)}. ${adminEscape(targetStatus.blocking_reason || "Target met with 2026+ found-online records. There is no cap; every extra eligible post is queued.")}</div>
        <div class="mt-1 text-[11px]">${adminEscape(targetStatus.evidence_policy || "Queue every specific public property post from 1 January 2026 onward with source URL, location, usable image/source evidence, and a contact route. If the source does not publish a price, use Price upon application. There is no cap.")}</div>
          ${targetStatus.no_phone_source_contact_policy ? `<div class="mt-1 text-[11px]">${adminEscape(targetStatus.no_phone_source_contact_policy)}</div>` : ""}
          ${targetStatus.source_page_vs_property_policy ? `<div class="mt-1 text-[11px]">${adminEscape(targetStatus.source_page_vs_property_policy)}</div>` : ""}
        </div>` : "";
    const visibleSampleHtml = visibleSamples
      .map((item) => adminSeededListingSummaryHtml(item, { pendingPanel: true }))
      .filter(Boolean)
      .join("");
    adminPendingQueueFilter = "found_online";
    if (statusEl) {
      statusEl.innerHTML = `
        <div class="font-black">Found-online property candidates created</div>
        <div class="mt-1">${adminEscape(data.created_properties || 0)} new property candidates were created. ${adminEscape(visibleSamples.length)} pending found-online records are available in the Review Queue filter below.</div>
        <div class="mt-1">${adminEscape(alreadyQueuedCount || 0)} matching property records already exist. ${adminEscape(alreadyLiveOrApproved.length)} already live/approved records were hidden from this pending panel. ${adminEscape(alreadyPendingReview.length)} existing pending records stay in the review queue.</div>
        <div class="mt-2"><button type="button" onclick="adminSetPendingQueueFilter('found_online'); adminScrollTo('#admin-pending-table')" class="rounded-lg bg-gray-900 px-3 py-2 text-xs font-black text-white">Show all found-online source records</button></div>
        <div class="mt-1">The 30,000 source database is now social-first: X/Twitter, Instagram, TikTok, YouTube, Facebook, and student accommodation social feeds. Website-only sources are ignored. The Review Queue receives curated exact social-source property posts/listings from 1 January 2026 onward once source evidence, contact route, and location/area are present. Public found-online pages use official embeds/source links and rewritten facts; copied social photos are not rehosted unless rights are explicitly approved. Missing source prices are queued as Price upon application. Location is non-negotiable before approval; other checks can be recorded as King review overrides.</div>
        ${targetHtml}
        <div class="mt-2 rounded-xl border border-emerald-100 bg-emerald-50 p-3 text-emerald-950">
          <div class="font-black">Land image rule</div>
          <div class="mt-1">For public found-online listings, use source links or official embeds first. Do not rehost copied social or website photos as makaug gallery assets unless the rights holder has explicitly supplied or approved them. Evidence cards stay for King review and source trail only.</div>
        </div>
        <div class="mt-1">${adminEscape(agentCount)} registered agent profiles refreshed. Source-only profiles are not auto-created; original posters must claim/register before Makaug shows a broker profile.</div>
        ${sourceReviewRecords.length ? `<div class="mt-1 text-amber-800">${adminEscape(sourceReviewRecords.length)} source pages/feeds are parked for source review, not hidden properties. Match each to a specific 2026+ property post before King queues it.</div>` : ""}
        ${visibleSampleHtml ? `<div class="mt-2 space-y-2">${visibleSampleHtml}</div>` : `<div class="mt-2 rounded-lg border border-blue-100 bg-white p-2 text-blue-900">No pending found-online records need review in this run. Approved or live records have been removed from this pending panel.</div>`}`;
      if (sourceReviewRecords.length) {
        statusEl.innerHTML += `<div class="mt-3 rounded-xl border border-amber-100 bg-amber-50 p-3">
          <div class="font-black text-amber-950">Source review records</div>
          <div class="mt-1 text-amber-900">These are not properties yet. No phone number is not a blocker if a public social profile exists, but website-only sources are blocked. Records stay parked when they still need a specific 2026+ social property post, source URL, location/area, usable image/source evidence, or public contact path before King queues a listing. Missing source prices become Price upon application.</div>
          <div class="mt-2 space-y-2">${sourceReviewRecords.map((item) => adminSourceReviewRecordSummaryHtml(item)).join("")}</div>
        </div>`;
      }
      adminScrubPendingSeedStatusPanel(statusEl);
    }
    toast("Found-online listings are ready for King review.");
    await renderAdminDashboard();
    setAdminWorkflowTab("review");
    adminScrollTo("#admin-review-queue-control");
  } catch (e) {
    if (statusEl) {
      statusEl.classList.remove("hidden");
      statusEl.innerHTML = `Could not create found-online listings: ${adminEscape(e.message || "Unknown error")}`;
    }
    toast(`Found-online seed failed: ${e.message || "error"}`);
  } finally {
    if (button) {
      button.disabled = false;
      button.classList.remove("opacity-60", "cursor-wait");
    }
  }
}

function adminSourceRecordKind(item = {}) {
  const kind = String(item.source_record_kind || item.metadata?.source_record_kind || "").trim();
  if (kind) return kind;
  const sourceType = String(item.source_type || item.sourceType || "").toLowerCase();
  if (
    sourceType.includes("search_feed")
    || sourceType.includes("hashtag_feed")
    || sourceType.includes("marketplace_feed")
    || sourceType.includes("group_search_feed")
    || sourceType.includes("public_video_search_feed")
    || sourceType.includes("public_reel_search_feed")
  ) return "discovery_feed";
  return "source_page";
}

function adminSourceRecordLabel(item = {}) {
  return adminSourceRecordKind(item) === "source_page"
    ? "Page/channel/account"
    : "Discovery feed";
}

function adminSourceRegistryHtml(data = {}) {
  const sources = Array.isArray(data.sources) ? data.sources : [];
  const summary = data.summary || {};
  const totalCount = Number(data.count || summary.count || sources.length || 0);
  const returnedCount = Number(data.returned_count || sources.length || 0);
  const byPlatform = data.by_platform || summary.by_platform || {};
  const platformText = Object.entries(byPlatform)
    .map(([platform, count]) => `${platform}: ${count}`)
    .join(" • ");
  const activeCount = summary.reviewed_source_pages_count || sources.filter((item) => item.status === "active" && adminSourceRecordKind(item) === "source_page").length;
  const candidateCount = summary.discovery_feed_count || sources.filter((item) => adminSourceRecordKind(item) === "discovery_feed").length;
  const rows = sources.map((item) => `
    <tr class="border-t border-emerald-100">
      <td class="py-2 pr-3 font-bold text-emerald-950">${adminEscape(item.source_name || item.name || "-")}</td>
      <td class="py-2 pr-3 uppercase text-[10px] font-black text-emerald-700">${adminEscape(item.platform || "-")}</td>
      <td class="py-2 pr-3">${adminEscape(adminSourceRecordLabel(item))}</td>
      <td class="py-2 pr-3">${adminEscape(item.source_type || "-")}</td>
      <td class="py-2 pr-3">${adminEscape(item.contact_phone || item.contact_phone_alt || item.contact_email || item.website || item.source_url || "Source review needed")}</td>
      <td class="py-2 pr-3">${item.can_contact_directly ? "Yes" : item.source_url ? "Source/social" : "Review first"}</td>
      <td class="py-2 pr-3">${adminEscape(item.status || "-")}</td>
      <td class="py-2"><a href="${adminAttr(item.source_url || "#")}" target="_blank" rel="noopener" class="font-bold text-emerald-800 underline">Open page/feed</a></td>
    </tr>`).join("");
  return `
    <div class="flex items-start justify-between gap-3 flex-wrap">
      <div>
        <div class="font-black text-emerald-950">Property source database</div>
        <div class="mt-1">${adminEscape(totalCount)} public source records loaded for daily found-online discovery.</div>
        <div class="mt-1 text-emerald-900"><span class="font-bold">${adminEscape(activeCount || 0)}</span> reviewed pages/channels/accounts • <span class="font-bold">${adminEscape(candidateCount || 0)}</span> discovery feeds/search terms to promote into real pages.</div>
        <div class="mt-1 text-[11px] text-emerald-800">Important: this table is the fishing net, not the approval queue. It stores social source pages, channels, accounts, hashtags, and search feeds across X/Twitter, Instagram, TikTok, YouTube, Facebook, and student accommodation social sources. Website-only sources are disabled. Individual posts are stored on found-online property records only after King finds a specific 2026+ social listing with source URL, contact route, location/area, and usable image/source evidence. Missing source prices become Price upon application.</div>
        ${platformText ? `<div class="mt-1 text-emerald-800">${adminEscape(platformText)}</div>` : ""}
        ${sources.length ? `<div class="mt-1 text-[11px] text-emerald-700">Showing ${adminEscape(returnedCount)} source records below. The full ${adminEscape(totalCount)}-record database stays server-side so this panel does not time out.</div>` : ""}
      </div>
      <button type="button" onclick="adminLoadPropertySourceRegistry()" class="border border-emerald-300 text-emerald-800 hover:bg-white px-3 py-1.5 rounded-lg text-xs font-bold">Refresh Sources</button>
    </div>
    ${rows ? `<div class="mt-3 max-h-[560px] overflow-auto rounded-xl border border-emerald-100 bg-white"><table class="min-w-full text-left text-[11px]"><thead class="sticky top-0 bg-emerald-50 text-emerald-900"><tr><th class="py-2 pr-3 pl-2">Name</th><th class="py-2 pr-3">Platform</th><th class="py-2 pr-3">Record</th><th class="py-2 pr-3">Type</th><th class="py-2 pr-3">Contact</th><th class="py-2 pr-3">Direct</th><th class="py-2 pr-3">Status</th><th class="py-2 pr-2">Source page/feed</th></tr></thead><tbody>${rows}</tbody></table></div>` : `<div class="mt-3 rounded-xl border border-emerald-100 bg-white p-3">No source records loaded yet.</div>`}`;
}

function adminSourceRegistryPanelElement() {
  if (activeAdminWorkflowTab === "student-sweep" || activeAdminWorkflowTab === "youtube-sweep") {
    return adminSocialStatusElement();
  }
  return document.getElementById("admin-source-registry-panel") || adminSocialStatusElement();
}

async function adminLoadPropertySourceRegistry() {
  if (!canUseLiveAdminApi()) {
    toast("Sign in as admin or save ADMIN_API_KEY first.");
    return;
  }
  const panel = adminSourceRegistryPanelElement();
  const button = document.getElementById("admin-load-source-registry-btn");
  if (button) {
    button.disabled = true;
    button.classList.add("opacity-60", "cursor-wait");
  }
  if (panel) {
    panel.classList.remove("hidden");
    panel.innerHTML = "Loading source database...";
  }
  try {
    const response = await apiRequest("/api/admin/property-source-registry?limit=500", {
      method: "GET",
      headers: adminAuthHeaders()
    });
    if (panel) panel.innerHTML = adminSourceRegistryHtml(response?.data || {});
    toast("Source database loaded.");
  } catch (e) {
    if (panel) {
      panel.classList.remove("hidden");
      panel.innerHTML = `Could not load source database: ${adminEscape(e.message || "Unknown error")}`;
    }
    toast(`Source database failed: ${e.message || "error"}`);
  } finally {
    if (button) {
      button.disabled = false;
      button.classList.remove("opacity-60", "cursor-wait");
    }
  }
}

async function adminImportFoundOnlineSourcePosts() {
  if (!canUseLiveAdminApi()) {
    toast("Sign in as admin or save ADMIN_API_KEY first.");
    return;
  }
  const raw = window.prompt("Paste a JSON array of extracted 2026+ source posts. Each post should include post_url/source_url, title, area/location, price or price_text, platform, source_name, and any image/contact fields.");
  if (!raw) return;
  let posts = [];
  try {
    const parsed = JSON.parse(raw);
    posts = Array.isArray(parsed) ? parsed : (Array.isArray(parsed.posts) ? parsed.posts : []);
  } catch (e) {
    toast("Source post import must be valid JSON.");
    return;
  }
  if (!posts.length) {
    toast("No source posts found in the JSON.");
    return;
  }
  const statusEl = document.getElementById("admin-found-online-status");
  const button = document.getElementById("admin-import-found-online-posts-btn");
  if (button) {
    button.disabled = true;
    button.classList.add("opacity-60", "cursor-wait");
  }
  if (statusEl) {
    statusEl.classList.remove("hidden");
    statusEl.innerHTML = `Importing ${adminEscape(posts.length)} extracted source posts into the King review intake...`;
  }
  try {
    const response = await apiRequest("/api/admin/found-online-source-posts/import", {
      method: "POST",
      headers: adminAuthHeaders(),
      body: { posts }
    });
    const data = response?.data || {};
    const queued = Array.isArray(data.queued_listings) ? data.queued_listings : [];
    const sourceReview = Array.isArray(data.source_review_records) ? data.source_review_records : [];
    const duplicateWarnings = Array.isArray(data.duplicate_warnings) ? data.duplicate_warnings : [];
    if (statusEl) {
      statusEl.innerHTML = `
        <div class="font-black">Source posts imported</div>
        <div class="mt-1">${adminEscape(data.created_properties || 0)} new properties queued. ${adminEscape(data.existing_properties || 0)} duplicate/existing links were blocked. ${adminEscape(sourceReview.length)} need source review before queueing.</div>
        <div class="mt-1">Import rule: curated exact YouTube social-source properties and other public social posts from 1 January 2026 onward with source URL, location/area, usable source evidence, official embed/link, and a public social/direct contact route are queued. Website-only sources are ignored. If the source does not publish a price, the property is queued as Price upon application. Location is the approval non-negotiable. Source-only broker profiles are not created automatically; the source owner must register or claim one.</div>
        ${queued.length ? `<div class="mt-2 space-y-2">${queued.slice(0, 12).map((item) => adminSeededListingSummaryHtml(item, { pendingPanel: true })).join("")}</div>` : ""}
        ${adminDuplicateSourceWarningHtml(duplicateWarnings)}
        ${sourceReview.length ? `<div class="mt-2 rounded-xl border border-amber-100 bg-amber-50 p-3 text-amber-900"><div class="font-black">Source review needed</div><div class="mt-2 space-y-2">${sourceReview.slice(0, 12).map((item) => adminSourceReviewRecordSummaryHtml(item)).join("")}</div></div>` : ""}`;
    }
    toast("Source post import finished.");
    await renderAdminDashboard();
    setAdminWorkflowTab("review");
    adminScrollTo("#admin-review-queue-control");
  } catch (e) {
    if (statusEl) {
      statusEl.classList.remove("hidden");
      statusEl.innerHTML = `Could not import source posts: ${adminEscape(e.message || "Unknown error")}`;
    }
    toast(`Source post import failed: ${e.message || "error"}`);
  } finally {
    if (button) {
      button.disabled = false;
      button.classList.remove("opacity-60", "cursor-wait");
    }
  }
}

function adminDuplicateSourceWarningHtml(duplicateWarnings = []) {
  const warnings = Array.isArray(duplicateWarnings) ? duplicateWarnings.filter(Boolean) : [];
  if (!warnings.length) return "";
  return `<div class="mt-2 rounded-xl border border-amber-200 bg-amber-50 p-3 text-amber-950">
    <div class="font-black">Duplicate social links blocked</div>
    <div class="mt-1 text-[11px]">These links were already loaded before, so makaug did not create another property.</div>
    <div class="mt-2 space-y-2">${warnings.slice(0, 12).map((item) => `<div class="rounded-lg border border-amber-100 bg-white p-2">
      <div class="font-bold">${adminEscape(item.title || "Existing property")}</div>
      <div class="mt-0.5 text-[11px]">${adminEscape(item.status || "existing")} ${item.property_url ? `• <a href="${adminAttr(item.property_url)}" target="_blank" rel="noopener" class="font-bold underline">Open existing</a>` : ""}</div>
      ${item.source_url ? `<div class="mt-0.5 break-words text-[10px]">${adminEscape(item.source_url)}</div>` : ""}
    </div>`).join("")}</div>
  </div>`;
}

function adminSocialCaptureHelperScript() {
  return `(async function(){
  var clean=function(value){return String(value||"").replace(/\\s+/g," ").trim();};
  var normalize=function(href){
    try {
      var u=new URL(href,location.href);
      var host=u.hostname.replace(/^www\\./,"").toLowerCase();
      var path=u.pathname || "";
      if (host==="youtu.be") {
        var shortId=path.replace(/^\\/+/, "").split("/")[0];
        return shortId ? "https://www.youtube.com/watch?v="+shortId : "";
      }
      if (host.endsWith("youtube.com")) {
        if (path==="/watch" && u.searchParams.get("v")) return "https://www.youtube.com/watch?v="+u.searchParams.get("v");
        if (path.indexOf("/shorts/")===0) return "https://www.youtube.com/shorts/"+path.split("/")[2];
      }
      if (host.endsWith("tiktok.com")) {
        var tik=path.match(/^\\/@[^/]+\\/video\\/\\d+/);
        if (tik) return "https://www.tiktok.com"+tik[0];
      }
      if (host.endsWith("instagram.com")) {
        var insta=path.match(/^\\/(p|reel|tv)\\/[^/]+/);
        if (insta) return "https://www.instagram.com"+insta[0]+"/";
      }
      if (host==="x.com" || host==="twitter.com" || host.endsWith(".x.com") || host.endsWith(".twitter.com")) {
        var x=path.match(/^\\/[^/]+\\/status\\/\\d+/);
        if (x) return "https://x.com"+x[0];
      }
      if (host.endsWith("facebook.com") || host.endsWith("fb.watch")) {
        if (host.endsWith("fb.watch")) return u.origin+path;
        if (path.indexOf("/watch/")===0 && u.searchParams.get("v")) return "https://www.facebook.com/watch/?v="+u.searchParams.get("v");
        if (path.indexOf("/reel/")===0) return "https://www.facebook.com"+path.split("/").slice(0,3).join("/");
        if (path.indexOf("/groups/")===0 && path.indexOf("/posts/")>0) return "https://www.facebook.com"+path.split("/").slice(0,5).join("/");
        if (/\\/posts\\//.test(path)) return "https://www.facebook.com"+path.split("/").slice(0,4).join("/");
        if (/\\/videos\\//.test(path)) return "https://www.facebook.com"+path.split("/").slice(0,4).join("/");
        if (path==="/story.php" && u.searchParams.get("story_fbid")) return u.href;
        if (path==="/permalink.php" && u.searchParams.get("story_fbid")) return u.href;
      }
      return "";
    } catch (error) {
      return "";
    }
  };
  var seen={};
  var rows=[];
  Array.prototype.slice.call(document.querySelectorAll("a[href]")).forEach(function(anchor){
    var url=normalize(anchor.href);
    if (!url || seen[url]) return;
    seen[url]=true;
    var card=anchor.closest("article,[data-e2e*=video],[data-testid*=tweet],li,div") || anchor;
    var text=clean(card.innerText || anchor.innerText || anchor.getAttribute("aria-label") || document.title || "").slice(0,220);
    rows.push(url+(text ? " | "+text : ""));
  });
  if (!rows.length) {
    alert("No exact social post links found on this visible page. Open a video/post/grid source page first, then run the helper again.");
    return;
  }
  var output=rows.join("\\n");
  try {
    await navigator.clipboard.writeText(output);
  } catch (error) {
    var box=document.createElement("textarea");
    box.value=output;
    box.style.position="fixed";
    box.style.left="8px";
    box.style.top="8px";
    box.style.width="80vw";
    box.style.height="40vh";
    box.style.zIndex="2147483647";
    document.body.appendChild(box);
    box.focus();
    box.select();
  }
  alert("makaug copied "+rows.length+" exact social post link(s). Go back to King, click Paste Captured Links, and paste.");
})();`;
}

function adminSocialCaptureBookmarkletUrl() {
  return `javascript:${encodeURIComponent(adminSocialCaptureHelperScript())}`;
}

async function adminCopyTextToClipboard(text) {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch (error) {
    return false;
  }
}

