function listingWhatsappContactText(key, vars = {}, lang = currentLang || "en") {
  const fallback = LANG_FALLBACK[lang] || "en";
  const template = LISTING_WHATSAPP_CONTACT_I18N[lang]?.[key]
    || LISTING_WHATSAPP_CONTACT_I18N[fallback]?.[key]
    || LISTING_WHATSAPP_CONTACT_I18N.en[key]
    || "";
  return Object.entries(vars).reduce((acc, [name, value]) => (
    acc.replaceAll(`{${name}}`, cleanWhatsappValue(value))
  ), template);
}

function buildListingWhatsappMessageForUi(p = {}) {
  const title = cleanWhatsappValue(p.title) || "this property";
  const category = getListingWhatsappCategory(p);
  const location = getListingWhatsappLocation(p);
  const url = getPropertyShareUrl(p);
  const price = fmtP(p.price || 0, p.period || p.price_period || "");
  const nextKey = category === "land" ? "landNext" : (category === "student" ? "studentNext" : "next");
  return [
    listingWhatsappContactText(category, { title }),
    listingWhatsappContactText("location", { location }),
    listingWhatsappContactText("price", { price }),
    listingWhatsappContactText(nextKey),
    url ? listingWhatsappContactText("link", { url }) : ""
  ].filter(Boolean).join(" ").replace(/\b(undefined|null)\b/gi, "").replace(/\s+/g, " ").trim();
}

async function recordListingWhatsappClick(propertyId, message = "", targetPhone = "", source = "listing_detail_whatsapp") {
  try {
    await apiRequest(`/api/properties/${encodeURIComponent(String(propertyId))}/whatsapp-click`, {
      method: "POST",
      body: {
        source,
        cta_location: source,
        message,
        target_phone: targetPhone,
        contact_name: authState?.user ? `${authState.user.first_name || ""} ${authState.user.last_name || ""}`.trim() : "",
        contact_phone: authState?.user?.phone || "",
        contact_email: authState?.user?.email || "",
        language: currentLang || "en"
      }
    });
  } catch (error) {
    console.warn("WhatsApp lead tracking failed", error.message || error);
  }
}

function openAdminWhatsAppMessageModal({ title = "Send WhatsApp message", listingLabel = "-", phone = "", message = "", manualUrl = "" } = {}) {
  const resolvedMessage = String(message || "").trim();
  const resolvedPhone = String(phone || "").trim();
  adminWhatsAppDraft = {
    phone: resolvedPhone,
    manualUrl,
    message: resolvedMessage
  };
  const titleEl = document.getElementById("admin-whatsapp-title");
  const subEl = document.getElementById("admin-whatsapp-subtitle");
  const phoneEl = document.getElementById("admin-whatsapp-phone");
  const listingEl = document.getElementById("admin-whatsapp-listing");
  const messageEl = document.getElementById("admin-whatsapp-message");
  if (titleEl) titleEl.textContent = title;
  if (subEl) subEl.textContent = manualUrl ? "Review the personalized message, then open WhatsApp to send it." : "Review or copy the personalized message.";
  if (phoneEl) phoneEl.textContent = resolvedPhone || "-";
  if (listingEl) listingEl.textContent = listingLabel || "-";
  if (messageEl) messageEl.value = resolvedMessage;
  openModal("admin-whatsapp-modal");
}

function openAdminWhatsAppFromModal() {
  const message = document.getElementById("admin-whatsapp-message")?.value || adminWhatsAppDraft?.message || "";
  const url = buildWhatsAppUrl(adminWhatsAppDraft?.phone || "", message) || adminWhatsAppDraft?.manualUrl || "";
  if (!url) {
    toast("No WhatsApp phone number is available.");
    return;
  }
  window.open(url, "_blank", "noopener,noreferrer");
}

async function copyAdminWhatsAppMessage() {
  const message = document.getElementById("admin-whatsapp-message")?.value || adminWhatsAppDraft?.message || "";
  if (!message.trim()) {
    toast("No message to copy.");
    return;
  }
  const ok = await copyTextToClipboard(message);
  toast(ok ? "Message copied." : "Copy failed.");
}

function adminOpenReviewShareWhatsApp() {
  const review = adminActiveReview || {};
  const message = String(review.extra_fields?.whatsapp_share_card || review.whatsapp_share_card || "").trim();
  if (!message) {
    toast("No WhatsApp share card is stored on this listing yet.");
    return;
  }
  openAdminWhatsAppMessageModal({
    title: "Share listing card",
    listingLabel: review.inquiry_reference || review.title || review.id || "-",
    phone: review.lister_phone || review.extra_fields?.contact_phone_alt || "",
    message
  });
}

function openAdminFollowUpWhatsApp(listingId) {
  const listing = adminLiveListings.find((p) => String(p.id) === String(listingId) || String(p.backend_id || "") === String(listingId))
    || adminRemoteListings.find((p) => String(p.id) === String(listingId) || String(p.backend_id || "") === String(listingId))
    || PROPERTIES.find((p) => String(p.id) === String(listingId) || String(p.backend_id || "") === String(listingId));
  if (!listing) {
    toast("Live listing not found in current snapshot.");
    return;
  }
  openAdminWhatsAppMessageModal({
    title: "Send 14-day follow-up",
    listingLabel: listing.inquiry_reference || listing.title || listing.id || "-",
    phone: listing.lister_phone || "",
    message: buildAdminFollowUpWhatsAppMessage(listing)
  });
}

function openAdminRejectedListingWhatsApp(listingId) {
  const listing = adminRemoteListings.find((p) => String(p.id) === String(listingId) || String(p.backend_id || "") === String(listingId))
    || PROPERTIES.find((p) => String(p.id) === String(listingId) || String(p.backend_id || "") === String(listingId));
  if (!listing) {
    toast("Rejected listing not found in current snapshot.");
    return;
  }
  const reason = listing.moderation_reason || listing.extra_fields?.moderation_reason || listing.review?.reason || "";
  openAdminWhatsAppMessageModal({
    title: "Send rejection follow-up",
    listingLabel: listing.inquiry_reference || listing.title || listing.id || "-",
    phone: listing.lister_phone || "",
    message: buildAdminRejectionWhatsAppMessage(listing, reason)
  });
}

function buildAdminWeeklyTipsMessage(user) {
  const firstName = user?.first_name || "there";
  return `Hi ${firstName}, this is makaug. Thanks for creating your account. We are sharing weekly Uganda property tips, saved-listing updates, and safety reminders to help you buy, rent, or list with confidence.`;
}

function openAdminUserTipsWhatsApp(userId) {
  const users = adminCurrentUsers || [];
  const user = users.find((item) => String(item.id) === String(userId));
  if (!user) {
    toast("User not found in current admin snapshot.");
    return;
  }
  openAdminWhatsAppMessageModal({
    title: "Send weekly tips outreach",
    listingLabel: `${user.first_name || ""} ${user.last_name || ""}`.trim() || user.email || user.phone || "-",
    phone: user.phone || "",
    message: buildAdminWeeklyTipsMessage(user)
  });
}

let adminCurrentUsers = [];

function campaignStatusMeta(status) {
  const normalized = String(status || "draft").toLowerCase();
  if (normalized === "live") return { cls: "bg-green-100 text-green-700", label: "Live" };
  if (normalized === "queued") return { cls: "bg-blue-100 text-blue-700", label: "Queued" };
  if (normalized === "sent") return { cls: "bg-emerald-100 text-emerald-700", label: "Sent" };
  if (normalized === "cancelled") return { cls: "bg-red-100 text-red-700", label: "Cancelled" };
  return { cls: "bg-gray-100 text-gray-700", label: "Draft" };
}

function deriveUserInterestSummary(user = {}) {
  const interests = [];
  if (Number(user.listings_count || 0) > 0) interests.push("Lists properties");
  if (Number(user.inquiries_count || 0) > 0) interests.push("Actively enquiring");
  if (Number(user.property_saves_count || 0) > 0) interests.push("Saving homes");
  if (Number(user.route_events_count || 0) > 0) interests.push("Checks routes");
  if (Number(user.property_views_count || 0) > 3) interests.push("Browsing heavily");
  const profile = user.profile_data && typeof user.profile_data === "object" ? user.profile_data : {};
  if (profile.primary_goal) interests.push(profile.primary_goal);
  if (profile.university) interests.push(`Student: ${profile.university}`);
  if (profile.agent_specialities) interests.push(`Agent: ${profile.agent_specialities}`);
  if (!interests.length) return "New or low-activity account";
  return interests.slice(0, 2).join(" • ");
}

function renderAdminOutreachOverview({ summary = {}, users = [], agents = [], fieldAgents = [], propertyRequests = [], campaigns = [] } = {}) {
  const wrap = document.getElementById("admin-outreach-overview");
  if (!wrap) return;
  const userSummary = summary?.users || {};
  const liveAgents = (agents || []).filter((agent) => String(agent?.status || "").toLowerCase() === "approved").length;
  const pendingAgents = (agents || []).filter((agent) => String(agent?.status || "").toLowerCase() === "pending").length;
  const activeFieldAgents = (fieldAgents || []).filter((user) => String(user?.status || "active").toLowerCase() === "active").length;
  const suspendedFieldAgents = (fieldAgents || []).filter((user) => String(user?.status || "").toLowerCase() === "suspended").length;
  const liveCampaigns = (campaigns || []).filter((campaign) => String(campaign?.status || "").toLowerCase() === "live").length;
  const draftCampaigns = (campaigns || []).filter((campaign) => ["draft", "queued"].includes(String(campaign?.status || "").toLowerCase())).length;
  const cards = [
    {
      label: "Active Accounts",
      value: Number(userSummary.active ?? users.length ?? 0),
      note: `${Number(userSummary.weekly_tips_opt_in ?? 0)} on weekly tips`,
      tone: "text-green-700"
    },
    {
      label: "Marketing Consent",
      value: Number(userSummary.marketing_opt_in ?? 0),
      note: "WhatsApp / outreach eligible",
      tone: "text-blue-700"
    },
    {
      label: "Field Agents",
      value: activeFieldAgents,
      note: `${suspendedFieldAgents} paused`,
      tone: "text-indigo-700"
    },
    {
      label: "Brokers Live / Pending",
      value: `${liveAgents}/${pendingAgents}`,
      note: "Approved vs awaiting review",
      tone: "text-emerald-700"
    },
    {
      label: "Property Requests",
      value: propertyRequests.length,
      note: "People looking for help",
      tone: "text-amber-700"
    },
    {
      label: "Campaigns",
      value: liveCampaigns,
      note: `${draftCampaigns} draft or queued`,
      tone: "text-fuchsia-700"
    },
    {
      label: "Recent Interest",
      value: users.filter((user) => Number(user.inquiries_count || 0) > 0 || Number(user.property_saves_count || 0) > 0).length,
      note: "Accounts showing buying intent",
      tone: "text-sky-700"
    },
    {
      label: "Protected Access",
      value: Number(userSummary.phone_verified ?? 0),
      note: "Verified phone accounts",
      tone: "text-gray-900"
    }
  ];
  wrap.innerHTML = cards.map((card) => `
    <div class="rounded-xl border border-gray-200 bg-white p-3">
      <div class="text-xs uppercase tracking-wide font-semibold text-gray-500">${card.label}</div>
      <div class="text-2xl font-black mt-1 ${card.tone}">${adminEscape(card.value)}</div>
      <div class="text-[11px] text-gray-500 mt-1">${adminEscape(card.note)}</div>
    </div>
  `).join("");
}

function adMoney(value) {
  return `UGX ${Number(value || 0).toLocaleString("en-UG")}`;
}

function adListText(value) {
  const list = Array.isArray(value) ? value : [];
  return list.length ? list.join(", ") : "-";
}

function adStatusBadge(status, type = "lead") {
  const normalized = String(status || (type === "payment" ? "unpaid" : "draft")).toLowerCase();
  const map = {
    new: "bg-emerald-100 text-emerald-700",
    contacted: "bg-sky-100 text-sky-700",
    proposal_sent: "bg-fuchsia-100 text-fuchsia-700",
    won: "bg-green-100 text-green-700",
    lost: "bg-red-100 text-red-700",
    archived: "bg-gray-100 text-gray-700",
    draft: "bg-gray-100 text-gray-700",
    awaiting_payment: "bg-amber-100 text-amber-800",
    paid: "bg-green-100 text-green-700",
    live: "bg-emerald-100 text-emerald-700",
    paused: "bg-yellow-100 text-yellow-700",
    completed: "bg-slate-100 text-slate-700",
    cancelled: "bg-red-100 text-red-700",
    unpaid: "bg-red-100 text-red-700",
    invoiced: "bg-amber-100 text-amber-800",
    refunded: "bg-gray-100 text-gray-700",
    waived: "bg-blue-100 text-blue-700"
  };
  return `<span class="text-[11px] font-semibold px-2 py-1 rounded ${map[normalized] || "bg-gray-100 text-gray-700"}">${adminEscape(normalized.replace(/_/g, " "))}</span>`;
}

