function languageDisplayName(code) {
  return {
    en: "English",
    lg: "Luganda",
    sw: "Kiswahili",
    ac: "Acholi",
    ny: "Runyankole",
    rn: "Rukiga",
    sm: "Lusoga",
    am: "Amharic",
    ar: "Arabic"
  }[String(code || "en").toLowerCase()] || "English";
}

function renderAdminUsersRows(users) {
  const wrap = document.getElementById("admin-users-table");
  if (!wrap) return;
  const search = (document.getElementById("admin-users-q")?.value || "").trim().toLowerCase();
  const roleFilter = (document.getElementById("admin-users-role")?.value || "").trim().toLowerCase();
  const weeklyOnly = (document.getElementById("admin-users-tips")?.value || "") === "weekly";
  adminCurrentUsers = Array.isArray(users) ? users : [];
  const view = adminApplyLaunchCleanFilter(adminCurrentUsers).filter((user) => {
    const role = String(user.role || "buyer_renter").toLowerCase();
    const hay = [
      user.first_name,
      user.last_name,
      user.email,
      user.phone,
      user.role,
      user.preferred_language
    ].filter(Boolean).join(" ").toLowerCase();
    if (roleFilter && role !== roleFilter) return false;
    if (weeklyOnly && user.weekly_tips_opt_in === false) return false;
    if (search && !hay.includes(search)) return false;
    return true;
  });
  if (!view.length) {
    wrap.innerHTML = `<div class="text-sm text-gray-500 bg-gray-50 border border-gray-200 rounded-xl p-4">No account users found for the current filters.</div>`;
    return;
  }
  wrap.innerHTML = view.map((user) => {
    const userIdArg = adminListingIdArg(user.id);
    const name = `${user.first_name || ""} ${user.last_name || ""}`.trim() || "Unnamed user";
    const contact = [user.phone, user.email].filter(Boolean).join(" • ") || "-";
    const tips = user.weekly_tips_opt_in !== false;
    const marketing = user.marketing_opt_in !== false;
    const social = user.oauth_provider ? `${user.oauth_provider} linked` : "Password/OTP";
    const language = languageDisplayName(user.preferred_language || "en");
    const whatsappUrl = user.phone ? buildWhatsAppUrl(user.phone, `Hello ${user.first_name || "there"}, this is makaug. We are following up on your account and property journey.`) : "";
    const nextStatus = String(user.status || "active").toLowerCase() === "suspended" ? "active" : "suspended";
    const interestSummary = deriveUserInterestSummary(user);
    return `
      <div class="border border-gray-200 rounded-xl p-4 bg-white">
        <div class="flex items-start justify-between gap-3 flex-wrap">
          <div>
            <div class="font-bold text-gray-900">${adminEscape(name)}</div>
            <div class="text-xs text-gray-500 mt-1">${adminEscape(contact)}</div>
            <div class="text-xs text-gray-500 mt-1">${mapRoleLabel(user.role || "buyer_renter")} • ${adminEscape(user.status || "active")} • ${adminEscape(social)} • ${adminEscape(language)}</div>
            <div class="text-xs text-green-700 mt-1 font-semibold">${adminEscape(interestSummary)}</div>
          </div>
          <div class="flex gap-1.5 flex-wrap justify-end">
            <span class="text-[11px] font-semibold px-2 py-1 rounded ${tips ? "bg-green-100 text-green-700" : "bg-gray-100 text-gray-600"}">${tips ? "Weekly tips" : "No tips"}</span>
            <span class="text-[11px] font-semibold px-2 py-1 rounded ${marketing ? "bg-blue-100 text-blue-700" : "bg-gray-100 text-gray-600"}">${marketing ? "Alerts on" : "Alerts off"}</span>
          </div>
        </div>
        <div class="grid sm:grid-cols-5 gap-2 mt-3 text-xs">
          <div class="rounded-lg bg-gray-50 border border-gray-200 p-2"><div class="text-gray-500">Listings</div><div class="font-black text-gray-900">${adminEscape(user.listings_count || 0)}</div></div>
          <div class="rounded-lg bg-gray-50 border border-gray-200 p-2"><div class="text-gray-500">Enquiries</div><div class="font-black text-gray-900">${adminEscape(user.inquiries_count || 0)}</div></div>
          <div class="rounded-lg bg-gray-50 border border-gray-200 p-2"><div class="text-gray-500">Views</div><div class="font-black text-gray-900">${adminEscape(user.property_views_count || 0)}</div></div>
          <div class="rounded-lg bg-gray-50 border border-gray-200 p-2"><div class="text-gray-500">Saves</div><div class="font-black text-gray-900">${adminEscape(user.property_saves_count || 0)}</div></div>
          <div class="rounded-lg bg-gray-50 border border-gray-200 p-2"><div class="text-gray-500">Routes</div><div class="font-black text-gray-900">${adminEscape(user.route_events_count || 0)}</div></div>
        </div>
        <div class="mt-3 flex gap-2 flex-wrap">
          <button onclick="openAdminUserTipsWhatsApp(${userIdArg})" class="bg-green-700 hover:bg-green-600 text-white px-3 py-1.5 rounded-lg text-xs font-semibold">WhatsApp Tips</button>
	              ${whatsappUrl ? `<a href="${adminAttr(whatsappUrl)}" target="_blank" rel="noopener noreferrer" class="border border-green-200 text-green-700 hover:bg-green-50 px-3 py-1.5 rounded-lg text-xs font-semibold">Contact</a>` : ""}
	              ${user.email ? `<a href="mailto:${adminAttr(user.email)}?subject=${encodeURIComponent("makaug weekly property tips")}" class="border border-gray-300 text-gray-700 hover:bg-gray-50 px-3 py-1.5 rounded-lg text-xs font-semibold">Email</a>` : ""}
	              ${canUseLiveAdminApi() ? `<button onclick="adminSetUserStatus(${userIdArg}, '${nextStatus}')" class="border border-gray-300 text-gray-700 hover:bg-gray-50 px-3 py-1.5 rounded-lg text-xs font-semibold">${nextStatus === "active" ? "Restore Access" : "Block Account"}</button>` : ""}
	              ${canUseLiveAdminApi() ? `<button onclick="adminSetUserStatus(${userIdArg}, 'deleted')" class="border border-red-200 text-red-600 hover:bg-red-50 px-3 py-1.5 rounded-lg text-xs font-semibold">Delete Account</button>` : ""}
	            </div>
	          </div>`;
  }).join("");
}

function renderAdminBrokerRows(agents) {
  const wrap = document.getElementById("admin-broker-accounts-table");
  if (!wrap) return;
  const rows = adminApplyLaunchCleanFilter(agents).slice(0, 50);
  if (!rows.length) {
    wrap.innerHTML = `<div class="text-sm text-gray-500 bg-white border border-gray-200 rounded-xl p-4">No broker profiles found in the current dataset.</div>`;
    return;
  }
  wrap.innerHTML = rows.map((agent) => {
    const idArg = adminListingIdArg(agent.id);
    const registration = adminVerificationBadge(agent.registration_status);
    const status = String(agent.status || "pending").toLowerCase();
    const statusMeta = status === "approved"
      ? { cls: "bg-green-100 text-green-700", label: "Live" }
      : status === "rejected"
        ? { cls: "bg-red-100 text-red-700", label: "Rejected" }
        : status === "suspended"
          ? { cls: "bg-yellow-100 text-yellow-700", label: "Suspended" }
          : { cls: "bg-amber-100 text-amber-700", label: "Pending" };
    const contact = [agent.phone, agent.email].filter(Boolean).join(" • ") || "-";
    const whatsappUrl = agent.phone ? buildWhatsAppUrl(agent.phone, `Hello ${agent.name || "there"}, this is makaug. We are following up on your broker account.`) : "";
    const idDocumentUploaded = Boolean(agent.identity_document_url);
    const hasPrivacyConsent = agent.privacy_consent_accepted === true && agent.data_retention_notice_accepted === true;
    const makaugAgentNumber = agent.makaug_agent_number || "Pending number";
    const phoneVerified = Boolean(agent.contact_phone_verified_at);
    const expiryLabel = agent.id_expiry_date ? formatDateShort(agent.id_expiry_date) : "missing";
    const experienceLabel = agent.experience_years || agent.experience_years === 0
      ? `${agent.experience_years} year${Number(agent.experience_years) === 1 ? "" : "s"}`
      : "missing";
    const channelLabel = agent.agent_application_channel ? String(agent.agent_application_channel).replace(/_/g, " ") : "web";
    const approveLabel = status === "approved" ? "Move to Pending" : "Approve & send access";
    return `
      <div class="border border-gray-200 rounded-xl p-4 bg-white">
        <div class="flex items-start justify-between gap-3 flex-wrap">
          <div>
            <div class="font-bold text-gray-900">${adminEscape(agent.name || "Broker")}</div>
            <div class="text-xs text-gray-500 mt-1">${adminEscape(agent.company || "makaug")} • ${adminEscape(contact)}</div>
            <div class="text-xs text-gray-500 mt-1">${adminEscape(agent.area || "Uganda")} • ${adminEscape(agent.licence || "No licence recorded")}</div>
            <div class="text-[11px] text-gray-500 mt-1">Agent No: <strong>${adminEscape(makaugAgentNumber)}</strong> • Channel: ${adminEscape(channelLabel)}${agent.user_id ? ` • User linked: ${adminEscape(agent.user_id)}` : ""}</div>
            <div class="text-[11px] text-gray-500 mt-1">NIN: ${adminEscape(agent.nin ? "provided" : "missing")} • ID expiry: ${adminEscape(expiryLabel)} • ID photo: ${idDocumentUploaded ? "uploaded" : "missing"} • Profile photo: ${agent.profile_photo_url ? "uploaded" : "missing"} • Phone OTP: ${phoneVerified ? "verified" : "missing"} • Experience: ${adminEscape(experienceLabel)} • Privacy: ${hasPrivacyConsent ? "accepted" : "missing"}</div>
          </div>
          <div class="flex gap-1.5 flex-wrap justify-end">
            <span class="text-[11px] font-semibold px-2 py-1 rounded ${statusMeta.cls}">${statusMeta.label}</span>
            <span class="text-[11px] font-semibold px-2 py-1 rounded ${registration.cls}">${registration.label}</span>
          </div>
        </div>
        ${agent.verification_reason ? `<div class="mt-3 rounded-lg border border-amber-100 bg-amber-50 p-2 text-xs text-amber-900"><strong>Broker reason:</strong> ${adminEscape(agent.verification_reason)}</div>` : ""}
        <div class="grid sm:grid-cols-4 gap-2 mt-3 text-xs">
          <div class="rounded-lg bg-gray-50 border border-gray-200 p-2"><div class="text-gray-500">Live Listings</div><div class="font-black text-gray-900">${adminEscape(agent.live_listings || 0)}</div></div>
          <div class="rounded-lg bg-gray-50 border border-gray-200 p-2"><div class="text-gray-500">Pending</div><div class="font-black text-gray-900">${adminEscape(agent.pending_listings || 0)}</div></div>
          <div class="rounded-lg bg-gray-50 border border-gray-200 p-2"><div class="text-gray-500">Rejected</div><div class="font-black text-gray-900">${adminEscape(agent.rejected_listings || 0)}</div></div>
          <div class="rounded-lg bg-gray-50 border border-gray-200 p-2"><div class="text-gray-500">Sales</div><div class="font-black text-gray-900">${adminEscape(agent.sales || 0)}</div></div>
        </div>
        <div class="mt-3 flex flex-wrap gap-2">
          <button onclick="openBrokerProfile(${idArg})" class="border border-green-700 text-green-700 hover:bg-green-50 px-3 py-1.5 rounded-lg text-xs font-semibold">Open Profile</button>
          ${idDocumentUploaded ? `<a href="${adminAttr(agent.identity_document_url)}" target="_blank" rel="noopener noreferrer" class="border border-amber-300 text-amber-800 hover:bg-amber-50 px-3 py-1.5 rounded-lg text-xs font-semibold">Review ID</a>` : ""}
          ${whatsappUrl ? `<a href="${adminAttr(whatsappUrl)}" target="_blank" rel="noopener noreferrer" class="bg-green-700 hover:bg-green-600 text-white px-3 py-1.5 rounded-lg text-xs font-semibold">Contact Broker</a>` : ""}
          ${agent.email ? `<a href="mailto:${adminAttr(agent.email)}?subject=${encodeURIComponent("makaug broker follow-up")}" class="border border-gray-300 text-gray-700 hover:bg-gray-50 px-3 py-1.5 rounded-lg text-xs font-semibold">Email</a>` : ""}
          ${canUseLiveAdminApi() ? `<button onclick="adminSetAgentStatus(${idArg}, '${status === "approved" ? "pending" : "approved"}')" class="border border-gray-300 text-gray-700 hover:bg-gray-50 px-3 py-1.5 rounded-lg text-xs font-semibold">${approveLabel}</button>` : ""}
        </div>
      </div>`;
  }).join("");
}

function renderAdminFeaturedAgentsRows(agents) {
  const wrap = document.getElementById("admin-featured-agents-table");
  if (!wrap) return;
  const rows = adminApplyLaunchCleanFilter(agents)
    .filter((agent) => String(agent?.status || "approved").toLowerCase() !== "rejected")
    .sort((a, b) => {
      const af = a?.featured_homepage === true ? 1 : 0;
      const bf = b?.featured_homepage === true ? 1 : 0;
      if (af !== bf) return bf - af;
      const ar = Number(a?.rating || 0);
      const br = Number(b?.rating || 0);
      if (ar !== br) return br - ar;
      return Number(b?.live_listings || b?.listings || 0) - Number(a?.live_listings || a?.listings || 0);
    })
    .slice(0, 40);
  if (!rows.length) {
    wrap.innerHTML = `<div class="text-sm text-gray-500 bg-gray-50 border border-gray-200 rounded-xl p-4">No approved agents available for homepage placement yet.</div>`;
    return;
  }
  wrap.innerHTML = rows.map((agent) => {
    const idArg = adminListingIdArg(agent.id);
    const featured = agent.featured_homepage === true;
    const registration = adminVerificationBadge(agent.registration_status);
    return `
      <div class="border ${featured ? "border-green-200 bg-green-50" : "border-gray-200 bg-white"} rounded-xl p-4">
        <div class="flex items-start justify-between gap-3 flex-wrap">
          <div class="min-w-0">
            <div class="font-bold text-gray-900">${adminEscape(agent.name || "Agent")}</div>
            <div class="text-xs text-gray-500 mt-1">${adminEscape(agent.company || "makaug")} • ${adminEscape(agent.area || "Uganda")}</div>
            <div class="mt-2 flex flex-wrap items-center gap-2 text-[11px]">
              <span class="inline-flex items-center px-2 py-1 rounded-full ${registration.cls} font-semibold">${registration.label}</span>
              <span class="inline-flex items-center px-2 py-1 rounded-full bg-gray-100 text-gray-700 font-semibold">⭐ ${adminEscape(agent.rating || 0)}</span>
              <span class="inline-flex items-center px-2 py-1 rounded-full bg-gray-100 text-gray-700 font-semibold">${adminEscape(agent.live_listings || agent.listings || 0)} live</span>
              <span class="inline-flex items-center px-2 py-1 rounded-full bg-gray-100 text-gray-700 font-semibold">${adminEscape(agent.sales || 0)} sales</span>
            </div>
          </div>
          <span class="text-xs font-semibold px-2 py-1 rounded ${featured ? "bg-green-700 text-white" : "bg-gray-100 text-gray-700"}">${featured ? "Featured Agent" : "Available"}</span>
        </div>
        <div class="mt-3 flex flex-wrap gap-2">
          <button onclick="openBrokerProfile(${idArg})" class="border border-green-700 text-green-700 hover:bg-green-50 px-3 py-1.5 rounded-lg text-xs font-semibold">Open Profile</button>
          <button onclick="adminSetAgentFeatured(${idArg}, ${featured ? "false" : "true"})" class="${featured ? "bg-gray-800 hover:bg-gray-700" : "bg-green-700 hover:bg-green-600"} text-white px-3 py-1.5 rounded-lg text-xs font-semibold">${featured ? "Remove Featured" : "Feature on Homepage"}</button>
          <button onclick="adminSetAgentRegistrationStatus(${idArg}, '${agent.registration_status === "registered" ? "not_registered" : "registered"}')" class="border border-gray-300 text-gray-700 hover:bg-gray-50 px-3 py-1.5 rounded-lg text-xs font-semibold">${agent.registration_status === "registered" ? "Mark Pending" : "Mark Verified"}</button>
        </div>
      </div>`;
  }).join("");
}

function renderAdminPropertyRequestRows(requests) {
  const wrap = document.getElementById("admin-property-requests-table");
  if (!wrap) return;
  const rows = Array.isArray(requests) ? requests.slice(0, 25) : [];
  if (!rows.length) {
    wrap.innerHTML = `<div class="text-sm text-gray-500 bg-white border border-gray-200 rounded-xl p-4">No property requests have been submitted yet.</div>`;
    return;
  }
  wrap.innerHTML = rows.map((request) => {
    const metadata = (() => {
      if (request.metadata && typeof request.metadata === "object" && !Array.isArray(request.metadata)) return request.metadata;
      if (typeof request.metadata === "string") {
        try {
          const parsed = JSON.parse(request.metadata);
          return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
        } catch (_error) {
          return {};
        }
      }
      return {};
    })();
    const noMatchRequest = String(request.source || "").toLowerCase() === "whatsapp_no_match" || metadata.whatsapp_no_match === true;
    const matchStatus = String(request.match_status || metadata.match_status || "waiting_for_listing").replace(/_/g, " ");
    const leadIdArg = request.lead_id ? JSON.stringify(String(request.lead_id)) : "";
    const digits = String(request.phone || "").replace(/\D/g, "");
    const whatsappUrl = digits ? `https://wa.me/${digits}?text=${encodeURIComponent(`Hello ${request.full_name || ""}, this is makaug. We received your request and can help you find a property that matches your brief.`)}` : "";
    const budget = request.max_budget ? fmtP(request.max_budget, "") : "Budget not set";
    const heading = [request.listing_type || "Any type", request.preferred_locations || "Any location"].filter(Boolean).join(" • ");
    return `
      <div class="border ${noMatchRequest ? "border-amber-200 bg-amber-50" : "border-gray-200 bg-white"} rounded-xl p-4">
        <div class="flex items-start justify-between gap-3 flex-wrap">
          <div class="min-w-0">
            <div class="font-bold text-gray-900">${adminEscape(noMatchRequest ? "WhatsApp unavailable-property lead" : request.full_name || "Property request")}</div>
            <div class="text-xs text-gray-500 mt-1">${adminEscape([request.phone, request.email].filter(Boolean).join(" • ") || "-")}</div>
            <div class="text-xs text-gray-500 mt-1">${adminEscape(heading)} • ${adminEscape(budget)}</div>
            ${noMatchRequest ? `<div class="text-xs font-bold text-amber-800 mt-2">No exact match captured from WhatsApp. Match status: ${adminEscape(matchStatus)}. Keep open until customer contact or agent assignment.</div>` : ""}
          </div>
          <span class="text-[11px] font-semibold px-2 py-1 rounded ${noMatchRequest ? "bg-amber-100 text-amber-800" : "bg-green-100 text-green-700"}">${adminEscape(formatListingDate(request.created_at) || "New")}</span>
        </div>
        <div class="mt-3 rounded-xl border ${noMatchRequest ? "border-amber-100 bg-white" : "border-gray-100 bg-gray-50"} p-3 text-sm text-gray-700">${noMatchRequest ? `<span class="font-bold">Original WhatsApp:</span> ` : ""}${adminEscape(request.requirements || "No extra requirements recorded.")}</div>
        <div class="mt-3 flex flex-wrap gap-2">
          ${noMatchRequest && leadIdArg ? `<button type="button" onclick="adminOpenLeadMatchMessage(${leadIdArg})" class="bg-green-700 hover:bg-green-600 text-white px-3 py-1.5 rounded-lg text-xs font-semibold">Message Match</button>` : ""}
          ${whatsappUrl ? `<a href="${adminAttr(whatsappUrl)}" target="_blank" rel="noopener noreferrer" class="bg-green-700 hover:bg-green-600 text-white px-3 py-1.5 rounded-lg text-xs font-semibold">WhatsApp</a>` : ""}
          ${request.email ? `<a href="mailto:${adminAttr(request.email)}?subject=${encodeURIComponent("makaug property request follow-up")}" class="border border-gray-300 text-gray-700 hover:bg-gray-50 px-3 py-1.5 rounded-lg text-xs font-semibold">Email</a>` : ""}
        </div>
      </div>`;
  }).join("");
}

async function adminProvisionFieldAgent(event) {
  if (event) event.preventDefault();
  if (!canUseLiveAdminApi()) {
    toast("Sign in as admin or set ADMIN_API_KEY before creating Field Agent accounts.");
    return;
  }
  const firstName = (document.getElementById("admin-fa-first-name")?.value || "").trim();
  const lastName = (document.getElementById("admin-fa-last-name")?.value || "").trim();
  const email = (document.getElementById("admin-fa-email")?.value || "").trim();
  const idNumber = (document.getElementById("admin-fa-id-number")?.value || "").trim();
  const phoneInput = document.getElementById("admin-fa-phone");
  const whatsappInput = document.getElementById("admin-fa-whatsapp");
  const phone = normalizeAdminFieldAgentPhone(phoneInput?.value || "");
  const whatsappPhone = normalizeAdminFieldAgentPhone(whatsappInput?.value || "");
  const pin = (document.getElementById("admin-fa-pin")?.value || "").trim();
  const territory = (document.getElementById("admin-fa-territory")?.value || "").trim();
  const payoutRate = (document.getElementById("admin-fa-payout-rate")?.value || "").trim();
  const notes = (document.getElementById("admin-fa-notes")?.value || "").trim();
  const result = document.getElementById("admin-fa-provision-result");
  if (!firstName || !lastName || !email || !idNumber || !phone || !whatsappPhone || !/^\d{4}$/.test(pin)) {
    toast("Add first name, surname, email, ID number, phone, WhatsApp number, and a 4-digit PIN.");
    if (result) result.textContent = "The agent has not been saved. Add first name, surname, email, ID number, full phone, full WhatsApp number, and a 4-digit PIN.";
    return;
  }
  if (!isValidAdminFieldAgentPhone(phone)) {
    const message = adminFieldAgentPhoneHelp("phone");
    if (result) result.textContent = message;
    toast(message);
    phoneInput?.focus();
    return;
  }
  if (!isValidAdminFieldAgentPhone(whatsappPhone)) {
    const message = adminFieldAgentPhoneHelp("whatsapp");
    if (result) result.textContent = message;
    toast(message);
    whatsappInput?.focus();
    return;
  }
  if (phoneInput) phoneInput.value = phone;
  if (whatsappInput) whatsappInput.value = whatsappPhone;
  const btn = document.getElementById("admin-fa-provision-btn");
  const original = btn?.textContent || "Save Field Agent";
  if (btn) {
    btn.disabled = true;
    btn.textContent = "Saving...";
  }
  try {
    const idDocument = await adminFieldAgentFilePayload("admin-fa-id-document-file", "ID document");
    const signedContract = await adminFieldAgentFilePayload("admin-fa-contract-file", "signed contract");
    const res = await apiRequest("/api/admin/field-agents/provision", {
      method: "POST",
      headers: adminAuthHeaders(),
      body: {
        first_name: firstName,
        last_name: lastName,
        email,
        id_number: idNumber,
        phone,
        whatsapp_phone: whatsappPhone,
        pin,
        territory,
        payout_rate_ugx: payoutRate || 5000,
        preferred_language: currentLang || "en",
        notes,
        id_document: idDocument,
        signed_contract: signedContract
      }
    });
    const data = res?.data || {};
    if (result) {
      result.textContent = `Saved ${data.field_agent_code || "Field Agent"} for ${data.first_name || firstName}. Directory refreshed below; the saved agent is highlighted. Give the agent their Field Agent ID and 4-digit PIN privately.`;
    }
    const pinInput = document.getElementById("admin-fa-pin");
    if (pinInput) pinInput.value = "";
    const idDocInput = document.getElementById("admin-fa-id-document-file");
    if (idDocInput) idDocInput.value = "";
    const contractInput = document.getElementById("admin-fa-contract-file");
    if (contractInput) contractInput.value = "";
    const nextCode = document.getElementById("admin-fa-next-code");
    if (nextCode) nextCode.textContent = `Last saved Field Agent ID: ${data.field_agent_code || "auto-generated"}. Next save will auto-generate the next available number.`;
    await trackEvent("admin_field_agent_provisioned", { field_agent_code: data.field_agent_code || "", source_page: currentPage });
    toast("Field Agent ID and PIN created.");
    await renderAdminDashboard();
    if (data.id) {
      adminHighlightFieldAgentRow(data.id);
    }
  } catch (error) {
    if (result) result.textContent = error.message || "Could not create Field Agent account.";
    toast(error.message || "Could not create Field Agent account.");
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = original;
    }
  }
}

async function adminBroadcastFieldAgents(event) {
  if (event) event.preventDefault();
  if (!canUseLiveAdminApi()) {
    toast("Sign in as admin or set ADMIN_API_KEY before broadcasting to Field Agents.");
    return;
  }
  const territory = (document.getElementById("admin-fa-broadcast-territory")?.value || "").trim();
  const channel = (document.getElementById("admin-fa-broadcast-channel")?.value || "whatsapp").trim();
  const message = (document.getElementById("admin-fa-broadcast-message")?.value || "").trim();
  const bannerMessage = (document.getElementById("admin-fa-banner-message")?.value || "").trim();
  const result = document.getElementById("admin-fa-broadcast-result");
  if (!message && !bannerMessage) {
    toast("Add a broadcast message or dashboard banner first.");
    return;
  }
  const btn = document.getElementById("admin-fa-broadcast-btn");
  const original = btn?.textContent || "Send / publish";
  if (btn) {
    btn.disabled = true;
    btn.textContent = "Sending...";
  }
  try {
    const res = await apiRequest("/api/admin/field-agents/broadcast", {
      method: "POST",
      headers: adminAuthHeaders(),
      body: { territory, channel, message, banner_message: bannerMessage }
    });
    const data = res?.data || {};
    if (result) {
      const sentBits = [
        `${data.target_count || 0} agents`,
        data.banner_updated ? "banner updated" : "",
        `WhatsApp ${data.whatsapp_sent || 0}/${data.whatsapp_failed || 0}`,
        `Email ${data.email_sent || 0}/${data.email_failed || 0}`
      ].filter(Boolean).join(" • ");
      result.textContent = `Broadcast processed: ${sentBits}`;
    }
    await trackEvent("admin_field_agent_broadcast_sent", { territory: territory || "all", channel, source_page: currentPage });
    toast("Field Agent broadcast processed.");
    await renderAdminDashboard();
  } catch (error) {
    if (result) result.textContent = error.message || "Could not process Field Agent broadcast.";
    toast(error.message || "Could not process Field Agent broadcast.");
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = original;
    }
  }
}

async function adminDeleteFieldAgent(userId) {
  if (!userId) return;
  await adminSetUserStatus(userId, "deleted");
}

function adminFindFieldAgent(userId) {
  const id = String(userId || "");
  return (adminFieldAgents || []).find((user) => String(user.id || "") === id) || null;
}

function isSafeFieldAgentDocumentHref(href = "") {
  const value = String(href || "");
  return value.startsWith("/assets/docs/field-agent/")
    || value.startsWith("https://")
    || value.startsWith("http://")
    || value.startsWith("data:application/pdf")
    || value.startsWith("data:image/")
    || value.startsWith("data:application/msword")
    || value.startsWith("data:application/vnd.openxmlformats-officedocument");
}

function adminFieldAgentPublicDocument(profile = {}, key) {
  const doc = profile[key] && typeof profile[key] === "object" ? profile[key] : null;
  if (!doc) return null;
  const href = String(doc.data_url || doc.url || "");
  if (!href) return null;
  if (!isSafeFieldAgentDocumentHref(href)) return null;
  return {
    ...doc,
    href,
    name: doc.name || "Uploaded document"
  };
}

function adminFieldAgentProfile(user = {}) {
  return user.profile_data && typeof user.profile_data === "object" ? user.profile_data : {};
}

function adminFieldAgentPayoutRate(user = {}) {
  const profile = adminFieldAgentProfile(user);
  return Number(profile.payout_rate_ugx || user.field_agent_payout_rate_ugx || 5000) || 5000;
}

function adminFieldAgentAcceptedCount(user = {}) {
  return Number(user.approved_listings_count || 0) || 0;
}

function adminFieldAgentPendingCount(user = {}) {
  return Number(user.pending_listings_count || 0) || 0;
}

function adminFieldAgentRejectedCount(user = {}) {
  return Number(user.rejected_listings_count || 0) || 0;
}

function adminFieldAgentReachScore(user = {}) {
  const backendReach = Number(user.field_agent_reach_score || 0) || 0;
  if (backendReach) return backendReach;
  return (Number(user.property_views_count || 0) || 0)
    + (Number(user.property_saves_count || 0) || 0)
    + (Number(user.inquiries_count || 0) || 0)
    + (Number(user.route_events_count || 0) || 0);
}

function adminFieldAgentFridayDue(user = {}) {
  const backendDue = Number(user.field_agent_friday_due_ugx || 0) || 0;
  if (backendDue) return backendDue;
  return adminFieldAgentAcceptedCount(user) * adminFieldAgentPayoutRate(user);
}

function adminFieldAgentTerritory(user = {}) {
  const profile = adminFieldAgentProfile(user);
  return user.field_agent_territory || profile.field_agent_territory || profile.territory || "Uganda";
}

function enrichAdminFieldAgents(users = []) {
  const rows = Array.isArray(users) ? users.map((user) => ({ ...user })) : [];
  const performanceSort = (a, b) => {
    const acceptedDelta = adminFieldAgentAcceptedCount(b) - adminFieldAgentAcceptedCount(a);
    if (acceptedDelta) return acceptedDelta;
    const listingDelta = (Number(b.listings_count || 0) || 0) - (Number(a.listings_count || 0) || 0);
    if (listingDelta) return listingDelta;
    const reachDelta = adminFieldAgentReachScore(b) - adminFieldAgentReachScore(a);
    if (reachDelta) return reachDelta;
    return String(a.created_at || "").localeCompare(String(b.created_at || ""));
  };
  [...rows].sort(performanceSort).forEach((row, index) => {
    if (!row.field_agent_rank) row.field_agent_rank = index + 1;
    row.field_agent_reach_score = adminFieldAgentReachScore(row);
    row.field_agent_friday_due_ugx = adminFieldAgentFridayDue(row);
    row.field_agent_territory = adminFieldAgentTerritory(row);
  });
  const byTerritory = new Map();
  rows.forEach((row) => {
    const territory = adminFieldAgentTerritory(row);
    if (!byTerritory.has(territory)) byTerritory.set(territory, []);
    byTerritory.get(territory).push(row);
  });
  byTerritory.forEach((territoryRows, territory) => {
    territoryRows.sort(performanceSort).forEach((row, index) => {
      if (!row.field_agent_region_rank) row.field_agent_region_rank = index + 1;
      row.field_agent_region = row.field_agent_region || territory;
      row.field_agent_region_count = row.field_agent_region_count || territoryRows.length;
      row.field_agent_region_accepted_count = row.field_agent_region_accepted_count || territoryRows.reduce((total, item) => total + adminFieldAgentAcceptedCount(item), 0);
      row.field_agent_region_reach_score = row.field_agent_region_reach_score || territoryRows.reduce((total, item) => total + adminFieldAgentReachScore(item), 0);
    });
  });
  return rows;
}

function normalizeAdminFieldAgentPhone(value = "") {
  const raw = String(value || "").trim().replace(/[^\d+]/g, "");
  if (!raw) return "";
  if (/^00\d{10,15}$/.test(raw)) return `+${raw.slice(2)}`;
  if (/^0\d{9}$/.test(raw)) return `+256${raw.slice(1)}`;
  if (/^256\d{9}$/.test(raw)) return `+${raw}`;
  return raw;
}

function isValidAdminFieldAgentPhone(value = "") {
  return /^\+?[0-9]{10,15}$/.test(normalizeAdminFieldAgentPhone(value));
}

function adminFieldAgentPhoneHelp(kind = "phone") {
  const label = kind === "whatsapp" ? "WhatsApp" : "phone";
  return `Enter a full ${label} number with country code, e.g. +256701123456 or +447757773202. Short local test numbers are not saved.`;
}

function adminFieldAgentRowElementId(userId) {
  return `admin-field-agent-row-${String(userId || "").replace(/[^a-zA-Z0-9_-]/g, "-")}`;
}

function adminHighlightFieldAgentRow(userId) {
  const row = document.getElementById(adminFieldAgentRowElementId(userId));
  if (!row) return;
  row.scrollIntoView({ behavior: "smooth", block: "center" });
  row.classList.add("ring-2", "ring-blue-500", "ring-offset-2");
  window.setTimeout(() => row.classList.remove("ring-2", "ring-blue-500", "ring-offset-2"), 2600);
}

function adminFieldAgentName(user = {}) {
  return `${user.first_name || ""} ${user.last_name || ""}`.trim() || "Field Agent";
}

function adminFieldAgentCode(user = {}) {
  const profile = adminFieldAgentProfile(user);
  return profile.field_agent_code || profile.employee_number || "-";
}

function adminFieldAgentKpiTitle(kind = "agents") {
  const titles = {
    agents: "All Field Agents",
    active: "Active Field Agents",
    pending: "Pending listings",
    approved: "Accepted listings",
    rejected: "Rejected listings",
    payouts: "Friday payday breakdown"
  };
  return titles[kind] || titles.agents;
}

function adminFieldAgentKpiDescription(kind = "agents") {
  const descriptions = {
    agents: "Every Field Agent account currently returned by the backend feed, with direct review, contact, and payment actions.",
    active: "Field Agents whose accounts are active and able to sign in with their Field Agent ID and PIN.",
    pending: "Pending Field Agent-linked property records. Open each property record or jump into the agent review panel.",
    approved: "Accepted/live Field Agent-linked property records. These create the Friday payout calculation.",
    rejected: "Rejected Field Agent-linked property records. Open records to see rejection reasons and follow-up actions.",
    payouts: "Friday payout is calculated as accepted listings multiplied by each agent's payout/listing rate: accepted listings x payout/listing."
  };
  return descriptions[kind] || descriptions.agents;
}

function adminFieldAgentKpiEmpty(kind = "agents") {
  if (kind === "active") return "No active Field Agents found.";
  if (kind === "pending") return "No pending Field Agent-linked listings found.";
  if (kind === "approved") return "No accepted Field Agent-linked listings found.";
  if (kind === "rejected") return "No rejected Field Agent-linked listings found.";
  if (kind === "payouts") return "No Field Agent payout rows found.";
  return "No Field Agents found in the current backend feed.";
}

function adminFieldAgentPayoutPeriodOptions() {
  return [
    ["current_due", "Current due ledger"],
    ["this_friday", "This Friday"],
    ["previous_friday", "Previous Friday"],
    ["this_week", "This week so far"],
    ["last_7_days", "Last 7 days"],
    ["all", "All accepted"]
  ];
}

function adminNormalizeFieldAgentPayoutPeriod(value = "") {
  const allowed = new Set(adminFieldAgentPayoutPeriodOptions().map(([key]) => key));
  const normalized = String(value || "").trim().toLowerCase().replace(/\s+/g, "_");
  return allowed.has(normalized) ? normalized : "current_due";
}

function adminFormatDateOnly(value) {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  return date.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" });
}

function adminFieldAgentPayoutFallbackPayload(periodKey = adminFieldAgentPayoutPeriod) {
  const rows = enrichAdminFieldAgents(adminFieldAgents)
    .slice()
    .sort((a, b) => adminFieldAgentFridayDue(b) - adminFieldAgentFridayDue(a) || adminFieldAgentAcceptedCount(b) - adminFieldAgentAcceptedCount(a))
    .map((user) => {
      const accepted = adminFieldAgentAcceptedCount(user);
      const payoutRate = adminFieldAgentPayoutRate(user);
      return {
        id: user.id,
        first_name: user.first_name,
        last_name: user.last_name,
        phone: user.phone,
        email: user.email,
        status: user.status || "active",
        field_agent_code: adminFieldAgentCode(user),
        field_agent_territory: adminFieldAgentTerritory(user),
        accepted_count: accepted,
        payout_rate_ugx: payoutRate,
        payout_due_ugx: accepted * payoutRate,
        pay_by_date: "",
        listings: []
      };
    });
  const totalDue = rows.reduce((total, row) => total + (Number(row.payout_due_ugx || 0) || 0), 0);
  return {
    data: rows,
    meta: {
      period_key: adminNormalizeFieldAgentPayoutPeriod(periodKey),
      period_label: "Current due ledger",
      period_description: "Local directory snapshot. Sign in as King/admin to load exact weekly payout windows and accepted listing records from the backend.",
      payout_day: "Friday",
      pay_by_date: "",
      period_start: null,
      period_end: null,
      has_range: false,
      count: rows.length,
      due_count: rows.filter((row) => (Number(row.payout_due_ugx || 0) || 0) > 0).length,
      total_due_ugx: totalDue,
      provider: canUseLiveAdminApi() ? "fallback" : "missing_auth"
    }
  };
}

async function adminLoadFieldAgentPayouts(periodKey = adminFieldAgentPayoutPeriod) {
  const period = adminNormalizeFieldAgentPayoutPeriod(periodKey);
  if (!canUseLiveAdminApi()) return adminFieldAgentPayoutFallbackPayload(period);
  const res = await apiRequest(`/api/admin/field-agents/payouts?period=${encodeURIComponent(period)}&limit=10000`, { headers: adminAuthHeaders() });
  return {
    data: Array.isArray(res?.data) ? res.data : [],
    meta: { ...(res?.meta || {}), provider: "live" }
  };
}

function adminSetFieldAgentPayoutPeriod(periodKey = "current_due") {
  adminFieldAgentPayoutPeriod = adminNormalizeFieldAgentPayoutPeriod(periodKey);
  adminRenderFieldAgentKpiPanel("payouts");
}

function adminFieldAgentKpiShell(kind, bodyHtml, extraHtml = "") {
  const panel = document.getElementById("admin-field-agent-kpi-panel");
  if (!panel) return;
  panel.classList.remove("hidden");
  panel.innerHTML = `
    <div class="rounded-2xl border border-blue-100 bg-white p-4 shadow-sm">
      <div class="flex items-start justify-between gap-3 flex-wrap mb-4">
        <div>
          <div class="text-xs uppercase tracking-wide font-black text-blue-700">King drill-down</div>
          <h4 class="text-xl font-black text-gray-900 mt-1">${adminEscape(adminFieldAgentKpiTitle(kind))}</h4>
          <p class="text-xs text-gray-500 mt-1">${adminEscape(adminFieldAgentKpiDescription(kind))}</p>
        </div>
        <button type="button" onclick="adminCloseFieldAgentKpi()" class="border border-gray-200 text-gray-700 hover:bg-gray-50 rounded-lg px-3 py-1.5 text-xs font-bold">Close</button>
      </div>
      ${extraHtml}
      ${bodyHtml}
    </div>`;
}

function adminCloseFieldAgentKpi() {
  adminActiveFieldAgentKpi = "";
  document.getElementById("admin-field-agent-kpi-panel")?.classList.add("hidden");
}

function adminOpenFieldAgentKpi(kind = "agents") {
  adminActiveFieldAgentKpi = String(kind || "agents");
  adminRenderFieldAgentKpiPanel(adminActiveFieldAgentKpi);
  window.setTimeout(() => document.getElementById("admin-field-agent-kpi-panel")?.scrollIntoView({ behavior: "smooth", block: "start" }), 50);
}

