async function adminApproveSourcedCandidateOverride(listingId) {
  const review = adminActiveReview || {};
  if (!adminIsSourcedInventoryCandidate(review)) {
    toast("Found-online approval is only available on found-online intake records.");
    return;
  }
  if (!adminSourcedCandidateCanUseOverride(review)) {
    toast("Add a location or area before found-online approval.");
    return;
  }
  const sourceLinks = adminSourcedCandidateSourceLinks(review);
  const message = sourceLinks.length
    ? "Approve this found-online record? Location is present. This records that King reviewed the stored source/photo links and overrode the remaining non-location checks."
    : "Approve this found-online record? Location is present. No source links are stored on the record, so only continue if you verified the source evidence outside makaug.";
  const ok = window.confirm(message);
  if (!ok) return;
  await adminSetListingStatus(listingId, "approved", listingId, {
    sourced_candidate_override: true,
    found_online_location_confirmed: true,
    source_reviewed: true
  });
}

async function adminSetListingStatus(localId, nextStatus, backendId = "", options = {}) {
  const normalizedStatus = normalizeModerationStatus(nextStatus);
  const statusOptions = options && typeof options === "object" ? options : {};
  const isSourcedCandidateOverride = normalizedStatus === "approved" && statusOptions.sourced_candidate_override === true;
  const listing = PROPERTIES.find(
    (p) => String(p.id) === String(localId)
      || (backendId && String(p.backend_id || "") === String(backendId))
  ) || adminRemoteListings.find(
    (p) => String(p.id) === String(localId)
      || (backendId && String(p.backend_id || "") === String(backendId))
  ) || adminLiveListings.find(
    (p) => String(p.id) === String(localId)
      || (backendId && String(p.backend_id || "") === String(backendId))
  );
  if (!listing) {
    toast("Listing not found in current snapshot.");
    return;
  }

  const previousStatus = normalizeModerationStatus(listing.status);
  const wasPendingBeforeStatusUpdate = previousStatus === "pending"
    || adminCurrentPendingListings.some((item) => adminListingMatchesId(item, backendId || localId));
  const isLiveApi = !!backendId && canUseLiveAdminApi();
  if ((normalizedStatus === "approved" || normalizedStatus === "rejected") && isLiveApi && (!adminActiveReview || String(adminActiveReview.id) !== String(backendId))) {
    await openAdminListingReview(backendId);
    return;
  }

  if (normalizedStatus === "deleted") {
    const ok = window.confirm("Delete this listing from public pages? You can restore it from the admin dashboard.");
    if (!ok) return;
  }
  if (normalizedStatus === "approved" && adminActiveReview?.id && String(adminActiveReview.id) === String(backendId) && !isSourcedCandidateOverride) {
    const pendingWarnings = getAdminPendingWarningOverrideLabels(adminActiveReview);
    if (pendingWarnings.length) {
      toast(`Review and override warning evidence first: ${pendingWarnings.slice(0, 3).join(", ")}${pendingWarnings.length > 3 ? "..." : ""}`);
      return;
    }
  }
  let moderationReason = (document.getElementById("admin-review-reason")?.value || listing?.extra_fields?.moderation_reason || "").trim();
  const reviewNotes = (document.getElementById("admin-review-notes")?.value || "").trim();
  const checklist = getAdminReviewChecklistFromDom();
  if (isSourcedCandidateOverride && !moderationReason) {
    moderationReason = "Approved as found-online intake after location was confirmed and non-location source-review checks were overridden.";
    const reasonEl = document.getElementById("admin-review-reason");
    if (reasonEl) reasonEl.value = moderationReason;
  }
  if (normalizedStatus === "rejected" && !moderationReason) {
    moderationReason = buildAdminGeneratedDecisionReason(adminActiveReview) || "";
    const reasonEl = document.getElementById("admin-review-reason");
    if (reasonEl && moderationReason) reasonEl.value = moderationReason;
    if (!moderationReason.trim()) {
      toast("Rejection reason is required.");
      return;
    }
  }

  listing.status = normalizedStatus;
  listing.reviewed_at = new Date().toISOString();
  listing.extra_fields = listing.extra_fields && typeof listing.extra_fields === "object" ? listing.extra_fields : {};
  if (normalizedStatus === "rejected" && moderationReason.trim()) {
    listing.extra_fields.moderation_reason = moderationReason.trim();
  }
  if (normalizedStatus === "deleted") {
    listing.deleted_at = new Date().toISOString();
  } else if (listing.deleted_at) {
    delete listing.deleted_at;
  }

  let statusResponse = null;
  let ownerNotificationOpened = false;
  const maybeOpenOwnerNotification = () => {
    const waPayload = statusResponse?.notification?.whatsapp || {};
    if (!["approved", "rejected"].includes(normalizedStatus)) return false;
    if (!(waPayload.message || waPayload.manual_url || waPayload.phone || listing.lister_phone)) return false;
    const fallbackMessage = normalizedStatus === "rejected"
      ? buildAdminRejectionWhatsAppMessage(listing, moderationReason)
      : buildAdminApprovalWhatsAppMessage(listing);
    openAdminWhatsAppMessageModal({
      title: normalizedStatus === "approved" ? "Listing is live: send approval WhatsApp" : "Send rejection WhatsApp",
      listingLabel: statusResponse?.inquiry_reference || listing.inquiry_reference || listing.title || backendId || "-",
      phone: waPayload.phone || statusResponse?.lister_phone || listing.lister_phone || "",
      message: waPayload.message || fallbackMessage,
      manualUrl: waPayload.manual_url || ""
    });
    return true;
  };
  if (backendId) {
    try {
      if (isLiveApi && adminActiveReview?.id && String(adminActiveReview.id) === String(backendId)) {
        const savedReview = await adminPersistActiveReviewEditsBeforeStatus(backendId, moderationReason, reviewNotes, checklist);
        if (savedReview) Object.assign(listing, savedReview);
      }
      const response = await apiRequest(`/api/properties/${encodeURIComponent(backendId)}/status`, {
        method: "PATCH",
        headers: adminAuthHeaders(),
	        body: {
	          ...statusOptions,
	          fast_admin_render: true,
	          manual_notification_only: ["approved", "rejected"].includes(normalizedStatus),
	          status: normalizedStatus,
	          reason: moderationReason.trim() || undefined,
	          review_notes: reviewNotes || undefined,
	          checklist,
	          warning_overrides: getAdminReviewWarningOverrides(adminActiveReview)
        }
      });
      statusResponse = response?.data || null;
      if (statusResponse) {
        Object.assign(listing, statusResponse, {
          status: statusResponse.status || normalizedStatus,
          moderation_status: normalizeModerationStatus(statusResponse.status || normalizedStatus)
        });
        const remoteIdx = adminRemoteListings.findIndex((p) => String(p.id) === String(backendId) || String(p.backend_id || "") === String(backendId));
	        if (remoteIdx >= 0) adminRemoteListings[remoteIdx] = { ...adminRemoteListings[remoteIdx], ...listing };
	        const liveIdx = adminLiveListings.findIndex((p) => String(p.id) === String(backendId) || String(p.backend_id || "") === String(backendId));
	        if (liveIdx >= 0) adminLiveListings[liveIdx] = { ...adminLiveListings[liveIdx], ...listing };
	      }
	      adminRenderListingStatusLocally(listing, normalizedStatus, backendId || localId, {
	        wasPending: wasPendingBeforeStatusUpdate
	      });
	      if (!ownerNotificationOpened) ownerNotificationOpened = maybeOpenOwnerNotification();
	      if (normalizedStatus === "approved") {
	        try {
	          const detail = await apiRequest(`/api/properties/${encodeURIComponent(backendId)}`, {
	            headers: adminAuthHeaders()
          });
          const liveProperty = upsertPropertyForUi(mapRemotePropertyForUi(detail?.data || {}));
          if (liveProperty) liveProperty.status = "approved";
        } catch (e) {
          upsertPropertyForUi({
            ...listing,
            id: backendId,
            status: "approved",
            remote_source: "api"
          });
        }
      } else if (normalizedStatus !== "approved") {
        const existingPublic = PROPERTIES.find((p) => String(p.id) === String(backendId) || String(p.backend_id || "") === String(backendId));
        if (existingPublic) existingPublic.status = normalizedStatus;
      }
    } catch (e) {
      const details = Array.isArray(e.response?.details)
        ? e.response.details.join("; ")
        : (e.response?.details ? JSON.stringify(e.response.details) : "");
      toast(`Status update failed: ${details || e.message || "error"}`);
      return;
    }
  }

	  if (!ownerNotificationOpened) ownerNotificationOpened = maybeOpenOwnerNotification();

	  if (normalizedStatus === "approved") {
	    setAdminWorkflowTab("live");
	  } else if (["rejected", "hidden", "deleted"].includes(normalizedStatus)) {
	    setAdminWorkflowTab("actioned");
	  } else if (backendId && adminActiveReview?.id && String(adminActiveReview.id) === String(backendId)) {
	    await openAdminListingReview(backendId);
	  }
	  const refreshAfterStatus = () => {
	    renderAll();
	    resetMaps();
	    void renderAdminDashboard().catch((error) => {
	      toast(`Dashboard refresh failed: ${error.message || "error"}`);
	    });
	  };
	  if (typeof window !== "undefined" && typeof window.requestAnimationFrame === "function") {
	    window.requestAnimationFrame(refreshAfterStatus);
	  } else {
	    refreshAfterStatus();
	  }
	  toast(ownerNotificationOpened && normalizedStatus === "approved" ? "Listing approved. WhatsApp message is ready." : (normalizedStatus === "approved" ? "Listing approved and live." : `Listing updated: ${normalizedStatus}.`));
	}

async function adminSetListingFeatured(propertyId, featured) {
  const id = String(propertyId || "");
  if (!id) return;
  if (!canUseLiveAdminApi()) {
    const local = PROPERTIES.find((p) => String(p.id) === id || String(p.backend_id || "") === id);
    if (local) {
      local.featured = !!featured;
      local.featured_at = featured ? new Date().toISOString() : local.featured_at;
      local.extra_fields = {
        ...(local.extra_fields || {}),
        featured: !!featured,
        ...(featured ? { featured_at: local.featured_at } : {})
      };
      renderAll();
      await renderAdminDashboard();
      toast(featured ? "Listing featured locally." : "Listing removed from local featured.");
    } else {
      toast("Listing not found.");
    }
    return;
  }
  try {
    const response = await apiRequest(`/api/admin/properties/${encodeURIComponent(id)}/featured`, {
      method: "PATCH",
      headers: adminAuthHeaders(),
      body: { featured: !!featured }
    });
    const data = response?.data || {};
    const nextFeatured = data.featured === true || String(data.extra_fields?.featured || "").toLowerCase() === "true" || !!featured;
    const applyFeatured = (item) => {
      if (!item) return item;
      item.featured = nextFeatured;
      item.featured_at = data.featured_at || data.extra_fields?.featured_at || (nextFeatured ? new Date().toISOString() : item.featured_at);
      item.remote_source = item.remote_source || "api";
      item.extra_fields = {
        ...(item.extra_fields || {}),
        ...(data.extra_fields || {}),
        featured: nextFeatured,
        ...(nextFeatured && item.featured_at ? { featured_at: item.featured_at } : {})
      };
      return item;
    };
    applyFeatured(PROPERTIES.find((p) => String(p.id) === id || String(p.backend_id || "") === id));
    applyFeatured(adminRemoteListings.find((p) => String(p.id) === id || String(p.backend_id || "") === id));
    applyFeatured(adminLiveListings.find((p) => String(p.id) === id || String(p.backend_id || "") === id));
    let publicFeaturedRefreshed = false;
    try {
      const detail = await apiRequest(`/api/properties/${encodeURIComponent(id)}`, {
        headers: adminAuthHeaders()
      });
      const publicProperty = mapRemotePropertyForUi(detail?.data || {});
      publicProperty.featured = nextFeatured;
      publicProperty.featured_at = data.featured_at || data.extra_fields?.featured_at || publicProperty.featured_at;
      publicProperty.extra_fields = {
        ...(publicProperty.extra_fields || {}),
        ...(data.extra_fields || {}),
        featured: nextFeatured,
        ...(publicProperty.featured_at ? { featured_at: publicProperty.featured_at } : {})
      };
      upsertPropertyForUi(publicProperty);
    } catch (detailError) {
      await refreshPublicListingsFromApi({ silent: true });
      publicFeaturedRefreshed = true;
    }
    if (!publicFeaturedRefreshed) await refreshPublicListingsFromApi({ silent: true });
    renderAll();
    resetMaps();
    await renderAdminDashboard();
    toast(featured ? "Listing added to Featured Properties." : "Listing removed from Featured Properties.");
  } catch (e) {
    toast(`Featured update failed: ${e.message || "error"}`);
  }
}

