function pendingAdminControlAfterAuth() {
  const currentPath = normalizeRoutePath(window.location.pathname || "/");
  let path = currentPath;
  if (currentPath === "/login") {
    try {
      const next = new URLSearchParams(window.location.search || "").get("next") || "";
      if (next) path = normalizeRoutePath(new URL(next, window.location.origin).pathname);
    } catch (error) {
      path = currentPath;
    }
  }
  const control = adminControlForPath(path);
  return control ? { path, control } : null;
}

function preferredAudienceForResolvedUser(user, preferredAudience = "") {
  const preferred = String(preferredAudience || "").toLowerCase();
  if (preferred && preferred !== "finder") return preferred;
  return derivePortalMode(user, "");
}

async function finalizeAuth(data, source, preferredAudience = "") {
  const token = data?.token;
  const user = data?.user;
  if (!token || !user) throw new Error("Authentication response is incomplete");
  const responseRedirect = data?.redirectUrl || data?.redirect_url || "";
  preferredAudience = preferredAudienceForResolvedUser(user, preferredAudience || portalModeForDashboardUrl(responseRedirect));
  const resolvedMode = derivePortalMode(user, preferredAudience);
  const resolvedUser = { ...user, portal_mode: resolvedMode };
  if (preferredAudience === "agent" && user.role !== "agent_broker") {
    resolvedUser.portal_mode = "finder";
    toast("This account is not marked as a broker. Opening property finder dashboard.");
  }
  if (preferredAudience === "field_agent" && user.role !== "field_agent") {
    resolvedUser.portal_mode = "finder";
    toast("This account is not marked as a Field Agent. Opening Property Finder dashboard.");
  }
  if ((preferredAudience === "moderator" || preferredAudience === "staff" || preferredAudience === "operations") && user.role !== "moderator" && user.role !== "admin" && user.role !== "super_admin") {
    resolvedUser.portal_mode = "finder";
    toast("This account is not marked as staff. Opening property finder dashboard.");
  }
  if (preferredAudience === "admin" && user.role !== "admin" && user.role !== "super_admin") {
    resolvedUser.portal_mode = "finder";
    toast("This account is not marked as admin. Opening property finder dashboard.");
  }
	      persistAuthState(token, resolvedUser);
		      hydrateAccountForm();
		      closeModal("auth-modal");
		      closeAccountAccessDrawer();
		      toast(data?.message || `Welcome, ${user.first_name || "user"}`);
		      const pendingAdmin = resolvedUser.portal_mode === "admin" ? pendingAdminControlAfterAuth() : null;
		      if (pendingAdmin) {
		        try { window.history.replaceState({ page: "admin", source: "auth_admin_return", adminPath: pendingAdmin.path }, "", pendingAdmin.path); } catch (error) {}
		        await openAdminControl(pendingAdmin.control, { source: "auth_admin_return" });
		      } else {
		        openSignedInDashboard(dashboardRouteForPortalMode(resolvedUser.portal_mode) || responseRedirect);
		      }
		      if (resolvedUser.profile_data?.force_password_change === true || String(resolvedUser.profile_data?.force_password_change || "").toLowerCase() === "true") {
		        toast("Please change your temporary password in Account Settings.");
		      }
		      trackEvent("auth_success", { source, role: user.role || "" }).catch(() => {});
		    }

