function formatOtpDeliveryFallbackMessage(message, channel = "phone") {
  const raw = String(message || "").trim();
  const lower = raw.toLowerCase();
  const providerIssue = lower.includes("not configured")
    || lower.includes("blocked by microsoft 365 tenant policy")
    || lower.includes("failed to send otp")
    || lower.includes("failed to send otp email")
    || lower.includes("failed to send otp sms");
  if (!providerIssue) return raw || "Could not send OTP right now.";
  const modeLabel = channel === "email" ? "email" : "SMS";
  return `OTP delivery via ${modeLabel} is temporarily unavailable. For internal testing, use the authorized admin override code.`;
}

async function requestListingOtp() {
  const channel = lpListingOtpChannel === "email" ? "email" : "phone";
  const phone = normalizePhoneInput(lpVal("lp-verify-phone"));
  const email = (lpVal("lp-verify-email") || "").toLowerCase();
  if (channel === "phone") {
    if (!phone) {
      toast("Enter phone number first.");
      return;
    }
    if (!(/^\+2567\d{8}$/.test(phone) || /^\+256\d{9}$/.test(phone))) {
      toast("Enter a valid Uganda phone format before OTP.");
      return;
    }
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    toast("Enter a valid email address first.");
    return;
  }
  setButtonLoading("lp-send-otp-btn", true);
  try {
    const response = await apiRequest("/api/properties/request-submit-otp", {
      method: "POST",
      body: {
        channel,
        phone: channel === "phone" ? phone : undefined,
        email: channel === "email" ? email : undefined,
        preferred_language: currentLang || "en",
        audience: "listing"
      }
    });
    const otpStatus = document.getElementById("lp-otp-status");
    if (otpStatus) {
      otpStatus.className = "text-xs text-green-700 mt-1";
      otpStatus.textContent = channel === "email" ? "OTP sent to your email." : "OTP sent by SMS to your phone.";
    }
    lpListingOtpVerifiedPhone = "";
    lpListingOtpVerifiedEmail = "";
    lpListingOtpToken = "";
  } catch (error) {
    const fallbackMsg = formatOtpDeliveryFallbackMessage(error.message, channel);
    const otpStatus = document.getElementById("lp-otp-status");
    if (otpStatus) {
      otpStatus.className = "text-xs text-red-600 mt-1";
      otpStatus.textContent = fallbackMsg;
    }
    toast(fallbackMsg);
  } finally {
    setButtonLoading("lp-send-otp-btn", false, "Send OTP");
  }
}

async function verifyListingOtp() {
  const channel = lpListingOtpChannel === "email" ? "email" : "phone";
  const phone = normalizePhoneInput(lpVal("lp-verify-phone"));
  const email = (lpVal("lp-verify-email") || "").toLowerCase();
  const code = lpVal("lp-verify-otp-code");
  if (!code) {
    toast("Enter OTP code.");
    return;
  }
  if (channel === "phone" && !phone) {
    toast("Enter phone and OTP code.");
    return;
  }
  if (channel === "email" && !email) {
    toast("Enter email and OTP code.");
    return;
  }
  setButtonLoading("lp-verify-otp-btn", true);
  try {
    const response = await apiRequest("/api/properties/verify-submit-otp", {
      method: "POST",
      body: {
        channel,
        phone: channel === "phone" ? phone : undefined,
        email: channel === "email" ? email : undefined,
        code
      }
    });
    lpListingOtpToken = response?.data?.listing_otp_token || "";
    lpListingOtpVerifiedPhone = channel === "phone" ? phone : "";
    lpListingOtpVerifiedEmail = channel === "email" ? email : "";
    const otpStatus = document.getElementById("lp-otp-status");
    if (otpStatus) {
      otpStatus.className = "text-xs text-green-700 mt-1";
      otpStatus.textContent = `${channel === "email" ? "Email" : "SMS"} OTP verified.`;
    }
    renderListReviewSummary();
  } catch (error) {
    const otpStatus = document.getElementById("lp-otp-status");
    if (otpStatus) {
      otpStatus.className = "text-xs text-red-600 mt-1";
      otpStatus.textContent = error.message || "OTP verification failed.";
    }
    toast(error.message || "OTP verification failed.");
  } finally {
    setButtonLoading("lp-verify-otp-btn", false, "Verify OTP");
  }
}

function normalizeStreetCandidate(value = "") {
  const cleaned = String(value || "").replace(/\s+/g, " ").trim();
  return cleaned.length >= 2 ? cleaned : "";
}

function getLocationScopedProperties({ district = "", city = "", neighborhood = "", area = "" } = {}) {
  const districtKey = String(district || "").trim().toLowerCase();
  const cityKey = String(city || "").trim().toLowerCase();
  const areaKeys = new Set(
    [neighborhood, area]
      .map((value) => String(value || "").trim().toLowerCase())
      .filter(Boolean)
  );

  return PROPERTIES.filter((property) => {
    const propertyDistrict = String(property?.district || "").trim().toLowerCase();
    const propertyCity = String(property?.city || property?.location_town || "").trim().toLowerCase();
    const propertyAreas = new Set(
      [
        property?.area,
        property?.neighborhood,
        property?.extra_fields?.neighborhood,
        property?.extra_fields?.area
      ]
        .map((value) => String(value || "").trim().toLowerCase())
        .filter(Boolean)
    );
    if (districtKey && propertyDistrict !== districtKey) return false;
    if (cityKey && propertyCity && propertyCity !== cityKey) return false;
    if (areaKeys.size) {
      let matchedArea = false;
      areaKeys.forEach((key) => {
        if (propertyAreas.has(key)) matchedArea = true;
      });
      if (!matchedArea && propertyAreas.size) return false;
    }
    return true;
  });
}

function mergeLpStreetSuggestions(values = []) {
  const listEl = document.getElementById("lp-street-suggestions");
  if (!listEl) return;
  const existing = new Set(
    Array.from(listEl.querySelectorAll("option"))
      .map((option) => normalizeStreetCandidate(option.value))
      .filter(Boolean)
  );
  values.forEach((value) => {
    const normalized = normalizeStreetCandidate(value);
    if (normalized) existing.add(normalized);
  });
  listEl.innerHTML = Array.from(existing).slice(0, 200).map((value) => `<option value="${value}"></option>`).join("");
}

function setLpStreetName(value = "", { force = false } = {}) {
  const streetEl = document.getElementById("lp-street-name");
  const normalized = normalizeStreetCandidate(value);
  if (!streetEl || !normalized) return;
  mergeLpStreetSuggestions([normalized]);
  if (!streetEl.value || !lpStreetManualOverride || force) {
    streetEl.value = normalized;
    streetEl.dataset.auto = force ? "0" : "1";
    syncLpAddressFromHierarchy();
  }
}

function extractStreetNameFromGoogleResult(result = {}) {
  const components = Array.isArray(result?.address_components) ? result.address_components : [];
  const findComponent = (...types) => {
    const match = components.find((item) => Array.isArray(item.types) && item.types.some((type) => types.includes(type)));
    return match?.long_name || "";
  };
  const streetNumber = findComponent("street_number");
  const route = findComponent("route");
  const premise = findComponent("premise", "subpremise");
  return normalizeStreetCandidate([streetNumber, route || premise].filter(Boolean).join(" ") || route || premise);
}

