function resizeListMap(map, provider, center = null, zoom = null, delay = 120) {
  setTimeout(() => {
    try {
      if (provider === "google" && window.google?.maps) {
        window.google.maps.event.trigger(map, "resize");
        if (center) map.setCenter(center);
        if (zoom != null) map.setZoom(zoom);
        return;
      }
      if (map?.invalidateSize) {
        map.invalidateSize();
        if (center) map.setView([center.lat, center.lng], zoom || map.getZoom?.() || 9, { animate: false });
      }
    } catch (e) {}
  }, delay);
}

function buildHierarchyLocationQuery({ region = "", district = "", city = "", neighborhood = "", area = "" } = {}) {
  const areaPart = area && area !== neighborhood && area !== city ? area : "";
  return uniqueTextParts([neighborhood, areaPart, city, district, region, "Uganda"]).join(", ");
}

function distanceBetweenPointsKm(a, b) {
  if (!a || !b) return Infinity;
  const toRad = (value) => (Number(value) * Math.PI) / 180;
  const earthRadiusKm = 6371;
  const dLat = toRad(Number(b.lat) - Number(a.lat));
  const dLng = toRad(Number(b.lng) - Number(a.lng));
  const lat1 = toRad(a.lat);
  const lat2 = toRad(b.lat);
  const sinLat = Math.sin(dLat / 2);
  const sinLng = Math.sin(dLng / 2);
  const chord = sinLat * sinLat + Math.cos(lat1) * Math.cos(lat2) * sinLng * sinLng;
  const arc = 2 * Math.atan2(Math.sqrt(chord), Math.sqrt(1 - chord));
  return earthRadiusKm * arc;
}

function pointMatchesHierarchyAnchor(point, anchor, maxDistanceKm = 60) {
  if (!anchor || !Number.isFinite(anchor.lat) || !Number.isFinite(anchor.lng)) return true;
  return distanceBetweenPointsKm(point, anchor) <= maxDistanceKm;
}

function buildGoogleBoundsFromCenter(center, radiusKm = 35) {
  if (!window.google?.maps || !center) return null;
  const latRadius = radiusKm / 111;
  const lngRadius = radiusKm / (111 * Math.max(Math.cos((Number(center.lat) * Math.PI) / 180), 0.25));
  return new google.maps.LatLngBounds(
    { lat: Number(center.lat) - latRadius, lng: Number(center.lng) - lngRadius },
    { lat: Number(center.lat) + latRadius, lng: Number(center.lng) + lngRadius }
  );
}

async function getGoogleGeocoder() {
  const ready = await ensureGoogleMapsApi();
  if (!ready || !window.google?.maps?.Geocoder) return null;
  if (!googleGeocoderInstance) googleGeocoderInstance = new google.maps.Geocoder();
  return googleGeocoderInstance;
}

async function getGooglePlacesAutocompleteService() {
  const ready = await ensureGoogleMapsApi();
  if (!ready || !window.google?.maps?.places?.AutocompleteService) return null;
  if (!googlePlacesAutocompleteService) {
    googlePlacesAutocompleteService = new google.maps.places.AutocompleteService();
  }
  return googlePlacesAutocompleteService;
}

async function getGooglePlacePredictions(query) {
  const service = await getGooglePlacesAutocompleteService();
  if (!service || !query) return [];
  return new Promise((resolve) => {
    service.getPlacePredictions({
      input: query,
      componentRestrictions: { country: "ug" },
      types: ["geocode"]
    }, (predictions, status) => {
      if (status !== "OK" || !Array.isArray(predictions)) {
        resolve([]);
        return;
      }
      resolve(predictions.slice(0, 5).map((prediction) => ({
        value: prediction.description,
        kind: "Google Places",
        placeId: prediction.place_id
      })));
    });
  });
}

async function geocodeWithGoogle(query, options = {}) {
  const geocoder = await getGoogleGeocoder();
  if (!geocoder || !query) return null;
  return new Promise((resolve) => {
    const request = {
      address: query,
      componentRestrictions: { country: "UG" }
    };
    if (options.bounds) request.bounds = options.bounds;
    geocoder.geocode(request, (results, status) => {
      if (status !== "OK" || !Array.isArray(results) || !results.length) {
        resolve(null);
        return;
      }
      const loc = results[0]?.geometry?.location;
      if (!loc) {
        resolve(null);
        return;
      }
      const streetName = extractStreetNameFromGoogleResult(results[0]);
      if (streetName) setLpStreetName(streetName);
      resolve({
        lat: loc.lat(),
        lng: loc.lng(),
        label: results[0].formatted_address || query,
        placeId: results[0].place_id || "",
        streetName
      });
    });
  });
}

function setLpAddressSearchStatus(message = "", tone = "info") {
  const el = document.getElementById("lp-address-search-status");
  if (!el) return;
  const color = tone === "error" ? "text-red-700" : tone === "success" ? "text-green-800" : "text-green-800";
  el.className = `text-xs ${color} mt-2`;
  el.textContent = message || translateListingLabel("Search for the nearest place, road, landmark, or area, then place the map pin where the property is located.");
}

function setLpHiddenValue(id, value = "") {
  const el = document.getElementById(id);
  if (el) el.value = value || "";
}

async function geocodeWithNominatim(query) {
  const q = uniqueTextParts([query, "Uganda"]).join(", ");
  try {
    const url = `https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&addressdetails=1&countrycodes=ug&q=${encodeURIComponent(q)}`;
    const response = await fetch(url, { headers: { Accept: "application/json" } });
    if (!response.ok) return null;
    const rows = await response.json();
    const row = Array.isArray(rows) ? rows[0] : null;
    const lat = Number(row?.lat);
    const lng = Number(row?.lon);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
    const streetName = extractStreetNameFromNominatimAddress(row?.address || {});
    if (streetName) setLpStreetName(streetName);
    return {
      lat,
      lng,
      label: row?.display_name || query,
      placeId: row?.place_id ? `osm:${row.place_id}` : "",
      streetName,
      provider: "nominatim",
      confidence: row?.importance ? Math.min(0.95, Math.max(0.35, Number(row.importance))) : 0.45
    };
  } catch (error) {
    return null;
  }
}

function applyLpAddressPlaceResult(point, query = "") {
  if (!point || !Number.isFinite(Number(point.lat)) || !Number.isFinite(Number(point.lng))) return false;
  const label = point.label || query || "";
  const addressEl = document.getElementById("lp-address");
  const searchEl = document.getElementById("lp-address-search");
  if (searchEl && label) searchEl.value = label;
  if (addressEl && label) {
    addressEl.disabled = false;
    addressEl.value = label;
    addressEl.dataset.auto = "1";
  }
  setLpHiddenValue("lp-place-id", point.placeId || "");
  setLpHiddenValue("lp-plus-code", point.plusCode || "");
  setLpHiddenValue("lp-geocoding-provider", point.provider || "google");
  setLpHiddenValue("lp-geocoded-at", new Date().toISOString());
  setLpHiddenValue("lp-location-confidence", point.confidence != null ? String(point.confidence) : "0.65");
  setLpResolvedLocationLabel(label);
  applyResolvedAddressHierarchy(label, point);
  setListPinCoords(point.lat, point.lng, true, true);
  const confirmEl = document.getElementById("lp-location-confirm");
  if (confirmEl) confirmEl.checked = false;
  updateLpLocationConfirmButton();
  updateListPreview();
  renderListReviewSummary();
  setLpAddressSearchStatus(translateListingLabel("Address found. Check the pin and confirm the location."), "success");
  return true;
}

function onLpAddressSearchInput() {
  const input = document.getElementById("lp-address-search");
  const query = (input?.value || "").trim();
  if (query.length >= 3) {
    renderTypeahead(input, getLocationSuggestionPool(true), (value) => {
      if (input) input.value = value;
      findLpAddressOrPlace();
    });
    if (lpPlacesSuggestTimer) window.clearTimeout(lpPlacesSuggestTimer);
    lpPlacesSuggestTimer = window.setTimeout(async () => {
      if (!input || document.activeElement !== input || (input.value || "").trim() !== query) return;
      const predictions = await getGooglePlacePredictions(query);
      if (!predictions.length || document.activeElement !== input) return;
      renderTypeahead(input, predictions.concat(getLocationSuggestionPool(true)), (value) => {
        if (input) input.value = value;
        findLpAddressOrPlace();
      });
      setLpAddressSearchStatus(translateListingLabel("Choose a Google Places suggestion or keep typing a landmark, road, area, town, or district."));
    }, 250);
  } else {
    if (lpPlacesSuggestTimer) window.clearTimeout(lpPlacesSuggestTimer);
    closeTypeahead();
  }
}

function onLpAddressSearchKeydown(event) {
  handleTypeaheadKeydown(event, () => getLocationSuggestionPool(true), () => findLpAddressOrPlace());
  if (event.key === "Enter" && !event.defaultPrevented) {
    event.preventDefault();
    findLpAddressOrPlace();
  }
}

async function findLpAddressOrPlace() {
  const input = document.getElementById("lp-address-search");
  const query = (input?.value || "").trim();
  if (query.length < 3) {
    markLpFieldError("lp-address-search", "Type at least 3 characters to find an address or place.");
    setLpAddressSearchStatus(translateListingLabel("Type at least 3 characters to find an address or place."), "error");
    return false;
  }
  clearLpValidationErrors("#lp-step-1");
  setLpAddressSearchStatus(translateListingLabel("Finding the nearest matching place in Uganda..."));
  ensureListPinMap();
  let point = null;
  try {
    point = await geocodeWithGoogle(uniqueTextParts([query, "Uganda"]).join(", "));
    if (point) {
      point.provider = "google";
      point.confidence = 0.75;
    }
  } catch (error) {
    point = null;
  }
  if (!point) {
    point = await geocodeWithNominatim(query);
  }
  if (!point) {
    const region = lpVal("lp-region");
    const district = lpVal("list-district-sel") || guessDistrictFromText(query);
    const fallback = getDistrictCenter(district) || getRegionCenter(region) || MAP_DEFAULT_CENTER;
    setListPinCoords(fallback.lat, fallback.lng, true, true);
    const addressEl = document.getElementById("lp-address");
    if (addressEl) {
      addressEl.disabled = false;
      addressEl.value = query;
      addressEl.dataset.auto = "0";
    }
    setLpHiddenValue("lp-geocoding-provider", "manual_fallback");
    setLpHiddenValue("lp-geocoded-at", new Date().toISOString());
    setLpHiddenValue("lp-location-confidence", "0.25");
    setLpResolvedLocationLabel(query);
    setLpAddressSearchStatus(translateListingLabel("We could not find an exact match. The map is ready for you to place the pin manually."), "error");
    return false;
  }
  return applyLpAddressPlaceResult(point, query);
}

function setLpCurrentLocationStatus(message = "", tone = "info") {
  const el = document.getElementById("lp-current-location-status");
  if (!el) return;
  const color = tone === "error" ? "text-red-700" : tone === "success" ? "text-green-800" : "text-green-800";
  el.className = `text-xs ${color}`;
  el.textContent = message || "We only use your exact location for this listing after you confirm the pin.";
}

function shareLpCurrentLocation() {
  const btn = document.getElementById("lp-current-location-btn");
  if (!navigator.geolocation) {
    const message = translateListingLabel("Location sharing is not available on this device. Search for address or place manually.");
    setLpCurrentLocationStatus(message, "error");
    setLpAddressSearchStatus(message, "error");
    return;
  }
  const secureEnough = window.isSecureContext || ["localhost", "127.0.0.1"].includes(window.location.hostname);
  if (!secureEnough) {
    const message = translateListingLabel("Location sharing needs HTTPS. Search for address or place manually.");
    setLpCurrentLocationStatus(message, "error");
    setLpAddressSearchStatus(message, "error");
    return;
  }
  if (btn) btn.disabled = true;
  setLpCurrentLocationStatus(translateListingLabel("Requesting location permission..."));
  setLpAddressSearchStatus(translateListingLabel("Requesting location permission..."));
  ensureListPinMap();
  navigator.geolocation.getCurrentPosition(async (pos) => {
    const lat = Number(pos.coords?.latitude);
    const lng = Number(pos.coords?.longitude);
    if (btn) btn.disabled = false;
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
      const message = translateListingLabel("Could not read your location. Search for address or place manually.");
      setLpCurrentLocationStatus(message, "error");
      setLpAddressSearchStatus(message, "error");
      return;
    }
    if (!isPointInUgandaClient(lat, lng)) {
      const message = translateListingLabel("The location appears outside Uganda. Search for a Ugandan address or place instead.");
      setLpCurrentLocationStatus(message, "error");
      setLpAddressSearchStatus(message, "error");
      trackEvent("listing_current_location_outside_uganda", {
        lat: roundSearchCoord(lat),
        lng: roundSearchCoord(lng),
        fallback: "manual_uganda_address"
      });
      return;
    }
    const input = document.getElementById("lp-address-search");
    const addressEl = document.getElementById("lp-address");
    if (input && !input.value.trim()) input.value = "Current location";
    if (addressEl && !addressEl.value.trim()) {
      addressEl.disabled = false;
      addressEl.value = "Current location";
      addressEl.dataset.auto = "0";
    }
    setLpHiddenValue("lp-geocoding-provider", "browser_geolocation");
    setLpHiddenValue("lp-geocoded-at", new Date().toISOString());
    const accuracy = Number(pos.coords?.accuracy);
    const confidence = Number.isFinite(accuracy) ? Math.max(0.35, Math.min(0.95, 1 - (accuracy / 5000))) : 0.75;
    setLpHiddenValue("lp-location-confidence", confidence.toFixed(2));
    setLpResolvedLocationLabel("Current location");
    setListPinCoords(lat, lng, true, false);
    const message = translateListingLabel("Location captured. Please move the pin if needed, then confirm the location.");
    setLpCurrentLocationStatus(message, "success");
    setLpAddressSearchStatus(message, "success");
    trackEvent("listing_current_location_captured", {
      lat: roundSearchCoord(lat),
      lng: roundSearchCoord(lng),
      accuracy_m: Number.isFinite(accuracy) ? Math.round(accuracy) : null,
      source: "browser_geolocation"
    });
  }, (err) => {
    if (btn) btn.disabled = false;
    const denied = err?.code === 1;
    const message = denied
      ? translateListingLabel("Location permission was denied. Search for an address or place instead.")
      : translateListingLabel("Location timed out or is unavailable. Search for address or place manually.");
    setLpCurrentLocationStatus(message, "error");
    setLpAddressSearchStatus(message, "error");
    trackEvent("listing_current_location_failed", {
      reason: denied ? "permission_denied" : "unavailable_or_timeout"
    });
  }, {
    enableHighAccuracy: true,
    timeout: 15000,
    maximumAge: 60000
  });
}

async function reverseGeocodeGoogleResult(lat, lng) {
  const geocoder = await getGoogleGeocoder();
  if (!geocoder) return null;
  return new Promise((resolve) => {
    geocoder.geocode({
      location: { lat: Number(lat), lng: Number(lng) }
    }, (results, status) => {
      if (status !== "OK" || !Array.isArray(results) || !results.length) {
        resolve(null);
        return;
      }
      resolve(results[0] || null);
    });
  });
}

async function reverseGeocodeWithGoogle(lat, lng) {
  const result = await reverseGeocodeGoogleResult(lat, lng);
  if (!result) return null;
  const streetName = extractStreetNameFromGoogleResult(result);
  if (streetName) setLpStreetName(streetName);
  return result?.formatted_address || "";
}

async function hydrateStreetSuggestionsForSelection(center) {
  if (!center || !Number.isFinite(center.lat) || !Number.isFinite(center.lng)) return;
  const geocoder = await getGoogleGeocoder();
  if (!geocoder) return;
  const seq = ++lpStreetSuggestSeq;
  const seen = new Set();
  const suggestions = [];
  const offsets = [
    { lat: 0, lng: 0 },
    { lat: 0.0018, lng: 0 },
    { lat: -0.0018, lng: 0 },
    { lat: 0, lng: 0.0018 },
    { lat: 0, lng: -0.0018 }
  ];
  for (const offset of offsets) {
    const result = await reverseGeocodeGoogleResult(center.lat + offset.lat, center.lng + offset.lng);
    if (seq !== lpStreetSuggestSeq) return;
    const streetName = extractStreetNameFromGoogleResult(result || {});
    if (streetName && !seen.has(streetName.toLowerCase())) {
      seen.add(streetName.toLowerCase());
      suggestions.push(streetName);
    }
  }
  if (seq !== lpStreetSuggestSeq || !suggestions.length) return;
  mergeLpStreetSuggestions(suggestions);
}

async function resolveHierarchyMapAnchor({ region = "", district = "", city = "", neighborhood = "", area = "" } = {}) {
  const localPoint = getNeighborhoodPoint(district, city, neighborhood)
    || getHierarchyPointForArea(district, neighborhood)
    || getCityPoint(district, city)
    || getHierarchyPointForArea(district, city)
    || getDistrictCenter(district);
  if (localPoint) return localPoint;

  const cacheKey = [region, district, city, neighborhood, area].map((value) => String(value || "").trim().toLowerCase()).join("|");
  if (cacheKey && lpHierarchyAnchorCache.has(cacheKey)) return lpHierarchyAnchorCache.get(cacheKey);

  const queries = Array.from(new Set([
    buildHierarchyLocationQuery({ region, district, city, neighborhood, area }),
    uniqueTextParts([city, district, region, "Uganda"]).join(", "),
    uniqueTextParts([district, region, "Uganda"]).join(", "),
    uniqueTextParts([district, "Uganda"]).join(", ")
  ].filter(Boolean)));

  for (const query of queries) {
    const googlePoint = await geocodeWithGoogle(query);
    if (googlePoint) {
      if (cacheKey) lpHierarchyAnchorCache.set(cacheKey, googlePoint);
      hydrateStreetSuggestionsForSelection(googlePoint);
      return googlePoint;
    }
  }

  for (const query of queries) {
    try {
      const url = `https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=ug&q=${encodeURIComponent(query)}`;
      const response = await fetch(url, { headers: { Accept: "application/json" } });
      if (!response.ok) continue;
      const rows = await response.json();
      const lat = Number(rows?.[0]?.lat);
      const lng = Number(rows?.[0]?.lon);
      if (Number.isFinite(lat) && Number.isFinite(lng)) {
        const point = { lat, lng };
        if (cacheKey) lpHierarchyAnchorCache.set(cacheKey, point);
        return point;
      }
    } catch (error) {}
  }

  const fallback = getRegionCenter(region) || MAP_DEFAULT_CENTER;
  if (cacheKey) lpHierarchyAnchorCache.set(cacheKey, fallback);
  return fallback;
}

function initGoogleListPinMap(el) {
  if (!window.google?.maps || !el) return false;
  el.innerHTML = "";
  lpPinMap = new google.maps.Map(el, {
    center: MAP_DEFAULT_CENTER,
    zoom: MAP_DEFAULT_ZOOM,
    mapTypeId: "hybrid",
    mapTypeControl: true,
    streetViewControl: true,
    fullscreenControl: true,
    clickableIcons: true
  });
  lpPinMapProvider = "google";
  lpPinInfoWindow = new google.maps.InfoWindow();
  lpPinMap.addListener("click", (evt) => {
    if (!evt.latLng) return;
    setListPinCoords(evt.latLng.lat(), evt.latLng.lng(), false);
  });
  return true;
}

function initLeafletListPinMap() {
  if (!window.L) return false;
  const el = document.getElementById("lp-pin-map");
  if (!el) return false;
  if (el._leaflet_id && !lpPinMap) {
    try { el._leaflet_id = null; } catch (e) {}
    el.innerHTML = "";
  }
  lpPinMap = L.map(el, {
    minZoom: 6,
    maxBounds: [[-1.7, 29.2], [4.5, 35.2]],
    maxBoundsViscosity: 0.65
  }).setView([MAP_DEFAULT_CENTER.lat, MAP_DEFAULT_CENTER.lng], MAP_DEFAULT_ZOOM);
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
    attribution: "&copy; OpenStreetMap contributors",
    maxZoom: 18
  }).addTo(lpPinMap);
  lpPinMapProvider = "leaflet";
  lpPinMap.on("click", (evt) => {
    setListPinCoords(evt.latlng.lat, evt.latlng.lng, false);
  });
  return true;
}

function ensureListPinMap() {
  const el = document.getElementById("lp-pin-map");
  if (!el) return;
  if (lpPinMap) {
    resizeListMap(lpPinMap, lpPinMapProvider);
    return;
  }
  if (lpPinMapInitPromise) return lpPinMapInitPromise;
  if (GOOGLE_MAPS_API_KEY) {
    lpPinMapInitPromise = ensureGoogleMapsApi().then((useGoogle) => {
      if (lpPinMap) return;
      const ready = useGoogle && initGoogleListPinMap(el);
      if (!ready) {
        return ensureLeafletApi().then(() => {
          if (!lpPinMap) initLeafletListPinMap();
          if (lpPinMap) {
            refreshListPinMapFromInputs();
            resizeListMap(lpPinMap, lpPinMapProvider);
          }
        });
        return;
      }
      refreshListPinMapFromInputs();
      resizeListMap(lpPinMap, lpPinMapProvider);
    }).finally(() => {
      lpPinMapInitPromise = null;
    });
    return;
  }
  lpPinMapInitPromise = ensureLeafletApi().then(() => {
    if (initLeafletListPinMap()) resizeListMap(lpPinMap, lpPinMapProvider);
  }).finally(() => {
    lpPinMapInitPromise = null;
  });
}

