function applyAccountAccessLanguageUi() {
  const drawer = document.getElementById("account-access-drawer");
  if (!drawer) return;
  setTextById("account-access-title", accountAccessText("heading"));
  setTextById("account-access-brand-kicker", `${publicBrand()} account`);
  setTextById("auth-drawer-benefits", accountAccessRouteBenefit());
  const sub = drawer.querySelector("[data-auth-drawer-subheading]");
  if (sub) sub.textContent = accountAccessText("subheading");
  const roleList = document.getElementById("account-access-role-list");
  if (roleList) roleList.innerHTML = renderAccountAccessRoleCards();
  const langLabel = drawer.querySelector("[data-auth-label-language]");
  if (langLabel) langLabel.textContent = accountAccessText("language");
  const continueAs = drawer.querySelector("[data-auth-label-continue-as]");
  if (continueAs) continueAs.textContent = accountAccessText("continueAs");
  drawer.querySelectorAll("[data-auth-text]").forEach((el) => {
    const key = el.getAttribute("data-auth-text");
    if (key) el.textContent = accountAccessText(key);
  });
  syncAccountAccessPasswordToggleLabels();
  const termsCopy = document.getElementById("account-access-terms-copy");
  if (termsCopy) {
    termsCopy.innerHTML = `${accountAccessText("terms").replace("Terms & Conditions", `<button type="button" data-auth-accent-link="1" onclick="openPolicyPreviewModal('terms')" onfocus="showPolicyPreviewCard(this, 'terms')" onblur="hidePolicyPreviewCard()" onmouseenter="showPolicyPreviewCard(this, 'terms')" onmouseleave="hidePolicyPreviewCard()" class="font-bold text-green-700 underline decoration-green-200">Terms & Conditions</button>`)}`;
  }
  const privacyCopy = document.getElementById("account-access-privacy-copy");
  if (privacyCopy) {
    privacyCopy.innerHTML = `${accountAccessText("privacy").replace("Privacy Policy", `<button type="button" data-auth-accent-link="1" onclick="openPolicyPreviewModal('privacy')" onfocus="showPolicyPreviewCard(this, 'privacy')" onblur="hidePolicyPreviewCard()" onmouseenter="showPolicyPreviewCard(this, 'privacy')" onmouseleave="hidePolicyPreviewCard()" class="font-bold text-green-700 underline decoration-green-200">Privacy Policy</button>`)}`;
  }
  setAccountAccessRole(accountAccessDrawerAudience);
  applyAccountAccessTheme();
  if (accountAccessDrawerMode === "create" || accountAccessDrawerMode === "verify") {
    setAccountAccessCreateStep(accountAccessCreateStep);
  } else if (accountAccessDrawerMode === "forgot") {
    setTextById("account-access-mode-label", accountAccessText("forgotTitle"));
    const btn = document.getElementById("account-access-continue-btn");
    if (btn) btn.textContent = accountAccessForgotResetState ? accountAccessText("resetPassword") : accountAccessText("sendResetCode");
  } else {
    setTextById("account-access-mode-label", accountAccessText("signIn"));
    const btn = document.getElementById("account-access-continue-btn");
    if (btn) btn.textContent = accountAccessText("signIn");
  }
  updateAccountAccessProgress(accountAccessDrawerStep);
  updateAccountAccessCreateFinalState();
}

function renderAccountAccessScreening(preservedValues = null) {
  const wrap = document.getElementById("account-access-screening");
  if (!wrap) return;
  const values = preservedValues || collectAccountAccessScreeningValues();
  const questions = accountAccessQuestionsForAudience(accountAccessDrawerAudience, values);
  wrap.innerHTML = questions.map((question) => `
    <label class="block">
      <span class="block text-xs font-bold text-gray-600 mb-1">${adminEscape(accountAccessScreeningText(question.label))}</span>
      <select data-auth-screening-key="${question.key}" ${accountAccessDrawerAudience === "finder" && question.key === "primary_goal" ? 'onchange="handleAccountAccessFinderGoalChange()"' : ""} class="w-full min-h-[48px] border rounded-xl px-4 py-3 text-sm bg-white" style="border-color:var(--auth-role-border, #bbf7d0);">
        ${question.options.map((option) => `<option value="${adminAttr(option)}"${values[question.key] === option ? " selected" : ""}>${adminEscape(accountAccessScreeningText(option))}</option>`).join("")}
      </select>
    </label>
  `).join("");
}

function updateAccountAccessProgress(step = "account") {
  accountAccessDrawerStep = step;
  const progress = document.getElementById("account-access-progress-summary");
  if (!progress) return;
  const labels = isAccountAccessBrokerCreateFlow() ? {
    details: "1 of 5: Details",
    verify: "2 of 5: Verify",
    preferences: "3 of 5: Broker details",
    broker_id: "4 of 5: Trust check",
    password: "5 of 5: Password"
  } : {
    details: "1 of 4: Details",
    verify: "2 of 4: Verify",
    preferences: "3 of 4: Preferences",
    password: "4 of 4: Password"
  };
  const shouldShow = accountAccessDrawerMode === "create" || accountAccessDrawerMode === "verify";
  progress.classList.toggle("hidden", !shouldShow);
  progress.textContent = shouldShow ? (labels[step] || labels.details) : "";
}

function updateAccountAccessRoleFocus() {
  const listWrap = document.getElementById("account-access-role-list-wrap");
  const selectedWrap = document.getElementById("account-access-selected-role-card");
  const secondary = document.getElementById("account-access-secondary-actions");
  const isFocusedFlow = accountAccessDrawerMode === "create" || accountAccessDrawerMode === "verify";
  const isAdmin = accountAccessDrawerAudience === "admin";
  const isModerator = accountAccessDrawerAudience === "moderator";
  const isInternalSignIn = isAdmin || isModerator;
  if (listWrap) listWrap.classList.toggle("hidden", isFocusedFlow || isInternalSignIn);
  if (selectedWrap) {
    const copy = accountAccessRoleCopy(accountAccessDrawerAudience);
    const theme = accountAccessRoleTheme(accountAccessDrawerAudience);
    selectedWrap.classList.toggle("hidden", !(isFocusedFlow || isInternalSignIn));
    selectedWrap.style.borderColor = theme.border;
    selectedWrap.style.background = theme.soft;
    selectedWrap.innerHTML = (isFocusedFlow || isInternalSignIn) ? `<div class="flex items-center justify-between gap-3">
      <div class="flex items-center gap-3">
        <span class="w-10 h-10 rounded-2xl bg-white flex items-center justify-center" style="color:${theme.primary};"><i class="fas ${copy.icon}" aria-hidden="true"></i></span>
        <span><span class="block text-sm font-black text-gray-900">${adminEscape(copy.label)}</span><span class="block text-xs text-gray-600">${adminEscape(copy.body)}</span></span>
      </div>
      ${!isAdmin && accountAccessDrawerMode === "create" && accountAccessCreateStep === "details" ? `<button type="button" onclick="showAccountAccessRolePicker()" class="text-xs font-bold" style="color:${theme.primary};">Back to account type</button>` : ""}
    </div>` : "";
  }
  if (secondary) secondary.classList.toggle("hidden", accountAccessDrawerMode === "verify" || accountAccessDrawerMode === "forgot");
  updateAccountAccessModeSwitches();
}

function isAccountAccessCreatingOrVerifying() {
  return accountAccessDrawerMode === "create" || accountAccessDrawerMode === "verify";
}

function toggleAccountAccessMode() {
  if (isAccountAccessCreatingOrVerifying()) {
    showAccountAccessSignIn();
    return;
  }
  showAccountAccessCreate();
}

function updateAccountAccessModeSwitches() {
  const creating = isAccountAccessCreatingOrVerifying();
  const label = creating ? accountAccessText("signIn") : accountAccessText("createAccount");
  const secondaryLabel = creating ? "Already have an account? Sign in" : accountAccessText("createAccount");
  const switchBtn = document.getElementById("account-access-mode-switch-btn");
  if (switchBtn) {
    switchBtn.textContent = label;
    switchBtn.setAttribute("aria-label", creating ? "Sign in to an existing makaug.com account" : "Create a makaug.com account");
  }
  const secondaryBtn = document.getElementById("account-access-secondary-mode-btn");
  if (secondaryBtn) {
    secondaryBtn.textContent = secondaryLabel;
    secondaryBtn.setAttribute("aria-label", creating ? "Sign in to an existing account" : "Create an account");
  }
}

function applyAccountAccessTheme() {
  const drawer = document.getElementById("account-access-drawer");
  if (!drawer) return;
  const theme = accountAccessRoleTheme(accountAccessDrawerAudience);
  drawer.setAttribute("data-auth-role-theme", normalizeAuthAudience(accountAccessDrawerAudience, true));
  drawer.style.setProperty("--auth-role-primary", theme.primary);
  drawer.style.setProperty("--auth-role-secondary", theme.secondary);
  drawer.style.setProperty("--auth-role-soft", theme.soft);
  drawer.style.setProperty("--auth-role-border", theme.border);
  drawer.style.setProperty("--auth-role-text", theme.text);
  const header = document.getElementById("account-access-header");
  if (header) header.style.background = theme.header;
  const benefit = document.getElementById("auth-drawer-benefits");
  if (benefit) {
    benefit.style.background = theme.soft;
    benefit.style.borderColor = theme.border;
    benefit.style.color = theme.text;
  }
  const modeLabel = document.getElementById("account-access-mode-label");
  if (modeLabel) modeLabel.style.color = theme.text;
  const roleLabel = document.getElementById("account-access-role-label");
  if (roleLabel) roleLabel.style.color = theme.primary;
  const progress = document.getElementById("account-access-progress-summary");
  if (progress) progress.style.background = "rgba(255,255,255,0.18)";
  const otpWrap = document.getElementById("account-access-otp-method-wrap");
  if (otpWrap) {
    otpWrap.style.background = theme.soft;
    otpWrap.style.borderColor = theme.border;
  }
  const continueBtn = document.getElementById("account-access-continue-btn");
  if (continueBtn) {
    continueBtn.style.background = theme.primary;
    continueBtn.style.borderColor = theme.primary;
  }
  drawer.querySelectorAll("#account-access-secondary-actions button, [data-auth-accent-link]").forEach((el) => {
    el.style.color = theme.primary;
  });
  drawer.querySelectorAll(".accent-green-700").forEach((el) => {
    el.style.accentColor = theme.primary;
  });
}

function isAccountAccessBrokerCreateFlow() {
  return accountAccessDrawerAudience === "agent";
}

function getAccountAccessBrokerIdentityDetails() {
  return {
    nin: normalizeNinInput(document.getElementById("account-access-broker-id-number")?.value || ""),
    fileName: accountAccessBrokerIdentityFileName || "",
    fileType: accountAccessBrokerIdentityFileType || "",
    dataUrl: accountAccessBrokerIdentityDataUrl || ""
  };
}

function updateAccountAccessBrokerIdentityState() {
  const input = document.getElementById("account-access-broker-id-number");
  if (input) input.value = normalizeNinInput(input.value || "");
  const preview = document.getElementById("account-access-broker-id-preview");
  if (!preview) return;
  const details = getAccountAccessBrokerIdentityDetails();
  preview.classList.toggle("hidden", !details.fileName && !details.nin);
  preview.innerHTML = `
    <div class="font-black text-green-950">Broker trust check</div>
    <div class="mt-1">${details.nin ? `ID number: ${adminEscape(details.nin)}` : "ID number can be added later."}</div>
    <div>${details.fileName ? `Photo ready: ${adminEscape(details.fileName)}` : "ID photo can be added later from the dashboard."}</div>
  `;
}

async function handleAccountAccessBrokerIdentitySelection(event) {
  const file = event?.target?.files?.[0];
  accountAccessBrokerIdentityDataUrl = "";
  accountAccessBrokerIdentityFileName = "";
  accountAccessBrokerIdentityFileType = "";
  if (!file) {
    updateAccountAccessBrokerIdentityState();
    return;
  }
  if (!file.type || !file.type.startsWith("image/")) {
    toast("Upload the National ID as a photo image, not a PDF.");
    event.target.value = "";
    updateAccountAccessBrokerIdentityState();
    return;
  }
  if (file.size > 8 * 1024 * 1024) {
    toast("That ID photo is too large. Please upload an image under 8MB.");
    event.target.value = "";
    updateAccountAccessBrokerIdentityState();
    return;
  }
  try {
    accountAccessBrokerIdentityDataUrl = await compressPhotoForSubmission(file, { maxSide: 1200, quality: 0.78 });
    accountAccessBrokerIdentityFileName = file.name || "national-id-photo.jpg";
    accountAccessBrokerIdentityFileType = file.type || "image/jpeg";
    updateAccountAccessBrokerIdentityState();
    toast("National ID photo added for broker review.");
  } catch (error) {
    toast("Could not read that ID photo. Please try another image.");
    event.target.value = "";
    updateAccountAccessBrokerIdentityState();
  }
}

function validateAccountAccessBrokerIdentityStep() {
  if (!isAccountAccessBrokerCreateFlow()) return true;
  const details = getAccountAccessBrokerIdentityDetails();
  if (!details.nin && !details.dataUrl) return true;
  if (details.nin && !isValidBrokerNationalId(details.nin)) {
    toast("Enter a valid National ID number, or clear it and add it later from your dashboard.");
    document.getElementById("account-access-broker-id-number")?.focus();
    return false;
  }
  return true;
}

function getAccountAccessCreatePasswordReadiness() {
  const password = (document.getElementById("account-access-create-password")?.value || "").trim();
  const confirmPassword = (document.getElementById("account-access-confirm-password")?.value || "").trim();
  const termsAccepted = document.getElementById("account-access-terms")?.checked === true;
  const privacyAccepted = document.getElementById("account-access-privacy")?.checked === true;
  const missing = [];
  if (!accountAccessContactVerificationToken) missing.push(accountAccessText("verifiedRequirement"));
  if (isAccountAccessBrokerCreateFlow()) {
    const brokerIdentity = getAccountAccessBrokerIdentityDetails();
    if (brokerIdentity.nin && !isValidBrokerNationalId(brokerIdentity.nin)) {
      missing.push("Broker ID number looks invalid. Clear it or add a valid ID number before continuing.");
    }
  }
  if (password.length < 8) missing.push(accountAccessText("passwordRequirement"));
  if (!confirmPassword || password !== confirmPassword) missing.push(accountAccessText("confirmRequirement"));
  if (!termsAccepted) missing.push(accountAccessText("termsRequirement"));
  if (!privacyAccepted) missing.push(accountAccessText("privacyRequirement"));
  return {
    ready: missing.length === 0,
    message: missing.length ? missing.join(" ") : accountAccessText("readyToCreate")
  };
}

function setAccountAccessCreateStatus(message = "", tone = "info") {
  const status = document.getElementById("account-access-create-status");
  if (!status) return;
  status.textContent = message;
  const toneClasses = {
    success: "rounded-2xl border border-green-100 bg-green-50 px-3 py-2 text-xs font-bold text-green-800",
    error: "rounded-2xl border border-red-200 bg-red-50 px-3 py-2 text-xs font-bold text-red-800",
    pending: "rounded-2xl border border-blue-100 bg-blue-50 px-3 py-2 text-xs font-bold text-blue-900",
    warning: "rounded-2xl border border-amber-200 bg-amber-50 px-3 py-2 text-xs font-bold text-amber-900"
  };
  status.className = toneClasses[tone] || toneClasses.warning;
}

function setAccountAccessFlowNote(message = "", tone = "info") {
  const note = document.getElementById("account-access-create-flow-note");
  if (!note) return;
  note.textContent = message || accountAccessText("contactStepNote");
  const toneClasses = {
    info: "rounded-2xl border border-green-100 bg-green-50 px-3 py-2 text-xs text-green-900",
    success: "rounded-2xl border border-green-100 bg-green-50 px-3 py-2 text-xs text-green-900 font-semibold",
    pending: "rounded-2xl border border-blue-100 bg-blue-50 px-3 py-2 text-xs text-blue-900 font-semibold",
    error: "rounded-2xl border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-900 font-semibold",
    warning: "rounded-2xl border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-900 font-semibold"
  };
  note.className = toneClasses[tone] || toneClasses.info;
}

function updateAccountAccessCreateFinalState() {
  const btn = document.getElementById("account-access-continue-btn");
  const status = document.getElementById("account-access-create-status");
  const shouldGuard = accountAccessDrawerMode === "create" && accountAccessCreateStep === "password";
  if (!btn) return;
  if (!shouldGuard) {
    if (!btn.dataset.accountSubmitting) {
      btn.disabled = false;
      btn.classList.remove("opacity-60", "cursor-not-allowed");
      btn.removeAttribute("aria-disabled");
    }
    return;
  }
  const readiness = getAccountAccessCreatePasswordReadiness();
  if (!btn.dataset.accountSubmitting) {
    btn.disabled = !readiness.ready;
    btn.classList.toggle("opacity-60", !readiness.ready);
    btn.classList.toggle("cursor-not-allowed", !readiness.ready);
    btn.setAttribute("aria-disabled", readiness.ready ? "false" : "true");
  }
  if (status) {
    setAccountAccessCreateStatus(readiness.message, readiness.ready ? "success" : "warning");
  }
}

function setAccountAccessCreateStep(step = "details") {
  accountAccessCreateStep = ["details", "verify", "preferences", "broker_id", "password"].includes(step) ? step : "details";
  if (accountAccessCreateStep === "broker_id" && !isAccountAccessBrokerCreateFlow()) accountAccessCreateStep = "password";
  const isVerify = accountAccessCreateStep === "verify";
  const stepIds = {
    details: "account-access-create-details-step",
    preferences: "account-access-create-preferences-step",
    broker_id: "account-access-create-broker-id-step",
    password: "account-access-create-password-step"
  };
  Object.entries(stepIds).forEach(([key, id]) => {
    document.getElementById(id)?.classList.toggle("hidden", key !== accountAccessCreateStep);
  });
  document.getElementById("account-access-otp-wrap")?.classList.toggle("hidden", !isVerify);
  document.getElementById("account-access-create-wrap")?.classList.toggle("hidden", isVerify);
  document.getElementById("account-access-signin-wrap")?.classList.add("hidden");
  document.getElementById("account-access-password-wrap")?.classList.add("hidden");
  document.getElementById("account-access-forgot-wrap")?.classList.add("hidden");
  const note = document.getElementById("account-access-create-flow-note");
	  if (note) {
	    const noteKey = accountAccessCreateStep === "preferences"
	      ? "preferencesStepNote"
	      : (accountAccessCreateStep === "broker_id" ? "brokerIdStepNote" : (accountAccessCreateStep === "password" ? "passwordStepNote" : "contactStepNote"));
	    setAccountAccessFlowNote(accountAccessText(noteKey), "info");
	  }
	  const titles = {
	    details: accountAccessText("detailsTitle"),
	    verify: accountAccessText("verifyTitle"),
	    preferences: accountAccessText("preferencesTitle"),
	    broker_id: accountAccessText("brokerIdTitle"),
	    password: accountAccessText("passwordTitle")
	  };
  setTextById("account-access-mode-label", titles[accountAccessCreateStep] || accountAccessText("createAccount"));
  const btn = document.getElementById("account-access-continue-btn");
  if (btn) {
    const labels = {
	      details: accountAccessText("sendCode"),
	      verify: accountAccessText("verifyCode"),
	      preferences: accountAccessText("continue"),
	      broker_id: accountAccessText("continue"),
	      password: accountAccessText("createFinal")
	    };
    btn.textContent = labels[accountAccessCreateStep] || accountAccessText("continue");
  }
  updateAccountAccessProgress(accountAccessCreateStep);
  updateAccountAccessRoleFocus();
  applyAccountAccessTheme();
  updateAccountAccessCreateFinalState();
}

function showAccountAccessRolePicker() {
  accountAccessDrawerMode = "signin";
	  accountAccessPendingOtp = null;
	  accountAccessContactVerificationToken = "";
	  accountAccessCreateStep = "details";
	  accountAccessForgotResetState = null;
	  accountAccessBrokerIdentityDataUrl = "";
	  accountAccessBrokerIdentityFileName = "";
	  accountAccessBrokerIdentityFileType = "";
  const signInWrap = document.getElementById("account-access-signin-wrap");
  const createWrap = document.getElementById("account-access-create-wrap");
  const passwordWrap = document.getElementById("account-access-password-wrap");
  const otpWrap = document.getElementById("account-access-otp-wrap");
  const forgotWrap = document.getElementById("account-access-forgot-wrap");
  if (signInWrap) signInWrap.classList.remove("hidden");
  if (createWrap) createWrap.classList.add("hidden");
  if (passwordWrap) passwordWrap.classList.remove("hidden");
  if (otpWrap) otpWrap.classList.add("hidden");
  if (forgotWrap) forgotWrap.classList.add("hidden");
  setTextById("account-access-mode-label", accountAccessText("signIn"));
  const btn = document.getElementById("account-access-continue-btn");
  if (btn) btn.textContent = accountAccessText("signIn");
  updateAccountAccessProgress("account");
  updateAccountAccessSignInCopy();
  updateAccountAccessRoleFocus();
}

function showAccountAccessSignIn() {
  accountAccessDrawerMode = "signin";
  accountAccessForgotResetState = null;
  document.getElementById("account-access-signin-wrap")?.classList.remove("hidden");
  document.getElementById("account-access-password-wrap")?.classList.remove("hidden");
  document.getElementById("account-access-create-wrap")?.classList.add("hidden");
  document.getElementById("account-access-otp-wrap")?.classList.add("hidden");
  document.getElementById("account-access-forgot-wrap")?.classList.add("hidden");
  setTextById("account-access-mode-label", accountAccessText("signIn"));
  const btn = document.getElementById("account-access-continue-btn");
  if (btn) btn.textContent = accountAccessText("signIn");
  updateAccountAccessProgress("account");
  updateAccountAccessSignInCopy();
  updateAccountAccessRoleFocus();
  setTimeout(() => document.getElementById("account-access-identifier")?.focus(), 30);
}

