function buildRevenuePlacementMarkup(slotKey, context) {
  const adSlot = String(GOOGLE_ADSENSE_SLOTS[slotKey] || GOOGLE_ADSENSE_SLOTS.default || "").trim();
  const hasLiveAds = GOOGLE_ADSENSE_CLIENT && adSlot;
  const sample = INHOUSE_AD_SAMPLES[slotKey] || INHOUSE_AD_SAMPLES.default;
  return `
    <div class="max-w-7xl mx-auto px-0 py-4">
      <div class="ad-unit">
        <span class="ad-tag"><i class="fas fa-bullhorn"></i> Sponsored</span>
        <div class="inhouse-ad-preview">
          <img src="${adminAttr(sample.image)}" alt="${adminAttr(sample.label)}">
          <div class="inhouse-ad-preview-body">
            <div class="text-[11px] uppercase tracking-wide text-green-700 font-black">${adminEscape(sample.label)}</div>
            <div class="text-sm font-black text-gray-900">${adminEscape(sample.headline)}</div>
            <div class="text-xs text-gray-600">${adminEscape(sample.body)}</div>
            <div class="text-[11px] text-gray-400">Slot: ${adminEscape(context || "makaug.com")}</div>
          </div>
        </div>
        ${hasLiveAds
          ? `<div class="ad-slot" data-adsense-client="${GOOGLE_ADSENSE_CLIENT}" data-adsense-slot="${adSlot}" data-ads-loaded="0"></div>`
          : `<button type="button" onclick="openPageMod('advertise')" class="text-sm font-bold text-green-700 hover:underline whitespace-nowrap">Advertise here</button>`
        }
      </div>
    </div>`;
}

function ensureRevenuePlacements() {
  INLINE_REVENUE_PLACEMENTS.forEach((placement) => {
    const anchor = document.getElementById(placement.anchorId);
    if (!anchor) return;
    const placementId = `revenue-placement-${placement.slotKey}`;
    let node = document.getElementById(placementId);
    if (!node) {
      node = document.createElement("div");
      node.id = placementId;
      node.dataset.revenuePlacement = placement.slotKey;
      anchor.insertAdjacentElement("afterend", node);
    }
    node.innerHTML = buildRevenuePlacementMarkup(placement.slotKey, placement.context);
  });
  renderGoogleAdsSlots();
}

function populateDistricts() {
  const ids = [
    "sale-district-f",
    "rent-district-f",
    "broker-district-f",
    "student-district-f",
    "commercial-district-f",
    "land-district-f"
  ];
  ids.forEach((id) => {
    const el = document.getElementById(id);
    if (!el) return;
    DISTRICTS.forEach((d) => {
      const option = document.createElement("option");
      option.value = d;
      option.textContent = d;
      el.appendChild(option);
    });
  });
}

function populateBrokerFilterOptions() {
  const specialtyEl = document.getElementById("broker-specialty-f");
  const languageEl = document.getElementById("broker-language-f");
  const brokerDirectory = getBrokerDirectory();
  if (specialtyEl) {
    const current = specialtyEl.value || "";
    const specialties = Array.from(new Set(brokerDirectory.flatMap((b) => b.specialties || [])).values()).sort((a, b) => a.localeCompare(b));
    specialtyEl.innerHTML = `<option value="">Any Speciality</option>` + specialties.map((s) => `<option value="${s}">${s}</option>`).join("");
    specialtyEl.value = specialties.includes(current) ? current : "";
  }
  if (languageEl) {
    const current = languageEl.value || "";
    const languages = Array.from(new Set(brokerDirectory.flatMap((b) => b.languages || [])).values()).sort((a, b) => a.localeCompare(b));
    languageEl.innerHTML = `<option value="">Any Language</option>` + languages.map((l) => `<option value="${l}">${l}</option>`).join("");
    languageEl.value = languages.includes(current) ? current : "";
  }
}

function regionForDistrict(district) {
  return DISTRICT_TO_REGION[district] || "";
}

function getDistrictsByRegion(region) {
  if (!region) return [...DISTRICTS];
  return DISTRICTS.filter((district) => regionForDistrict(district) === region);
}

function getRegionCenter(region) {
  if (!region) return null;
  return UG_REGION_CENTERS[region] || null;
}

function setLpGuidedFieldState(id, enabled, placeholder = "") {
  const el = document.getElementById(id);
  if (!el) return;
  el.disabled = !enabled;
  el.classList.toggle("lp-guided-disabled", !enabled);
  if (!enabled && placeholder && !el.value && "placeholder" in el) {
    el.placeholder = translateListingLabel(placeholder);
  }
}

function updateLpLocationStepLocks() {
  const hasRegion = !!lpVal("lp-region");
  const hasDistrict = !!lpVal("list-district-sel");
  const hasCity = !!lpVal("lp-city");
  const hasNeighborhood = !!lpVal("lp-neighborhood");
  setLpGuidedFieldState("list-district-sel", hasRegion);
  setLpGuidedFieldState("lp-city", hasDistrict);
  setLpGuidedFieldState("lp-neighborhood", hasCity);
  setLpGuidedFieldState("lp-area", hasNeighborhood, "Select a neighbourhood first");
  setLpGuidedFieldState("lp-street-name", hasNeighborhood, "Select a neighbourhood first");
  setLpGuidedFieldState("lp-address", hasNeighborhood, "Select a neighbourhood first");
  const syncBtn = document.getElementById("lp-map-sync-btn");
  const canSync = hasRegion && hasDistrict && hasCity && hasNeighborhood;
  if (syncBtn) {
    syncBtn.disabled = !canSync;
    syncBtn.classList.toggle("opacity-60", !canSync);
    syncBtn.classList.toggle("cursor-not-allowed", !canSync);
  }
  updateLpLocationConfirmButton();
}

function populateLpRegionOptions(keepRegion = "") {
  const regionEl = document.getElementById("lp-region");
  if (!regionEl) return;
  regionEl.innerHTML = [`<option value="">${translateListingLabel("Select region")}</option>`]
    .concat(UG_REGIONS.map((region) => `<option value="${region}">${translateListingLabel(region)}</option>`))
    .join("");
  if (keepRegion && UG_REGIONS.includes(keepRegion)) {
    regionEl.value = keepRegion;
  } else if (!regionEl.value) {
    regionEl.value = "";
  }
  updateLpLocationStepLocks();
}

function populateLpDistrictOptions(region, keepDistrict = "") {
  const districtEl = document.getElementById("list-district-sel");
  if (!districtEl) return;
  const districts = getDistrictsByRegion(region);
  districtEl.innerHTML = [`<option value="">${translateListingLabel("Select district")}</option>`]
    .concat(districts.map((district) => `<option value="${district}">${district}</option>`))
    .join("");
  if (keepDistrict && districts.includes(keepDistrict)) districtEl.value = keepDistrict;
  else districtEl.value = "";
  updateLpLocationStepLocks();
}

function selectFirstLpOptionIfNeeded(el, preferred = "", allowFirst = true) {
  if (!el) return "";
  const values = Array.from(el.options || []).map((option) => option.value).filter(Boolean);
  if (preferred && values.includes(preferred)) {
    el.value = preferred;
  } else if (allowFirst && values.length) {
    el.value = values[0];
  } else if (!values.includes(el.value)) {
    el.value = "";
  }
  return el.value || "";
}

function findLpLocationOptionByText(options = [], getValue, text = "") {
  const haystack = String(text || "").toLowerCase();
  if (!haystack) return null;
  return options.find((item) => {
    const value = String(getValue(item) || "").toLowerCase();
    return value && haystack.includes(value);
  }) || null;
}

function getDistrictLocationTree(district) {
  if (!district) return [];
  if (UG_LOCATION_TREE[district]) return UG_LOCATION_TREE[district];
  return [
    {
      city: `${district} ${translateListingLabel("Town")}`,
      neighborhoods: [
        { name: `${district} ${translateListingLabel("Central")}` },
        { name: `${district} ${translateListingLabel("East")}` },
        { name: `${district} ${translateListingLabel("West")}` }
      ]
    }
  ];
}

function populateLpCityOptions(district, keepCity = "") {
  const cityEl = document.getElementById("lp-city");
  if (!cityEl) return;
  const tree = getDistrictLocationTree(district);
  cityEl.innerHTML = [`<option value="">${translateListingLabel("Select town / city")}</option>`]
    .concat(tree.map((item) => `<option value="${item.city}">${item.city}</option>`))
    .join("");
  selectFirstLpOptionIfNeeded(cityEl, keepCity, false);
  updateLpLocationStepLocks();
}

function populateLpNeighborhoodOptions(district, city, keepNeighborhood = "") {
  const nEl = document.getElementById("lp-neighborhood");
  if (!nEl) return;
  const tree = getDistrictLocationTree(district);
  let activeCity = city;
  const cityNode = tree.find((item) => item.city === activeCity);
  const list = cityNode?.neighborhoods || [];
  nEl.innerHTML = [`<option value="">${translateListingLabel("Select neighbourhood")}</option>`]
    .concat(list.map((item) => `<option value="${item.name}">${item.name}</option>`))
    .join("");
  selectFirstLpOptionIfNeeded(nEl, keepNeighborhood, list.length === 1);
  updateLpLocationStepLocks();
}

function getNeighborhoodPoint(district, city, neighborhood) {
  const tree = getDistrictLocationTree(district);
  const cityNode = tree.find((item) => item.city === city);
  const n = cityNode?.neighborhoods?.find((item) => item.name === neighborhood);
  if (!n) return null;
  if (typeof n.lat === "number" && typeof n.lng === "number") return { lat: n.lat, lng: n.lng };
  return null;
}

function getCityPoint(district, city) {
  const tree = getDistrictLocationTree(district);
  const cityNode = tree.find((item) => item.city === city);
  const points = (cityNode?.neighborhoods || []).filter((item) => typeof item.lat === "number" && typeof item.lng === "number");
  if (!points.length) return null;
  const lat = points.reduce((sum, item) => sum + item.lat, 0) / points.length;
  const lng = points.reduce((sum, item) => sum + item.lng, 0) / points.length;
  return { lat, lng };
}

function syncLpAreaFromHierarchy() {
  const district = lpVal("list-district-sel");
  const city = lpVal("lp-city");
  const neighborhood = lpVal("lp-neighborhood");
  const region = lpVal("lp-region");
  const areaEl = document.getElementById("lp-area");
  if (!areaEl) return;
  const autoArea = neighborhood || "";
  if (!neighborhood && (!lpAreaManualOverride || areaEl.dataset.auto === "1")) {
    areaEl.value = "";
    areaEl.dataset.auto = "0";
  } else if (!lpAreaManualOverride || !areaEl.value.trim() || areaEl.dataset.auto === "1") {
    areaEl.value = autoArea;
    areaEl.dataset.auto = autoArea ? "1" : "0";
  }
  populateListAddressSuggestions({ district, city, neighborhood, area: areaEl.value.trim() || autoArea, region });
  syncLpAddressFromHierarchy();
  updateLpLocationStepLocks();
}

