function normalizePageKey(page) {
  const key = String(page || "").trim();
  return {
    "for-sale": "sale",
    "to-rent": "rent",
    "student-accommodation": "students",
    "anti-fraud": "fraud",
    "report-fraud": "fraud",
    "broker-dashboard": "agent-dashboard",
    "field-agent-dashboard": "field-dashboard",
    "staff-operations-dashboard": "staff-dashboard",
    "moderator-dashboard": "staff-dashboard"
  }[key] || key;
}

function normalizeRoutePath(path = "/") {
  const clean = String(path || "/").split("#")[0].split("?")[0].replace(/\/+$/, "");
  return clean || "/";
}

function routeForPage(page) {
  return PAGE_ROUTE_MAP[normalizePageKey(page)] || "";
}

function pageForPublicRoute(path) {
  return PUBLIC_ROUTE_PAGE_MAP[normalizeRoutePath(path)] || "";
}

function normalizeLegacyHashPublicRoute() {
  const hash = String(window.location.hash || "");
  const match = hash.match(/^#page-([a-z0-9-]+)(?:\?(.+))?$/i);
  if (!match) return "";
  const page = normalizePageKey(match[1]);
  const route = routeForPage(page);
  if (!route || route === "/" || !pageForPublicRoute(route)) return "";
  const merged = new URLSearchParams(window.location.search || "");
  const hashParams = new URLSearchParams(match[2] || "");
  hashParams.forEach((value, key) => {
    if (!merged.has(key)) merged.set(key, value);
  });
  const query = merged.toString();
  const nextPath = `${route}${query ? `?${query}` : ""}`;
  try {
    window.history.replaceState({ page, source: "legacy_hash_public_route" }, "", nextPath);
  } catch (error) {}
  return page;
}

