function adminControlForPath(path = "/admin") {
  const clean = normalizeRoutePath(path);
  return ADMIN_ROUTE_CONTROL_MAP[clean] || ((clean.startsWith("/admin/") || clean.startsWith("/king/")) ? ADMIN_ROUTE_CONTROL_MAP["/admin"] : null);
}

function isSignedInAdminUser() {
  return !!(authState?.user && derivePortalMode(authState.user, authState.user.portal_mode) === "admin");
}

function scrollAdminControlIntoView(selector) {
  if (!selector) return;
  window.setTimeout(() => {
    const el = document.querySelector(selector);
    if (el) {
      el.scrollIntoView({ behavior: "auto", block: "start" });
      el.classList.add("admin-control-focus");
      window.setTimeout(() => el.classList.remove("admin-control-focus"), 1800);
    }
  }, 20);
}

async function openAdminControl(control, options = {}) {
  const target = typeof control === "string" ? adminControlForPath(control) : control;
  if (!target) return false;
  if (!isSignedInAdminUser() && !adminApiKey) {
    showPage("admin-dashboard", { history: false, source: options.source || "admin_api_key_fallback" });
    renderAdminDashboard().catch((error) => {
      console.warn("Admin API key fallback gate failed", error);
    });
    return true;
  }
  if (target.page === "admin-docs") {
    showPage("admin-docs", { history: false, source: options.source || "admin_control" });
    return true;
  }
  if (target.page === "admin-setup-status") {
    showPage("admin-setup-status", { history: false, source: options.source || "admin_control" });
    renderAdminSetupStatus();
    return true;
  }
  if (target.tab) activeAdminWorkflowTab = target.tab;
  showPage("admin-dashboard", { history: false, source: options.source || "admin_control", scroll: options.scroll !== false });
  if (target.tab) setAdminWorkflowTab(target.tab);
  if (target.fieldAgentKpi) adminOpenFieldAgentKpi(target.fieldAgentKpi);
  scrollAdminControlIntoView(target.selector);
  if (target.label && options.toast !== false) toast(`Opened ${target.label}.`);
  renderAdminDashboard()
    .then(() => {
      if (target.tab) setAdminWorkflowTab(target.tab);
      if (target.fieldAgentKpi) adminOpenFieldAgentKpi(target.fieldAgentKpi);
      scrollAdminControlIntoView(target.selector);
    })
    .catch((error) => {
      console.warn("Admin control refresh failed", error);
    });
  return true;
}

function openKingShortcut(event, path) {
  if (event) event.preventDefault();
  const targetPath = normalizeRoutePath(path || "/admin");
  const control = adminControlForPath(targetPath);
  if (!control) {
    toast("That King shortcut is not connected yet.");
    return false;
  }
  try {
    if (currentPathWithQueryAndHash() !== targetPath) {
      window.history.pushState({ page: "admin", source: "king_shortcut", adminPath: targetPath }, "", targetPath);
    }
  } catch (error) {}
  openAdminControl(control, { source: "king_shortcut" });
  return false;
}

function currentPathWithQueryAndHash() {
  return `${window.location.pathname || "/"}${window.location.search || ""}${window.location.hash || ""}`;
}

function updateRouteHistoryForPage(page, source = "show_page") {
  const route = routeForPage(page);
  if (!route || currentPathWithQueryAndHash() === route) return;
  try {
    window.history.pushState({ page, source }, "", route);
  } catch (error) {}
}

let publicRouteLoadSeq = 0;
let publicRouteTargetPage = "";

function beginPublicRouteIntent(page) {
  const targetPage = normalizePageKey(page);
  if (!targetPage || !routeForPage(targetPage)) return publicRouteLoadSeq;
  publicRouteLoadSeq += 1;
  publicRouteTargetPage = targetPage;
  return publicRouteLoadSeq;
}

function isCurrentPublicRouteLoad(loadToken, page) {
  return Boolean(loadToken)
    && loadToken === publicRouteLoadSeq
    && publicRouteTargetPage === normalizePageKey(page);
}

function closeRouteTransientModals(nextPage, previousPage) {
  if (!previousPage || nextPage === previousPage) return;
  const modalIds = [];
  if (nextPage !== "list-property") modalIds.push("list-choice-modal", "listing-submit-modal");
  if (nextPage !== "detail") modalIds.push("save-property-modal", "report-modal");
  if (nextPage !== "ai-chatbot") modalIds.push("howto-video-modal");
  modalIds.forEach((id) => {
    const el = document.getElementById(id);
    if (el?.classList.contains("open")) el.classList.remove("open");
  });
  if (modalIds.length) syncModalOpenState();
}

function showPage(page, options = {}) {
  const targetPage = normalizePageKey(page);
  beginPublicRouteIntent(targetPage);
  const previousPage = currentPage;
  const el = document.getElementById("page-" + targetPage);
  if (el && isPublicRouteSkeletonElement(el) && routeForPage(targetPage)) {
    loadPublicRouteFragment(currentUrlForPublicRoutePage(targetPage), targetPage, {
      source: options.source || "show_page_skeleton_recovery",
      scroll: options.scroll !== false,
      loadToken: publicRouteLoadSeq
    });
    return;
  }
  if (el) {
    if (!el.classList.contains("active")) {
      document.querySelectorAll(".page.active").forEach((p) => {
        if (p !== el) p.classList.remove("active");
      });
      el.classList.add("active");
    }
    if (options.scroll !== false) window.scrollTo({ top: 0, left: 0, behavior: "auto" });
    lastPage = currentPage;
    currentPage = targetPage;
    closeRouteTransientModals(targetPage, previousPage);
    mountSectionSearchShell(targetPage);
    if (options.history !== false) updateRouteHistoryForPage(targetPage, options.source || "show_page");
  } else {
    const route = routeForPage(targetPage);
    if (route && window.location.pathname !== route) {
      navigatePublicRoute(route, null, { source: "show_page_fallback" });
      return;
    }
  }
  closeMobile();
  window.setTimeout(() => refreshActivePublicMapsAfterRoute(), 120);
  window.requestAnimationFrame(() => scheduleMapsInit({ force: targetPage !== previousPage }));
  if (targetPage && targetPage !== previousPage) {
    trackEvent("page_view", { page: targetPage });
  }
  if (targetPage === "finder-dashboard") renderFinderDashboard();
  if (targetPage === "student-dashboard") renderStudentDashboard();
  if (targetPage === "saved") renderSaved();
  if (targetPage === "agent-dashboard") renderAgentDashboard();
  if (targetPage === "field-dashboard") renderFieldDashboard();
  if (targetPage === "staff-dashboard") renderStaffDashboard();
  if (targetPage === "advertiser-dashboard") renderAdvertiserDashboard();
  if (targetPage === "admin-dashboard") renderAdminDashboard();
  if (targetPage === "admin-setup-status") renderAdminSetupStatus();
  if (targetPage === "list-property") {
    if (previousPage !== "list-property") {
      listWizardStep = 1;
      lpListingPathChoice = "";
      lpInquiryReference = "";
      lpMainPhotoIndex = 0;
      lpSelectedPhotos = [];
      lpPhotoUploadUrls = [];
      lpPhotoUploadSignature = "";
      lpPhotoAssignments = {};
      lpListingOtpToken = "";
      lpListingOtpVerifiedPhone = "";
      lpResolvedLocationLabel = "";
      lpLastHierarchySignature = "";
      lpLastAddressValue = "";
      lpAreaManualOverride = false;
      lpStreetManualOverride = false;
      lpAddressManualOverride = false;
      const success = document.getElementById("lp-success-box");
      if (success) success.classList.add("hidden");
      renderLpVideoPreview();
    }
    const routeType = getListPropertyRouteType();
    if (routeType) setListChoiceType(routeType);
    if (getListPropertyRouteMode() === "online") {
      chooseListPropertyOnline({ source: "route_query", skipModalClose: true });
    } else {
      setListChoiceType(getListChoiceType());
      setListPropertyFormVisible(false);
      maybeOpenListPropertyChoiceModal();
    }
  }
  syncPublicWhatsappLinks();
}

const PUBLIC_ROUTE_SKELETON_LABELS = Object.freeze({
  sale: "For Sale",
  rent: "To Rent",
  students: "Student Accommodation",
  commercial: "Commercial",
  land: "Land",
  brokers: "Brokers",
  mortgage: "Mortgage Finder",
  "ai-chatbot": "Discover AI Chatbot",
  advertise: "Advertise",
  "how-it-works": "How it works",
  careers: "Careers",
  help: "Help Centre",
  safety: "Safety Tips",
  fraud: "Anti-Fraud",
  "privacy-policy": "Privacy Policy",
  "cookie-policy": "Cookie Policy",
  terms: "Terms",
  "list-property": "List Property",
  about: "About Us",
  saved: "Saved"
});

function isPublicRouteSkeletonElement(el) {
  if (!el) return false;
  const skeletonRoute = el.dataset?.publicRouteSkeleton || "";
  const text = String(el.textContent || "");
  return Boolean(skeletonRoute)
    || el.classList?.contains("route-fragment-loading")
    || text.includes("Loading the latest makaug.com page.");
}

function getPublicRoutePageCandidates(doc, page) {
  if (!doc || !page) return [];
  const targetPage = normalizePageKey(page);
  if (!targetPage) return [];
  return Array.from(doc.querySelectorAll(`[id="page-${targetPage}"]`));
}

function getHydratedPublicRoutePage(doc, page) {
  return getPublicRoutePageCandidates(doc, page).find((candidate) => !isPublicRouteSkeletonElement(candidate)) || null;
}

function currentUrlForPublicRoutePage(page) {
  const targetPage = normalizePageKey(page);
  const currentPath = normalizeRoutePath(window.location.pathname || "/");
  if (pageForPublicRoute(currentPath) === targetPage) return currentPathWithQueryAndHash();
  return routeForPage(targetPage) || "/";
}

function mountPublicRouteSkeleton(page) {
  const targetPage = normalizePageKey(page);
  if (!targetPage || document.getElementById(`page-${targetPage}`)) return false;
  const label = PUBLIC_ROUTE_SKELETON_LABELS[targetPage] || "Loading";
  const main = document.createElement("main");
  main.id = `page-${targetPage}`;
  main.className = "page active route-fragment-loading";
  main.setAttribute("data-public-route-skeleton", targetPage);
  main.innerHTML = `
    <section class="bg-green-800 py-12 text-white">
      <div class="max-w-5xl mx-auto px-4">
        <p class="text-green-200 text-sm font-bold uppercase tracking-wide">makaug.com</p>
        <h1 class="text-4xl font-black serif mt-2">${label}</h1>
        <p class="text-green-50 mt-3">Loading the latest makaug.com page.</p>
      </div>
    </section>
    <section class="max-w-5xl mx-auto px-4 py-10">
      <div class="rounded-3xl border border-green-100 bg-white p-6 min-h-[220px]">
        <div class="h-4 w-40 rounded-full bg-green-100"></div>
        <div class="mt-5 grid gap-3 md:grid-cols-3">
          <div class="h-28 rounded-2xl bg-gray-50"></div>
          <div class="h-28 rounded-2xl bg-gray-50"></div>
          <div class="h-28 rounded-2xl bg-gray-50"></div>
        </div>
      </div>
    </section>
  `;
  document.querySelectorAll(".page.active").forEach((el) => el.classList.remove("active"));
  const footer = document.querySelector("footer");
  document.body.insertBefore(main, footer || document.body.lastElementChild);
  closeRouteTransientModals(targetPage, currentPage);
  lastPage = currentPage;
  currentPage = targetPage;
  window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  return true;
}

function mountPublicRouteFragment(doc, page) {
  const incoming = getHydratedPublicRoutePage(doc, page);
  if (!incoming) return false;
  const imported = document.importNode(incoming, true);
  imported.classList.remove("route-fragment-loading");
  imported.removeAttribute("data-public-route-skeleton");
  imported.classList.add("active");
  document.querySelectorAll(".page").forEach((el) => {
    if (el.id !== imported.id) el.remove();
  });
  const existing = document.getElementById(imported.id);
  if (existing) {
    existing.replaceWith(imported);
  } else {
    const footer = document.querySelector("footer");
    document.body.insertBefore(imported, footer || document.body.lastElementChild);
  }
  clearStaleMapRegistry();
  doc.querySelectorAll(".modal-overlay").forEach((modal) => {
    if (!modal.id || document.getElementById(modal.id)) return;
    document.body.appendChild(document.importNode(modal, true));
  });
  return true;
}

async function loadPublicRouteFragment(nextUrl, page, options = {}) {
  const source = options.source || "spa_fragment";
  const loadToken = options.loadToken || beginPublicRouteIntent(page);
  document.documentElement.classList.add("route-loading");
  try {
    const response = await fetch(nextUrl, {
      method: "GET",
      headers: { Accept: "text/html", "X-makaug-Route-Fragment": "1" },
      credentials: "same-origin"
    });
    if (!response.ok) throw new Error(`Route fetch failed (${response.status})`);
    const html = await response.text();
    const doc = new DOMParser().parseFromString(html, "text/html");
    if (!isCurrentPublicRouteLoad(loadToken, page)) return false;
    if (!mountPublicRouteFragment(doc, page)) throw new Error(`Route fragment missing page-${page}`);
    const url = new URL(nextUrl, window.location.origin);
    const nextPath = `${normalizeRoutePath(url.pathname)}${url.search || ""}${url.hash || ""}`;
    if (currentPathWithQueryAndHash() !== nextPath) {
      try { window.history.pushState({ page, source }, "", nextPath); } catch (error) {}
    }
    renderAll();
    renderHowToVideoSections();
    renderMortgageFinder();
    filterStudents();
    filterCommercial();
    filterLand();
    wireSearchTypeahead();
    setLang(currentLang, true, false);
    showPage(page, { history: false, source, scroll: options.scroll !== false });
    applyHeroSearchHandoff(page);
    if (!syncActiveRouteSearchHandoff(`${source}_route_query`)) {
      runSectionSearch(page, { source: `${source}_fragment` });
    }
    return true;
  } catch (error) {
    if (!isCurrentPublicRouteLoad(loadToken, page)) return false;
    console.warn("Falling back to full route navigation", error);
    window.location.href = nextUrl;
    return false;
  } finally {
    document.documentElement.classList.remove("route-loading");
  }
}

function navigatePublicRoute(target, event, options = {}) {
  if (event) event.preventDefault();
  let url;
  try {
    url = new URL(String(target || "/"), window.location.origin);
  } catch (error) {
    return true;
  }
  if (url.origin !== window.location.origin) return true;
  const path = normalizeRoutePath(url.pathname);
  if (path === "/login") {
    openAuthSignIn(authAudienceFromLoginParams(url.searchParams));
    const nextUrl = `${path}${url.search || ""}${url.hash || ""}`;
    if (currentPathWithQueryAndHash() !== nextUrl) {
      try { window.history.pushState({ page: "auth", source: options.source || "spa_login" }, "", nextUrl); } catch (error) {}
    }
    return false;
  }
  const adminControl = adminControlForPath(path);
  if (adminControl) {
    const nextUrl = `${path}${url.search || ""}${url.hash || ""}`;
    if (currentPathWithQueryAndHash() !== nextUrl) {
      try { window.history.pushState({ page: "admin", source: options.source || "spa_admin", adminPath: path }, "", nextUrl); } catch (error) {}
    }
    openAdminControl(adminControl, { source: options.source || "spa_admin" });
    return false;
  }
  if (["/signup", "/student-signup", "/broker-signup", "/field-agent-signup", "/advertiser-signup"].includes(path) || url.searchParams.get("auth") === "create") {
    const role = path.includes("student")
      ? "student"
      : (path.includes("broker")
        ? "agent"
        : (path.includes("field-agent")
          ? "field_agent"
          : (path.includes("advertiser") ? "advertiser" : (url.searchParams.get("role") || url.searchParams.get("audience") || "finder"))));
    openAuthSignUp(role);
    const nextUrl = `${path}${url.search || ""}${url.hash || ""}`;
    if (currentPathWithQueryAndHash() !== nextUrl) {
      try { window.history.pushState({ page: "auth-create", role, source: options.source || "spa_signup" }, "", nextUrl); } catch (error) {}
    }
    return false;
  }
  const page = pageForPublicRoute(path);
  if (!page) return true;
  const loadToken = beginPublicRouteIntent(page);
  const nextUrl = `${path}${url.search || ""}${url.hash || ""}`;
  const existingPublicRoutePage = document.getElementById(`page-${page}`);
  if (!existingPublicRoutePage || isPublicRouteSkeletonElement(existingPublicRoutePage)) {
    mountPublicRouteSkeleton(page);
    if (currentPathWithQueryAndHash() !== nextUrl) {
      try { window.history.pushState({ page, source: options.source || "spa_link_loading" }, "", nextUrl); } catch (error) {}
    }
    loadPublicRouteFragment(nextUrl, page, { ...options, loadToken });
    return false;
  }
  if (currentPathWithQueryAndHash() !== nextUrl) {
    try { window.history.pushState({ page, source: options.source || "spa_link" }, "", nextUrl); } catch (error) {}
  }
  showPage(page, { history: false, source: options.source || "spa_link" });
  applyHeroSearchHandoff(page);
  syncActiveRouteSearchHandoff(`${options.source || "spa_link"}_route_query`);
  return false;
}

let publicRouteInterceptorInstalled = false;
function installPublicRouteInterceptor() {
  if (publicRouteInterceptorInstalled) return;
  publicRouteInterceptorInstalled = true;
  document.addEventListener("click", (event) => {
    if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    const anchor = event.target?.closest?.("a[href]");
    if (!anchor || anchor.target || anchor.hasAttribute("download") || anchor.dataset.noSpa === "true") return;
    let url;
    try {
      url = new URL(anchor.getAttribute("href"), window.location.origin);
    } catch (error) {
      return;
    }
    if (url.origin !== window.location.origin) return;
    const handled = navigatePublicRoute(url, event, { source: "internal_link" });
    if (handled === false) {
      event.stopPropagation();
    }
  });
  window.addEventListener("popstate", () => {
    parseInitialDeepLink();
  });
}

function returnToLastPageFromDetail() {
  const target = lastPage || "home";
  showPage(target);
  const route = routeForPage(target) || "/";
  try {
    if (route && window.location.pathname !== route) {
      window.history.pushState({ page: target, source: "detail_back" }, "", route);
    }
  } catch (error) {}
  return false;
}

function mapRemotePropertyForUi(p, options = {}) {
  const images = Array.isArray(p?.images) ? p.images : [];
  const extraFields = p?.extra_fields && typeof p.extra_fields === "object" ? p.extra_fields : {};
  const imageItems = images.map((item, index) => ({
    url: item.url || item,
    is_main: item.is_primary === true || index === 0,
    sort_order: item.sort_order ?? index,
    slot_key: item.slot_key || item.slot || "",
    slot: item.slot_key || item.slot || "",
    room_label: /^photo\s*\d+$/i.test(String(item.room_label || "").trim()) ? "" : (item.room_label || ""),
    location_label: [p.area, p.district].filter(Boolean).join(", ")
  })).filter((item) => item.url);
  const id = String(p?.id || "");
  const thirdPartyDiscovery = isFoundOnlineListing(p);
  const publicImageItems = thirdPartyDiscovery ? [] : imageItems;
  const normalizedListingType = normalizeType(p?.listing_type || p?.type);
  const publicListingType = normalizedListingType || getHeroPropertyOpportunityBucket(p);
  const nearestUniversity = inferStudentNearestUniversity({ ...p, type: publicListingType, extra_fields: extraFields });  const studentUniversities = normalizeStudentUniversityList([
    ...(Array.isArray(p?.student_universities) ? p.student_universities : []),
    ...(Array.isArray(extraFields.student_universities) ? extraFields.student_universities : []),
    nearestUniversity
  ]);
  return {
    ...p,
    id,
    backend_id: id,
    title: p?.title || "Untitled listing",
    type: publicListingType,
    subtype: p?.property_type || p?.subtype || "Property",
    title_type: p?.title_type || extraFields.title_type || "",
    land_title_available: getLandTitleAvailabilityValue(p),
    beds: p?.bedrooms,
    baths: p?.bathrooms,
    price: Number(p?.price || 0),
    period: p?.price_period || p?.period || "",
    img: thirdPartyDiscovery ? "" : (p?.primary_image_url || p?.img || publicImageItems[0]?.url || "https://images.unsplash.com/photo-1560518883-ce09059eeffa?w=900&q=80"),
    desc: p?.description || p?.desc || "",
    address: p?.address || "",
    lat: parseFloatSafe(p?.latitude ?? p?.lat),
    lng: parseFloatSafe(p?.longitude ?? p?.lng),
    status: p?.status || "pending",
    sold_at: p?.sold_at || null,
    moderation_status: normalizeModerationStatus(p?.status),
    featured: p?.featured === true || String(extraFields.featured || "").toLowerCase() === "true",
    featured_at: p?.featured_at || extraFields.featured_at || null,
    registration_status: p?.registration_status || p?.agent_registration_status || extraFields.lister_registration_status || "not_registered",
    lister_registration_status: extraFields.lister_registration_status || p?.registration_status || "not_registered",
    inquiry_reference: p?.inquiry_reference || "",
    inquiry_count: Number(p?.inquiry_count || p?.lead_count || p?.leads || 0) || 0,
    agent: p?.agent_id || p?.agent || null,
    lister_display_name: p?.lister_name || p?.contact_display_name || "",
    area_highlights: extraFields.area_highlights || p?.area_highlights || "",
    translations: extraFields.translations || p?.translations || {},
    city: p?.city || extraFields.city || "",
    neighborhood: p?.neighborhood || extraFields.neighborhood || "",
    region: p?.region || extraFields.region || "",
    street_name: p?.street_name || extraFields.street_name || "",
    preferred_contact_method: p?.preferred_contact_method || extraFields.preferred_contact_method || "both",
    video_url: p?.video_url || extraFields.video_url || extraFields.youtube_url || extraFields.tiktok_url || "",
    youtube_url: p?.youtube_url || extraFields.youtube_url || "",
    tiktok_url: p?.tiktok_url || extraFields.tiktok_url || (/tiktok\.com/i.test(String(p?.video_url || extraFields.video_url || extraFields.source_url || "")) ? (p?.video_url || extraFields.video_url || extraFields.source_url || "") : ""),
    resolved_location_label: p?.resolved_location_label || extraFields.resolved_location_label || "",
    nearby_places: normalizeNearbyPlacesForUi(
      Array.isArray(extraFields.nearby_facilities) ? extraFields.nearby_facilities : (Array.isArray(p?.nearby_places) ? p.nearby_places : [])
    ),
    nearest_university: nearestUniversity || null,
    distance_to_uni_km: parseFloatSafe(p?.distance_to_uni_km ?? extraFields.distance_to_uni_km ?? extraFields.uni_distance),
    student_universities: studentUniversities,
    images: publicImageItems,
    third_party_discovery_result: thirdPartyDiscovery,
    detail_loaded: options.detailLoaded === true || publicImageItems.length > 0,
    owner_preview_visible: options.ownerPreview === true,
    owner_preview_token: options.token || ""
  };
}

function findPropertyForUi(id) {
  return PROPERTIES.find((p) => String(p.id) === String(id) || String(p.backend_id || "") === String(id));
}

function upsertPropertyForUi(property) {
  if (!property?.id) return null;
  const mapped = property.type ? property : mapRemotePropertyForUi(property);
  mapped.remote_source = mapped.remote_source || "api";
  const idx = PROPERTIES.findIndex((p) => String(p.id) === String(mapped.id) || String(p.backend_id || "") === String(mapped.id));
  if (idx >= 0) {
    const existing = PROPERTIES[idx];
    const next = { ...existing, ...mapped };
    if (isFoundOnlineListing(mapped)) {
      next.images = [];
      next.img = "";
    } else if ((!Array.isArray(mapped.images) || mapped.images.length === 0) && Array.isArray(existing.images) && existing.images.length) {
      next.images = existing.images;
    }
    if (existing.detail_loaded === true && mapped.detail_loaded !== true) {
      next.detail_loaded = true;
    }
    if (existing.owner_preview_token && !mapped.owner_preview_token) {
      next.owner_preview_token = existing.owner_preview_token;
      next.owner_preview_visible = existing.owner_preview_visible;
    }
    PROPERTIES[idx] = next;
    return PROPERTIES[idx];
  } else {
    PROPERTIES.push(mapped);
  }
  return mapped;
}

function applyPublicFeaturedRows(featuredRows = []) {
  const rows = Array.isArray(featuredRows) ? featuredRows.filter((p) => !adminRecordLooksLikeTest(p)) : [];
  publicFeaturedListingsFromApi = rows.map((p) => upsertPropertyForUi(p)).filter(Boolean);
  return publicFeaturedListingsFromApi;
}

async function fetchPublicFeaturedListingsFromApi() {
  const featuredResponse = await apiRequest("/api/properties?status=approved&featured=true&limit=12&page=1&public_only=1&sort=featured&include_summary=0", { skipAuth: true });
  return Array.isArray(featuredResponse?.data) ? featuredResponse.data.filter((p) => !adminRecordLooksLikeTest(p)) : [];
}

function applyPublicOpportunityStats(stats) {
  const nextStats = normalizeHeroOpportunityStats(stats);
  if (!nextStats) return false;
  publicListingsApiStats = nextStats;
  publicListingsApiTotal = nextStats.total;
  renderHeroPropertyOpportunityCounter();
  return true;
}

function publicOpportunityStatsFromApiResponse(response) {
  return response?.summary?.public_opportunities || response?.summary || null;
}

async function fetchPublicOpportunityStatsFromApi() {
  if (window.__makaugPublicSummaryPromise && !window.__makaugPublicSummaryConsumed) {
    window.__makaugPublicSummaryConsumed = true;
    try {
      const preloadedResponse = await window.__makaugPublicSummaryPromise;
      const preloadedStats = publicOpportunityStatsFromApiResponse(preloadedResponse);
      if (preloadedStats) return preloadedStats;
    } catch (prefetchError) {
      console.warn("Unable to use preloaded public opportunity summary", prefetchError);
    }
  }
  const response = await apiRequest(PUBLIC_OPPORTUNITY_SUMMARY_PATH, { skipAuth: true });
  return publicOpportunityStatsFromApiResponse(response);
}

async function loadRemotePropertyDetailForUi(id, options = {}) {
  const listingId = String(id || "").trim();
  if (!listingId) return null;
  const response = await apiRequest(`/api/properties/${encodeURIComponent(listingId)}`, { skipAuth: options.skipAuth !== false });
  const mapped = mapRemotePropertyForUi(response?.data || {}, { ...options, detailLoaded: true });
  mapped.remote_source = "api";
  return upsertPropertyForUi(mapped) || mapped;
}

async function hydratePropertyDetailForUi(property) {
  if (!property) return null;
  if (property.detail_loaded || property.owner_preview_visible === true) return property;
  const listingId = property.backend_id || property.id;
  if (!listingId || property.remote_source !== "api") return property;
  try {
    return await loadRemotePropertyDetailForUi(listingId);
  } catch (error) {
    console.warn("Unable to load full listing detail", error);
    return property;
  }
}

async function fetchPublicPaginatedRows(path, options = {}) {
  const limit = Math.min(Math.max(Number(options.limit || 100), 1), 100);
  const maxPages = Math.min(Math.max(Number(options.maxPages || 50), 1), 200);
  const rows = [];
  let firstResponse = null;
  let page = 1;
  let totalPages = 1;
  const hasSummaryParam = /[?&](include_summary|includeSummary|summary)=/i.test(path);
  do {
    const separator = path.includes("?") ? "&" : "?";
    const includeSummary = options.includeSummary !== false && page === 1;
    const summaryParam = hasSummaryParam ? "" : `&include_summary=${includeSummary ? "1" : "0"}`;
    const response = await apiRequest(`${path}${separator}limit=${limit}&page=${page}${summaryParam}`, { skipAuth: true });
    if (!firstResponse) firstResponse = response;
    rows.push(...(Array.isArray(response?.data) ? response.data : []));
    totalPages = Math.max(1, Number(response?.pagination?.totalPages || 1));
    if (typeof options.onPage === "function") {
      try {
        options.onPage({ rows: rows.slice(), firstResponse, response, page, totalPages });
      } catch (pageCallbackError) {
        console.warn("Public listings page callback failed", pageCallbackError);
      }
    }
    page += 1;
  } while (page <= totalPages && page <= maxPages);
  return { rows, firstResponse };
}

function applyPublicRowsForUi(publicRowsSnapshot, responseSnapshot, options = {}) {
  const rows = Array.isArray(publicRowsSnapshot) ? publicRowsSnapshot.filter((p) => !adminRecordLooksLikeTest(p)) : [];
  const nextStats = normalizeHeroOpportunityStats(responseSnapshot?.summary?.public_opportunities || responseSnapshot?.summary) || null;
  if (nextStats) publicListingsApiStats = nextStats;
  const exactResponseTotalValue = responseSnapshot?.pagination?.approximate ? null : Number(responseSnapshot?.pagination?.total);
  const exactResponseTotal = Number.isFinite(exactResponseTotalValue) && exactResponseTotalValue > 0 ? exactResponseTotalValue : null;
  const apiTotal = Number(publicListingsApiStats?.total ?? exactResponseTotal ?? publicListingsApiTotal ?? rows.length);
  publicListingsApiTotal = Number.isFinite(apiTotal) ? apiTotal : rows.length;
  const featuredRows = Array.isArray(options.featuredRows) ? options.featuredRows : [];
  const combinedRows = [...rows, ...featuredRows];
  if (options.prune === true) {
    const remoteIds = new Set(combinedRows.map((p) => String(p.id || "")).filter(Boolean));
    for (let i = PROPERTIES.length - 1; i >= 0; i -= 1) {
      const p = PROPERTIES[i];
      const id = String(p?.backend_id || p?.id || "");
      if (p?.remote_source === "api" && id && !remoteIds.has(id)) {
        PROPERTIES.splice(i, 1);
      }
    }
  }
  combinedRows.forEach((p) => upsertPropertyForUi(p));
  if (options.prune === true || featuredRows.length) {
    applyPublicFeaturedRows(featuredRows);
  }
  publicListingsFromApiLoaded = true;
  renderHeroPropertyOpportunityCounter();
  return rows;
}

function activePublicInventoryCategoryFromRoute() {
  const path = String(window.location.pathname || "").replace(/\/+$/, "") || "/";
  if (path === "/for-sale") return "sale";
  if (path === "/to-rent") return "rent";
  if (path === "/commercial") return "commercial";
  if (path === "/land") return "land";
  if (path === "/student-accommodation" || path === "/students") return "student";
  return "";
}

function publicInventoryCategoryPath(category) {
  const normalized = category === "students" ? "student" : normalizeType(category);
  if (normalized === "student") return "/api/properties?status=approved&public_only=1&student_portal=1";
  if (["sale", "rent", "commercial", "land"].includes(normalized)) {
    return `/api/properties?status=approved&public_only=1&listing_type=${encodeURIComponent(normalized)}`;
  }
  return "";
}

function publicInventoryRouteSearchPath(category) {
  const page = category === "student" ? "students" : normalizePageKey(category);
  const payload = routeSearchHandoffPayload(page);
  const config = sectionSearchConfigFor(page);
  if (!payload || !config) return "";
  const query = normalizeInput(payload.query || payload.area || "");
  const area = normalizeInput(payload.area || "");
  const filters = payload.filters || {};
  const hasSearch = Boolean(query || area || Object.values(filters).some(Boolean));
  if (!hasSearch) return "";
  const params = new URLSearchParams();
  params.set("status", "approved");
  params.set("public_only", "1");
  if (config.backendCategory === "students") {
    params.set("student_portal", "1");
  } else {
    params.set("listing_type", config.backendCategory);
  }
  if (query) params.set("query", query);
  if (area && area !== query) params.set(page === "students" ? "studentCampus" : "area", area);
  if (filters.propertyType) params.set("property_type", filters.propertyType);
  if (filters.minPrice) params.set("min_price", String(filters.minPrice));
  if (filters.maxPrice) params.set("max_price", String(filters.maxPrice));
  if (filters.bedrooms) params.set("bedrooms", String(filters.bedrooms));
  if (filters.amenities) params.set("amenities", String(filters.amenities));
  if (filters.commercialType) params.set("commercial_type", String(filters.commercialType));
  if (filters.landTitleType) params.set("land_title_type", String(filters.landTitleType));
  return `/api/properties/search?${params.toString()}`;
}

function hydrateVisibleRouteSearchResults(source = "route_search_backend_results") {
  const activeCategory = activePublicInventoryCategoryFromRoute();
  if (!activeCategory || !publicInventoryRouteSearchPath(activeCategory)) return false;
  refreshActivePublicInventoryCategoryFromApi({ silent: true })
    .then((loaded) => {
      if (loaded && activeCategory === activePublicInventoryCategoryFromRoute()) {
        syncActiveRouteSearchHandoff(source);
      }
    })
    .catch((error) => console.warn("Route search hydration failed", error));
  return true;
}

function exactPublicPaginationTotal(response) {
  if (response?.pagination?.approximate) return 0;
  const total = Number(response?.pagination?.total || 0) || 0;
  return total > 0 ? total : 0;
}

async function fetchPublicCategoryRows(category, totalCount = 0, options = {}) {
  const path = publicInventoryCategoryPath(category);
  if (!path) return { rows: [], firstResponse: null };
  const limit = PUBLIC_LISTINGS_BACKGROUND_PAGE_LIMIT;
  const expectedPages = Math.ceil(Math.max(0, Number(totalCount) || 0) / limit) || 1;
  const maxPages = Math.min(Math.max(expectedPages, 1), PUBLIC_LISTINGS_BACKGROUND_MAX_PAGES);
  const separator = path.includes("?") ? "&" : "?";
  const responses = await Promise.all(Array.from({ length: maxPages }, (_, index) => {
    const page = index + 1;
    return apiRequest(`${path}${separator}limit=${limit}&page=${page}&include_summary=0`, { skipAuth: true })
      .then((response) => {
        const pageRows = Array.isArray(response?.data) ? response.data : [];
        if (pageRows.length && typeof options.onPageRows === "function") {
          try {
            options.onPageRows(pageRows, response, page);
          } catch (pageCallbackError) {
            console.warn("Public category inventory page callback failed", pageCallbackError);
          }
        }
        return response;
      })
      .catch((error) => {
        console.warn("Public category inventory page failed", { category, page, error: error?.message || error });
        return null;
      });
  }));
  const rows = responses.flatMap((response) => Array.isArray(response?.data) ? response.data : []);
  return { rows, firstResponse: responses.find(Boolean) || null };
}

async function refreshActivePublicInventoryCategoryFromApi({ silent = true } = {}) {
  const activeCategory = activePublicInventoryCategoryFromRoute();
  if (!activeCategory) return false;
  const activeRouteSearchPath = publicInventoryRouteSearchPath(activeCategory);
  const activeCategoryPath = activeRouteSearchPath || publicInventoryCategoryPath(activeCategory);
  if (!activeCategoryPath) return false;
  if (publicActiveCategoryHydrationPromises.has(activeCategory)) {
    return publicActiveCategoryHydrationPromises.get(activeCategory);
  }
  const hydrationPromise = (async () => {
    try {
      const { rows: firstCategoryRows, firstResponse: firstCategoryResponse } = await fetchPublicPaginatedRows(activeCategoryPath, {
        limit: PUBLIC_LISTINGS_FAST_PAGE_LIMIT,
        maxPages: 1,
        includeSummary: false
      });
      if (firstCategoryRows.length && activeCategory === activePublicInventoryCategoryFromRoute()) {
        applyPublicRowsForUi(firstCategoryRows, firstCategoryResponse);
        renderAll();
        syncActiveRouteSearchHandoff(activeRouteSearchPath ? "active_route_search_first_page" : "active_category_first_page");
      }
      const stats = publicListingsApiStats || await fetchPublicOpportunityStatsFromApi()
        .then((nextStats) => {
          if (applyPublicOpportunityStats(nextStats)) renderAll();
          return nextStats;
        })
        .catch((summaryError) => {
          console.warn("Unable to refresh public opportunity summary", summaryError);
          return null;
        });
      const firstCategoryTotal = exactPublicPaginationTotal(firstCategoryResponse);
      const categoryTotal = firstCategoryTotal || (publicOpportunityStatForCategory(activeCategory) ?? stats?.[activeCategory] ?? 0);
      if (activeRouteSearchPath) {
        const expectedPages = Math.ceil(Math.max(0, Number(categoryTotal) || 0) / PUBLIC_LISTINGS_BACKGROUND_PAGE_LIMIT) || 1;
        const { rows: searchRows, firstResponse: searchFirstResponse } = await fetchPublicPaginatedRows(activeRouteSearchPath, {
          limit: PUBLIC_LISTINGS_BACKGROUND_PAGE_LIMIT,
          maxPages: Math.min(Math.max(expectedPages, 1), 12),
          includeSummary: false,
          onPage: ({ rows, response }) => {
            if (activeCategory !== activePublicInventoryCategoryFromRoute()) return;
            applyPublicRowsForUi(rows, response);
            renderAll();
            syncActiveRouteSearchHandoff("active_route_search_page");
          }
        });
        if (searchRows.length && activeCategory === activePublicInventoryCategoryFromRoute()) {
          applyPublicRowsForUi(searchRows, searchFirstResponse || firstCategoryResponse);
          renderAll();
          syncActiveRouteSearchHandoff("active_route_search_complete");
        }
        return searchRows.length > 0 || firstCategoryRows.length > 0;
      }
      const { rows: categoryRows, firstResponse: categoryFirstResponse } = await fetchPublicCategoryRows(activeCategory, categoryTotal, {
        onPageRows: (pageRows, pageResponse) => {
          if (activeCategory !== activePublicInventoryCategoryFromRoute()) return;
          applyPublicRowsForUi(pageRows, pageResponse);
          renderAll();
        }
      });
      if (categoryRows.length && activeCategory === activePublicInventoryCategoryFromRoute()) {
        applyPublicRowsForUi(categoryRows, categoryFirstResponse);
        renderAll();
      }
      return categoryRows.length > 0;
    } catch (error) {
      if (!silent) toast(`Live ${activeCategory} listings refresh failed: ${error.message || "error"}`);
      return false;
    }
  })();
  publicActiveCategoryHydrationPromises.set(activeCategory, hydrationPromise);
  try {
    return await hydrationPromise;
  } finally {
    publicActiveCategoryHydrationPromises.delete(activeCategory);
  }
}

function schedulePublicCategoryDeepHydration(category, totalCount = 0) {
  const normalizedCategory = category === "students" ? "student" : normalizeType(category);
  if (!normalizedCategory || totalCount <= PUBLIC_LISTINGS_FAST_PAGE_LIMIT) return false;
  if (publicCategoryDeepHydrationTimers.has(normalizedCategory)) return false;
  const timer = window.setTimeout(() => {
    publicCategoryDeepHydrationTimers.delete(normalizedCategory);
    if (normalizedCategory !== activePublicInventoryCategoryFromRoute()) return;
    refreshActivePublicInventoryCategoryFromApi({ silent: true }).then((loaded) => {
      if (loaded && normalizedCategory === activePublicInventoryCategoryFromRoute()) {
        renderAll();
        resetMaps();
      }
    });
  }, PUBLIC_CATEGORY_DEEP_HYDRATION_DELAY_MS);
  publicCategoryDeepHydrationTimers.set(normalizedCategory, timer);
  return true;
}

async function refreshPublicListingsFromApi({ silent = true } = {}) {
  if (publicListingsApiLoading) return refreshActivePublicInventoryCategoryFromApi({ silent });
  publicListingsApiLoading = true;
  try {
    const activeCategory = activePublicInventoryCategoryFromRoute();
    const featuredRowsPromise = activeCategory ? Promise.resolve([]) : fetchPublicFeaturedListingsFromApi()
      .then((rows) => {
        const featuredListings = applyPublicFeaturedRows(rows);
        if (featuredListings.length) renderAll();
        return rows;
      })
      .catch((featuredError) => {
        console.warn("Unable to refresh featured listings", featuredError);
        return [];
      });
    const summaryStatsPromise = fetchPublicOpportunityStatsFromApi()
      .then((stats) => {
        if (applyPublicOpportunityStats(stats)) renderAll();
        return stats;
      })
      .catch((summaryError) => {
        console.warn("Unable to refresh public opportunity summary", summaryError);
        return null;
      });
    const activeRouteSearchPath = activeCategory ? publicInventoryRouteSearchPath(activeCategory) : "";
    const firstPagePath = activeCategory
      ? activeRouteSearchPath || publicInventoryCategoryPath(activeCategory) || "/api/properties?status=approved&public_only=1"
      : "/api/properties?status=approved&public_only=1";
    const firstPageRowsPromise = fetchPublicPaginatedRows(firstPagePath, {
      limit: PUBLIC_LISTINGS_FAST_PAGE_LIMIT,
      maxPages: 1,
      includeSummary: false
    });
    const [
      { rows: firstPageRows, firstResponse: firstPageResponse },
      summaryStats
    ] = await Promise.all([firstPageRowsPromise, summaryStatsPromise]);
    applyPublicRowsForUi(firstPageRows, firstPageResponse);
    renderAll();
    if (activeRouteSearchPath) syncActiveRouteSearchHandoff("initial_route_search_first_page");
    const firstPageCategoryTotal = activeCategory ? exactPublicPaginationTotal(firstPageResponse) : 0;
    const categoryTotal = activeCategory ? firstPageCategoryTotal || (publicOpportunityStatForCategory(activeCategory) ?? summaryStats?.[activeCategory] ?? 0) : 0;
    if (activeCategory) {
      if (activeRouteSearchPath) {
        const expectedPages = Math.ceil(Math.max(0, Number(categoryTotal) || 0) / PUBLIC_LISTINGS_BACKGROUND_PAGE_LIMIT) || 1;
        const { rows: searchRows, firstResponse: searchFirstResponse } = await fetchPublicPaginatedRows(activeRouteSearchPath, {
          limit: PUBLIC_LISTINGS_BACKGROUND_PAGE_LIMIT,
          maxPages: Math.min(Math.max(expectedPages, 1), 12),
          includeSummary: false,
          onPage: ({ rows, response }) => {
            if (activeCategory !== activePublicInventoryCategoryFromRoute()) return;
            applyPublicRowsForUi(rows, response);
            renderAll();
            syncActiveRouteSearchHandoff("initial_route_search_page");
          }
        });
        if (searchRows.length && activeCategory === activePublicInventoryCategoryFromRoute()) {
          applyPublicRowsForUi(searchRows, searchFirstResponse || firstPageResponse);
          renderAll();
          syncActiveRouteSearchHandoff("initial_route_search_complete");
        }
        return true;
      }
      schedulePublicCategoryDeepHydration(activeCategory, categoryTotal);
      return true;
    }
    const backgroundRowsPromise = fetchPublicPaginatedRows("/api/properties?status=approved&public_only=1", {
      limit: PUBLIC_LISTINGS_BACKGROUND_PAGE_LIMIT,
      maxPages: PUBLIC_LISTINGS_BACKGROUND_MAX_PAGES,
      includeSummary: false
    });
    const { rows: publicRows, firstResponse } = await backgroundRowsPromise;
    const featuredRows = await featuredRowsPromise;
    applyPublicRowsForUi(publicRows, firstResponse, { featuredRows, prune: true });
    renderAll();
    return true;
  } catch (e) {
    if (!silent) toast(`Live listings refresh failed: ${e.message || "error"}`);
    return false;
  } finally {
    publicListingsApiLoading = false;
  }
}

async function openOwnerListingPreview(listingId, token) {
  if (!listingId || !token) return false;
  try {
    const response = await apiRequest(`/api/properties/${encodeURIComponent(listingId)}/preview?token=${encodeURIComponent(token)}`);
    const property = mapRemotePropertyForUi(response?.data || {}, { ownerPreview: true, token, detailLoaded: true });
    upsertPropertyForUi(property);
    openDetail(property.id);
    toast("Private listing preview loaded.");
    return true;
  } catch (e) {
    toast(e.message || "Unable to load listing preview.");
    return false;
  }
}

async function openOwnerPreviewEdit(id) {
  const property = PROPERTIES.find((p) => String(p.id) === String(id) || String(p.backend_id || "") === String(id));
  if (!property?.owner_preview_token || !property?.backend_id) {
    toast("Preview edit token is missing.");
    return;
  }
  const title = window.prompt("Edit listing title:", property.title || "");
  if (title == null) return;
  const description = window.prompt("Edit listing description:", property.desc || property.description || "");
  if (description == null) return;
  try {
    const response = await apiRequest(`/api/properties/${encodeURIComponent(property.backend_id)}/preview`, {
      method: "PATCH",
      body: {
        token: property.owner_preview_token,
        listing: { title, description }
      }
    });
    property.title = response?.data?.title || title;
    property.desc = response?.data?.description || description;
    property.description = property.desc;
    toast("Listing wording updated.");
    openDetail(property.id);
  } catch (e) {
    toast(e.message || "Unable to update listing.");
  }
}

async function parseInitialDeepLink() {
  normalizeLegacyHashPublicRoute();
  const path = (window.location.pathname || "/").replace(/\/+$/, "") || "/";
  const qs = new URLSearchParams(window.location.search || "");

  const authIntent = String(qs.get("auth") || "").toLowerCase();
  if (path === "/login" || authIntent === "signin") {
    openAuthSignIn(authAudienceFromLoginParams(qs));
    return true;
  }
  if (path === "/signup" || path === "/student-signup" || path === "/broker-signup" || path === "/field-agent-signup" || path === "/advertiser-signup" || authIntent === "create") {
    const role = path.includes("student")
      ? "student"
      : (path.includes("broker")
        ? "agent"
        : (path.includes("field-agent")
          ? "field_agent"
          : (path.includes("advertiser") ? "advertiser" : (qs.get("role") || qs.get("audience") || "finder"))));
    openAuthSignUp(role);
    return true;
  }

  const propertyFromPath = path.match(/^\/property\/([^/?#]+)/i)?.[1];
  const agentFromPath = path.match(/^\/agents?\/([^/?#]+)/i)?.[1];
  const propertyFromQuery = qs.get("property") || qs.get("listing");
  const brokerFromQuery = qs.get("broker") || qs.get("agent");
  const previewToken = qs.get("token") || qs.get("edit_token");

  if (qs.get("listing_preview") && propertyFromQuery && previewToken) {
    await openOwnerListingPreview(propertyFromQuery, previewToken);
    return true;
  }

  if (propertyFromPath || propertyFromQuery) {
    const pid = decodeURIComponent(propertyFromPath || propertyFromQuery || "");
    const found = getPublicListings().find((p) => String(p.id) === String(pid) || String(p.backend_id || "") === String(pid));
    if (found) {
      await openDetail(found.id);
      return true;
    }
    try {
      const loaded = await loadRemotePropertyDetailForUi(pid);
      if (loaded && isListingPublicVisible(loaded)) {
        await openDetail(loaded.id);
        return true;
      }
    } catch (error) {
      console.warn("Unable to open linked property", error);
    }
    if (publicListingsApiLoading || !publicListingsFromApiLoaded) {
      const loaded = await refreshPublicListingsFromApi({ silent: true });
      const retry = loaded
        ? getPublicListings().find((p) => String(p.id) === String(pid) || String(p.backend_id || "") === String(pid))
        : null;
      if (retry) {
        await openDetail(retry.id);
        return true;
      }
    }
  }

  if (path === "/property" && !propertyFromQuery) {
    const latest = getPublicListings().sort(sortListingsByNewest)[0];
    if (latest) {
      await openDetail(latest.id);
      return true;
    }
  }

  if (agentFromPath || brokerFromQuery) {
    const bid = agentFromPath || brokerFromQuery;
    if (!remoteBrokersLoaded) await refreshBrokersFromApi({ silent: true });
    const found = findBrokerById(bid);
    if (found) {
      await openBrokerProfile(found.id);
      return true;
    }
    try {
      const loaded = await loadRemoteBrokerProfileForUi(bid);
      if (loaded) {
        await openBrokerProfile(loaded.id);
        return true;
      }
    } catch (error) {
      console.warn("Unable to open linked broker", error);
    }
  }

  const adminControl = path === "/admin-dashboard" ? adminControlForPath("/admin") : adminControlForPath(path);
  if (adminControl) {
    if (isSignedInAdminUser() || adminApiKey || authState?.user) {
      await openAdminControl(adminControl, { history: false, source: "deep_link", toast: false });
    } else {
      openAuthSignIn("admin");
    }
    return true;
  }

  if (path === "/advertiser-dashboard") {
    if (authState?.user && derivePortalMode(authState.user, authState.user.portal_mode) === "advertiser") {
      showPage("advertiser-dashboard", { history: false, source: "deep_link" });
      renderAdvertiserDashboard();
    } else {
      openAuthSignIn("advertiser");
    }
    return true;
  }

  if (path === "/dashboard") {
    if (authState?.user && derivePortalMode(authState.user, authState.user.portal_mode) === "finder") {
      showPage("finder-dashboard", { history: false, source: "deep_link" });
      renderFinderDashboard();
    } else {
      openAuthSignIn("finder");
    }
    return true;
  }

  if (path === "/student-dashboard") {
    if (authState?.user && derivePortalMode(authState.user, authState.user.portal_mode) === "student") {
      showPage("student-dashboard", { history: false, source: "deep_link" });
      renderStudentDashboard();
    } else {
      openAuthSignIn("student");
    }
    return true;
  }

  if (path === "/broker-dashboard") {
    if (authState?.user && derivePortalMode(authState.user, authState.user.portal_mode) === "agent") {
      showPage("agent-dashboard", { history: false, source: "deep_link" });
      renderAgentDashboard();
    } else {
      openAuthSignIn("agent");
    }
    return true;
  }

  if (path === "/field-agent-dashboard") {
    if (authState?.user && derivePortalMode(authState.user, authState.user.portal_mode) === "field_agent") {
      showPage("field-dashboard", { history: false, source: "deep_link" });
      renderFieldDashboard();
    } else {
      openAuthSignIn("field_agent");
    }
    return true;
  }

  if (path === "/staff-dashboard") {
    if (authState?.user && ["moderator", "admin"].includes(derivePortalMode(authState.user, authState.user.portal_mode))) {
      showPage("staff-dashboard", { history: false, source: "deep_link" });
    } else {
      openAuthSignIn("moderator");
    }
    return true;
  }

  const publicRoutePage = pageForPublicRoute(path);
  if (publicRoutePage) {
    const existingPublicRoutePage = document.getElementById(`page-${publicRoutePage}`);
    if (!existingPublicRoutePage || isPublicRouteSkeletonElement(existingPublicRoutePage)) {
      await loadPublicRouteFragment(`${path}${window.location.search || ""}${window.location.hash || ""}`, publicRoutePage, {
        source: "popstate_missing_fragment",
        scroll: false
      });
      return true;
    }
    showPage(publicRoutePage, { history: false, source: "deep_link" });
    applyHeroSearchHandoff(publicRoutePage);
    syncActiveRouteSearchHandoff("deep_link_route_query");
    return true;
  }

  return false;
}

function setTab(el, type) {
  const group = el.parentElement;
  group.querySelectorAll(".tab-btn").forEach((b) => b.classList.remove("active"));
  el.classList.add("active");
  currentTab = type;
  setHeroLocationFilter(type);
  setHeroRadiusState(type);
  setHeroContextFilter(type);
  applyHeroSearchLanguageUI();
  setHeroLocationStatus(getNearMeSearchState(type) ? tr("heroLocationActive") : tr("heroLocationHelper"), getNearMeSearchState(type) ? "active" : "idle");
  closeHeroSuggestions();
  const heroInput = document.getElementById("hero-q");
  if (heroInput && document.activeElement === heroInput && heroInput.value.trim()) {
    renderTypeahead(heroInput, getLocationSuggestionPool(currentTab === "students"), () => {});
  }
}

function buildHeroSearchBackendPayload({ query = "", area = "", filters = {}, nearState = null, resultsCount = 0, category = currentTab } = {}) {
  const searchCategory = category || currentTab;
  const payload = {
    query,
    category: searchCategory,
    source: nearState ? "homepage_location_control" : "homepage_search",
    language: currentLang || "en",
    session: getAnalyticsClientId(),
    resultsCount
  };
  if (searchCategory === "students") {
    payload.student_portal = "true";
  } else {
    payload.listing_type = searchCategory;
  }
  const setFilter = (camelKey, snakeKey, value) => {
    if (!value) return;
    payload[camelKey] = value;
    payload[snakeKey] = value;
  };
  if (area) payload.area = area;
  if (filters.propertyType) payload.propertyType = filters.propertyType;
  if (filters.propertyType) payload.property_type = filters.propertyType;
  if (filters.minPrice) payload.minPrice = filters.minPrice;
  if (filters.minPrice) payload.min_price = filters.minPrice;
  if (filters.maxPrice) payload.maxPrice = filters.maxPrice;
  if (filters.maxPrice) payload.max_price = filters.maxPrice;
  if (filters.currency) payload.currency = filters.currency;
  if (filters.bedrooms) payload.bedrooms = filters.bedrooms;
  if (filters.bathrooms) payload.bathrooms = filters.bathrooms;
  if (filters.amenities) payload.amenities = filters.amenities;
  setFilter("commercialType", "commercial_type", filters.commercialType);
  setFilter("landTitleType", "land_title_type", filters.landTitleType);
  if (filters.sort) payload.sort = filters.sort;
  if (nearState) {
    payload.lat = nearState.lat;
    payload.lng = nearState.lng;
    payload.radiusMiles = nearState.radiusMiles || filters.radiusMiles || DEFAULT_NEAR_ME_RADIUS_MI;
    payload.radiusKm = nearState.radiusKm || filters.radiusKm || milesToKm(payload.radiusMiles);
    payload.radiusUnit = "miles";
    payload.locationSource = "browser_geolocation";
  }
  return payload;
}

function recordHeroSearchBackendPayload(payload = {}) {
  const params = new URLSearchParams();
  Object.entries(payload).forEach(([key, value]) => {
    if (value === undefined || value === null || value === "") return;
    if (key === "resultsCount" || key === "category") return;
    params.set(key, String(value));
  });
  params.set("limit", "12");
  const endpoint = `${API_BASE}/api/properties/search?${params.toString()}`;
  fetch(endpoint, { credentials: "same-origin" })
    .then((res) => res.json().catch(() => ({})).then((body) => ({ ok: res.ok, body })))
    .then(({ ok, body }) => {
      trackEvent("homepage_search_backend_checked", {
        category: payload.category,
        source: payload.source,
        radius_miles: payload.radiusMiles || null,
        backend_ok: ok,
        backend_results: Array.isArray(body?.data) ? body.data.length : null,
        outside_uganda: Boolean(body?.data?.outside_uganda || body?.error?.includes?.("outside Uganda"))
      });
    })
    .catch((error) => {
      trackEvent("homepage_search_backend_check_failed", {
        category: payload.category,
        source: payload.source,
        error: error?.message || "network_error"
      });
    });
}

