let lpTitleExampleIndex = 0;
let lpTitleExampleTimer = null;

function getLpTitleExamples(type = getListType()) {
  return LP_TITLE_EXAMPLES[type] || LP_TITLE_EXAMPLES.sale;
}

function renderLpTitleExample(example, animate = true) {
  const titleEl = document.getElementById("lp-title");
  const apply = () => {
    const text = translateListingLabel(example);
    if (titleEl && !titleEl.value.trim()) titleEl.placeholder = `e.g. ${text}`;
  };
  apply();
}

function updateLpTitleExamplesForType(type = getListType(), restart = false) {
  const examples = getLpTitleExamples(type);
  lpTitleExampleIndex = Math.min(lpTitleExampleIndex, examples.length - 1);
  renderLpTitleExample(examples[lpTitleExampleIndex] || examples[0], false);
  if (restart) startLpTitleExampleRotation(type);
}

function startLpTitleExampleRotation(type = getListType()) {
  if (lpTitleExampleTimer) clearInterval(lpTitleExampleTimer);
  const examples = getLpTitleExamples(type);
  lpTitleExampleTimer = window.setInterval(() => {
    lpTitleExampleIndex = (lpTitleExampleIndex + 1) % examples.length;
    renderLpTitleExample(examples[lpTitleExampleIndex]);
  }, 2800);
}

function updateLpTitleExampleState() {
  updateLpTitleExamplesForType(getListType(), false);
}

function updateListingModeHero(type) {
  const meta = LP_MODE_META[type] || LP_MODE_META.sale;
  const shell = document.getElementById("lp-wizard-shell");
  if (shell) {
    shell.classList.remove("lp-theme-sale", "lp-theme-rent", "lp-theme-land", "lp-theme-commercial", "lp-theme-student");
    shell.classList.add(meta.theme);
  }
  const icon = document.getElementById("lp-mode-icon");
  const title = document.getElementById("lp-mode-title");
  const copy = document.getElementById("lp-mode-copy");
  const kicker = document.getElementById("lp-mode-kicker");
  if (icon) icon.textContent = meta.icon;
  if (title) title.textContent = translateListingLabel(meta.title);
  if (copy) copy.textContent = translateListingLabel(meta.copy);
  if (kicker) kicker.textContent = translateListingLabel("Listing mode");
}

function setListType(type) {
  const previousType = lpCurrentFormType || getListType();
  if (type) {
    const radio = document.querySelector(`input[name='lp-type'][value='${type}']`);
    if (radio) radio.checked = true;
  }
  const selected = getListType();
  const cfg = LP_CONFIG[selected] || LP_CONFIG.sale;
  const preserveTypeSpecificValues = previousType === selected;

  updateListTypeChips(selected);
  updateListingModeHero(selected);
  lpChoiceType = selected;
  applyListPropertyTheme(selected);
  syncListChoiceCopy(selected);
  updateListPropertyWhatsAppLinks();
  updateBrokerListingContextBanner();

  const titleEl = document.getElementById("lp-title");
  const areaEl = document.getElementById("lp-area");
  const descEl = document.getElementById("lp-description");
  const areaLabelEl = document.getElementById("lp-area-label");
  const subtypeLabelEl = document.getElementById("lp-subtype-label");
  const sizeLabelEl = document.getElementById("lp-size-label");
  const sizeEl = document.getElementById("lp-size");
  const sizeWrapEl = document.getElementById("lp-size-wrap");
	      const periodLabelEl = document.getElementById("lp-period-label");
	      const availableFromWrap = document.getElementById("lp-available-from-wrap");
	      const availableFromLabel = document.getElementById("lp-available-from-label");
	      const bedsLabelEl = document.getElementById("lp-beds-label");
  const bathsLabelEl = document.getElementById("lp-baths-label");
  const bedsRow = document.getElementById("lp-beds-baths-row-wrap");
  const amenitiesLabelEl = document.getElementById("lp-amenities-label");
  const continueBtn = document.getElementById("lp-step1-next-btn");

  updateLpTitleExamplesForType(selected, true);
  if (areaEl) areaEl.placeholder = translateListingLabel("Auto-filled from district/city/neighbourhood");
  if (descEl) descEl.placeholder = translateListingLabel(cfg.descPlaceholder);
  if (areaLabelEl) areaLabelEl.textContent = translateListingLabel(cfg.areaLabel);
  if (subtypeLabelEl) subtypeLabelEl.textContent = translateListingLabel(cfg.subtypeLabel);
  if (sizeLabelEl) sizeLabelEl.textContent = translateListingLabel(cfg.sizeLabel);
  if (sizeEl) sizeEl.placeholder = translateListingLabel(cfg.sizePlaceholder);
  if (sizeWrapEl) sizeWrapEl.classList.toggle("hidden", cfg.showSize === false);
  if (cfg.showSize === false && sizeEl) sizeEl.value = "";
  if (!cfg.showBedsBaths) {
    const bedsEl = document.getElementById("lp-beds");
    const bathsEl = document.getElementById("lp-baths");
    if (bedsEl) bedsEl.value = "";
    if (bathsEl) bathsEl.value = "";
  }
	      if (periodLabelEl) periodLabelEl.textContent = translateListingLabel(cfg.periodLabel);
	      const showAvailableFrom = selected === "rent" || selected === "student" || selected === "land" || (selected === "commercial" && (document.getElementById("lp-extra-commercial_mode")?.value || "") === "rent");
	      if (availableFromWrap) availableFromWrap.classList.toggle("hidden", !showAvailableFrom);
	      if (availableFromLabel) {
	        availableFromLabel.textContent = translateListingLabel(selected === "land" ? "Available / Lease Starts From" : "Available From");
	      }
	      if (bedsLabelEl) bedsLabelEl.textContent = translateListingLabel(cfg.bedsLabel);
  if (bathsLabelEl) bathsLabelEl.textContent = translateListingLabel(cfg.bathsLabel);
  if (amenitiesLabelEl) amenitiesLabelEl.textContent = selected === "land" ? translateListingLabel("Land Features") : translateListingLabel("Amenities");
  if (continueBtn) continueBtn.textContent = translateListingLabel(cfg.continueLabel);
  if (bedsRow) bedsRow.classList.toggle("hidden", !cfg.showBedsBaths);

  setSelectOptions("lp-subtype", cfg.subtypes || [], (cfg.subtypes || [])[0]?.value, true);
  setSelectOptions("lp-period", cfg.periods || [], (cfg.periods || [])[0]?.value, true);
  renderLpExtraFields(selected, preserveTypeSpecificValues);
	      if (selected === "commercial") syncCommercialMode();
  renderLpAmenities(selected, preserveTypeSpecificValues);
  updateLpPhotoRequirements();
  updateListPreview();
  renderListReviewSummary();
  if (!document.getElementById("lp-city")?.options?.length || document.getElementById("lp-city")?.options?.length < 2) {
    populateLpCityOptions(lpVal("list-district-sel"), lpVal("lp-city"));
  }
  if (!document.getElementById("lp-neighborhood")?.options?.length || document.getElementById("lp-neighborhood")?.options?.length < 2) {
    populateLpNeighborhoodOptions(lpVal("list-district-sel"), lpVal("lp-city"), lpVal("lp-neighborhood"));
  }
  syncLpPublicNameSuggestion();
  updateLpLocationStepLocks();
  refreshListPinMapFromInputs();
  lpCurrentFormType = selected;
}

function lpVal(id) {
  return (document.getElementById(id)?.value || "").trim();
}

function lpNum(id) {
  const v = parseInt(lpVal(id).replace(/[^0-9]/g, ""), 10);
  return Number.isFinite(v) ? v : 0;
}

function renderListingDescriptionTranslationPreview() {
  const copyEl = document.getElementById("lp-description-preview-copy");
  const sourceEl = document.getElementById("lp-description-preview-source");
  if (!copyEl) return;
  const original = lpVal("lp-description");
  const lang = document.getElementById("lp-description-preview-language")?.value || "en";
  const names = {
    en: "English",
    lg: "Luganda",
    sw: "Kiswahili",
    ac: "Acholi",
    ny: "Runyankole",
    rn: "Rukiga",
    sm: "Lusoga",
    am: "Amharic",
    ar: "Arabic"
  };
  if (!original) {
    copyEl.textContent = translateListingLabel("Add a description to preview it in another language.");
    if (sourceEl) sourceEl.textContent = translateListingLabel("Source: original description. Translation review pending.");
    return;
  }
  copyEl.textContent = original;
  if (sourceEl) {
    const label = names[lang] || "selected language";
    sourceEl.textContent = lang === "en"
      ? "Source: original English description."
      : `Preview in ${label}: original shown until AI/manual translation is reviewed.`;
  }
}

function updateListPreview() {
  const type = getListType();
  const cfg = LP_CONFIG[type] || LP_CONFIG.sale;
  const badgeEl = document.getElementById("lp-preview-badge");
  const titleEl = document.getElementById("lp-preview-title");
  const locEl = document.getElementById("lp-preview-location");
  const priceEl = document.getElementById("lp-preview-price");
  const metaEl = document.getElementById("lp-preview-meta");
  const amenEl = document.getElementById("lp-preview-amenities");

  if (badgeEl) {
    badgeEl.className = `inline-flex items-center px-2.5 py-1 rounded text-xs font-bold ${cfg.badgeClass}`;
    badgeEl.textContent = translateListingLabel(cfg.badge);
  }

  const title = lpVal("lp-title") || translateListingLabel("Your listing title will appear here");
  if (titleEl) titleEl.textContent = title;

  const streetName = lpVal("lp-street-name");
  const area = lpVal("lp-area") || translateListingLabel("Area");
  const city = lpVal("lp-city");
  const district = lpVal("list-district-sel") || translateListingLabel("District");
  const locationParts = uniqueTextParts([streetName, area]);
  if (city && city !== area) locationParts.push(city);
  locationParts.push(district);
  if (locEl) locEl.textContent = locationParts.filter(Boolean).join(", ");

	      const priceNum = lpNum("lp-price");
	      const periodRaw = lpVal("lp-period");
	      const periodVal = (periodRaw === "once" || periodRaw === "neg") ? "" : periodRaw;
	      if (priceEl) priceEl.textContent = priceNum ? fmtP(priceNum, periodVal) : translateListingLabel("Price upon application");

  const metaParts = [];
  const subtype = document.getElementById("lp-subtype")?.selectedOptions?.[0]?.textContent || cfg.badge;
  if (subtype) metaParts.push(subtype);
  const size = lpVal("lp-size");
  if (cfg.showSize !== false && size) metaParts.push(size);

	      if (cfg.showBedsBaths) {
	        const beds = lpVal("lp-beds");
	        const baths = lpVal("lp-baths");
	        if (beds) metaParts.push(`${beds} ${cfg.bedsSuffix}`);
	        if (baths) metaParts.push(`${baths} ${cfg.bathsSuffix}`);
	      }
	      const availableFrom = lpVal("lp-available-from");
	      if (availableFrom) metaParts.push(`${translateListingLabel("Available From")}: ${availableFrom}`);

  (cfg.previewExtras || []).forEach((item) => {
    const fieldEl = document.getElementById(`lp-extra-${item.key}`);
    if (!fieldEl) return;
    const hiddenParent = fieldEl.closest("[data-depends-on]");
    if (hiddenParent && hiddenParent.classList.contains("hidden")) return;
    const raw = (fieldEl.value || "").trim();
    if (!raw) return;
    const itemLabel = translateListingLabel(item.label);
    if (item.key === "deposit") {
      const d = lpNum(`lp-extra-${item.key}`);
      if (d) metaParts.push(`${itemLabel}: ${fmtP(d)}`);
      return;
    }
    if (item.key === "uni_distance") {
      metaParts.push(`${itemLabel}: ${raw}km`);
      return;
    }
    if (item.key === "contract_months") {
      metaParts.push(`${itemLabel}: ${raw} ${translateListingLabel("months")}`);
      return;
    }
    if (item.key === "commercial_mode") {
      metaParts.push(`${itemLabel}: ${translateListingLabel(raw === "rent" ? "For Rent" : "For Sale")}`);
      return;
    }
    if (item.key === "land_title_available") {
      metaParts.push(`${itemLabel}: ${landTitleAvailabilityLabel(raw) || translateListingLabel("Not set")}`);
      return;
    }
    if (item.key === "students_welcome") {
      metaParts.push(`${itemLabel}: ${translateListingLabel(raw === "yes" ? "Yes" : "No")}`);
      return;
    }
    metaParts.push(`${itemLabel}: ${translateListingLabel(raw)}`);
  });

  if (metaEl) metaEl.textContent = metaParts.length ? metaParts.join(" • ") : translateListingLabel("Type • Key details");

  const checked = Array.from(document.querySelectorAll("#lp-amenities input:checked")).map((el) => el.getAttribute("data-label") || el.value);
  if (amenEl) amenEl.textContent = checked.length
    ? `${translateListingLabel("Amenities")}: ${checked.slice(0, 5).join(", ")}`
    : translateListingLabel("Amenities will appear here");
  renderListingDescriptionTranslationPreview();

  const previewWrap = document.getElementById("lp-preview-card-wrap");
  if (previewWrap) {
    lpPreviewPhotos.forEach((item) => {
      if (item?.ephemeral && item?.url && item.url.startsWith("blob:")) {
        try { URL.revokeObjectURL(item.url); } catch (e) {}
      }
    });
    lpPreviewPhotos = lpSelectedPhotos.map((file, idx) => ({
      url: URL.createObjectURL(file),
      name: file.name,
      slot: getLpPhotoSlotLabel(lpPhotoAssignments[idx], type) || `${translateListingLabel("Photo")} ${idx + 1}`,
      ephemeral: true,
      is_main: idx === lpMainPhotoIndex
    }));
    const previewPhotos = lpPreviewPhotos;
    const previewMain = previewPhotos.find((item) => item.is_main) || previewPhotos[0];
    const previewImg = publicImageSrc(previewMain?.url, "https://images.unsplash.com/photo-1560518883-ce09059eeffa?w=900&q=80");
    const previewType = type === "student" ? "student" : type;
    const source = listingSourceMeta({ listed_by: "private" });
    const bedVal = lpVal("lp-beds");
    const bathVal = lpVal("lp-baths");
    const sizeVal = cfg.showSize !== false ? lpVal("lp-size") : "";
    const previewDesc = lpVal("lp-description") || translateListingLabel("Description will appear here after you add details.");
    const subtypeLabel = document.getElementById("lp-subtype")?.selectedOptions?.[0]?.textContent || translateListingLabel("Property");
    const detailLocation = locationParts.filter(Boolean).join(", ");
    const latVal = parseFloatSafe(lpVal("lp-lat"));
    const lngVal = parseFloatSafe(lpVal("lp-lng"));
    const districtVal = lpVal("list-district-sel");
    const contactDisplayName = getPublicDisplayName() || translateListingLabel("Private Owner");
    const nearbyFacilities = getNearbyAmenitySuggestions({
      lat: latVal,
      lng: lngVal,
      district: districtVal,
      city,
      area
    });
    const autoAreaHighlights = buildLocationHighlightsText({
      type: previewType,
      area,
      district: districtVal,
      city,
      neighborhood: lpVal("lp-neighborhood"),
      nearby: nearbyFacilities
    });
    const areaHighlightsInput = document.getElementById("lp-area-highlights-edit");
    let areaHighlights = autoAreaHighlights;
    if (areaHighlightsInput) {
      const manualValue = (areaHighlightsInput.value || "").trim();
      const canAutoFill = !manualValue || areaHighlightsInput.dataset.auto !== "0";
      if (canAutoFill) {
        areaHighlightsInput.value = autoAreaHighlights;
        areaHighlightsInput.dataset.auto = "1";
        areaHighlights = autoAreaHighlights;
      } else {
        areaHighlights = manualValue;
      }
    }
    previewWrap.innerHTML = `
      <div class="bg-white rounded-2xl border border-gray-200 overflow-hidden">
        <div class="h-64 md:h-72 relative overflow-hidden">
          <img src="${adminAttr(previewImg)}" alt="${adminAttr(title)}" class="w-full h-full object-cover">
          <div class="absolute top-3 left-3 flex flex-wrap gap-1.5">
            <div class="${badgeColor(previewType)} text-white text-xs px-2 py-1 rounded font-bold">${badgeLabel(previewType)}</div>
            <div class="bg-blue-600 text-white text-[11px] px-2 py-1 rounded font-semibold inline-flex items-center gap-1"><i class="fas fa-bolt text-[10px]"></i> ${translateListingLabel("NEW")}</div>
            <div class="${source.cls} text-white text-[11px] px-2 py-1 rounded font-semibold inline-flex items-center gap-1"><i class="${source.icon} text-[10px]"></i> ${source.label}</div>
          </div>
          <div class="absolute bottom-3 right-3 bg-green-900/90 text-white px-3 py-1.5 rounded text-base font-black">${priceEl?.textContent || translateListingLabel("Price upon application")}</div>
        </div>
        <div class="px-5 pt-4">
          <div class="text-xs uppercase tracking-wide text-gray-500 font-semibold mb-2">${translateListingLabel("Uploaded photos preview")}</div>
          <div class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-2">
            ${previewPhotos.length ? previewPhotos.map((item, idx) => `
              <button type="button" onclick="openPreviewPhotoLightbox(${idx})" class="border border-gray-200 rounded-lg overflow-hidden bg-gray-50 text-left hover:border-green-400 transition-colors">
                <img src="${adminAttr(publicImageSrc(item.url))}" alt="${adminAttr(item.name)}" class="w-full h-20 object-cover">
                <div class="px-2 py-1.5 text-[11px] text-gray-600 truncate">${item.slot}${item.is_main ? ` • ${translateListingLabel("Main")}` : ""}</div>
              </button>
            `).join("") : `<div class="col-span-full text-xs text-gray-500">${translateListingLabel("Upload photos in Step 2 to preview exactly how they will appear.")}</div>`}
          </div>
        </div>
        <div class="p-5">
          <div class="flex items-start justify-between gap-4 flex-wrap">
            <div>
              <h3 class="text-3xl font-bold text-gray-800 leading-tight serif">${title}</h3>
              <p class="text-gray-500 mt-1"><i class="fas fa-map-marker-alt text-green-600"></i> ${detailLocation}</p>
            </div>
          </div>
          <div class="mt-4 text-sm text-gray-700">${previewDesc}</div>
          <div class="mt-4 bg-green-50 border border-green-100 rounded-xl p-3">
            <div class="text-xs uppercase tracking-wide text-green-700 font-semibold mb-1">${translateListingLabel("Area Highlights")}</div>
            <p class="text-sm text-gray-700">${areaHighlights}</p>
          </div>
          <div class="mt-3">
            <div class="text-xs uppercase tracking-wide text-gray-500 font-semibold mb-2">${translateListingLabel("Nearby Amenities")}</div>
            <div class="flex flex-wrap gap-2">
              ${nearbyFacilities.length ? nearbyFacilities.map((item) => {
                const distLabel = Number.isFinite(item.distanceKm) ? ` · ${item.distanceKm.toFixed(1)} km` : "";
                return `<span class="inline-flex items-center gap-1.5 bg-gray-50 border border-gray-200 rounded-full px-3 py-1 text-xs text-gray-700"><i class="fas fa-location-dot text-green-600"></i>${item.name}${distLabel}</span>`;
              }).join("") : `<span class="text-xs text-gray-500">${translateListingLabel("Nearby amenities will appear after location is set.")}</span>`}
            </div>
          </div>
          <div class="mt-4 grid sm:grid-cols-4 gap-3 text-sm">
              ${bedVal ? `<div class="bg-green-50 rounded-lg p-2"><strong>${bedVal}</strong> ${countLabel(bedVal, "bed", "beds")}</div>` : ""}
              ${bathVal ? `<div class="bg-green-50 rounded-lg p-2"><strong>${bathVal}</strong> ${countLabel(bathVal, "bath", "baths")}</div>` : ""}
            ${sizeVal ? `<div class="bg-green-50 rounded-lg p-2"><strong>${sizeVal}</strong></div>` : ""}
            <div class="bg-green-50 rounded-lg p-2"><strong>${subtypeLabel}</strong></div>
          </div>
          <div class="mt-3 text-xs text-gray-500">${translateListingLabel("Public contact name")}: <strong class="text-gray-700">${contactDisplayName}</strong></div>
        </div>
      </div>`;
    updateListPreviewMap(latVal, lngVal, title, detailLocation, districtVal);
    setTimeout(() => {
      if (lpPreviewMap) {
        resizeListMap(lpPreviewMap, lpPreviewMapProvider);
      }
    }, 120);
  }
  renderListReviewSummary();
}

function closePreviewPhotoLightbox() {
  closeModal("preview-photo-modal");
}

function renderPreviewPhotoLightbox() {
  const imageEl = document.getElementById("preview-photo-image");
  const captionEl = document.getElementById("preview-photo-caption");
  const thumbsEl = document.getElementById("preview-photo-thumbs");
  if (!imageEl || !captionEl || !thumbsEl) return;
  if (!lpPreviewPhotos.length) {
    imageEl.removeAttribute("src");
    captionEl.textContent = "";
    thumbsEl.innerHTML = "";
    return;
  }
  const active = lpPreviewPhotos[lpPreviewPhotoIndex] || lpPreviewPhotos[0];
  imageEl.src = publicImageSrc(active.url);
  captionEl.textContent = `${lpPreviewPhotoIndex + 1}/${lpPreviewPhotos.length} - ${active.slot || active.name || "Photo"}`;
  thumbsEl.innerHTML = lpPreviewPhotos.map((item, idx) => {
    const activeCls = idx === lpPreviewPhotoIndex ? "ring-2 ring-green-600 border-green-600" : "border-gray-200";
    return `
      <button type="button" onclick="openPreviewPhotoLightbox(${idx})" class="rounded-lg overflow-hidden border ${activeCls} bg-gray-50">
        <img src="${adminAttr(publicImageSrc(item.url))}" alt="${adminAttr(item.name || `Photo ${idx + 1}`)}" class="w-full h-14 object-cover">
      </button>
    `;
  }).join("");
}

function openPreviewPhotoLightbox(index = 0) {
  if (!lpPreviewPhotos.length) {
    toast(translateListingLabel("Upload photos in Step 2 to preview them."));
    return;
  }
  const next = Number(index);
  if (Number.isFinite(next)) {
    lpPreviewPhotoIndex = Math.max(0, Math.min(lpPreviewPhotos.length - 1, next));
  } else {
    lpPreviewPhotoIndex = 0;
  }
  renderPreviewPhotoLightbox();
  openModal("preview-photo-modal");
}

function shiftPreviewPhoto(direction = 1) {
  if (!lpPreviewPhotos.length) return;
  const delta = Number(direction) || 0;
  if (!delta) return;
  lpPreviewPhotoIndex = (lpPreviewPhotoIndex + delta + lpPreviewPhotos.length) % lpPreviewPhotos.length;
  renderPreviewPhotoLightbox();
}

function closeDetailGalleryLightbox() {
  closeModal("detail-photo-modal");
}

function renderDetailGalleryLightbox() {
  const imageEl = document.getElementById("detail-photo-image");
  const captionEl = document.getElementById("detail-photo-caption");
  const thumbsEl = document.getElementById("detail-photo-thumbs");
  if (!imageEl || !captionEl || !thumbsEl) return;
  if (!detailGalleryPhotos.length) {
    imageEl.removeAttribute("src");
    captionEl.textContent = "";
    thumbsEl.innerHTML = "";
    return;
  }
  const active = detailGalleryPhotos[detailGalleryPhotoIndex] || detailGalleryPhotos[0];
  const property = findPropertyForUi(activeDetailPropertyId);
  const slotLabel = getDisplayPhotoLabel(active, detailGalleryPhotoIndex, property);
  const locationLabel = active.location_label || "";
  imageEl.src = publicImageSrc(active.url);
  captionEl.textContent = `${detailGalleryPhotoIndex + 1}/${detailGalleryPhotos.length} - ${slotLabel}${locationLabel ? ` • ${locationLabel}` : ""}`;
  thumbsEl.innerHTML = detailGalleryPhotos.map((item, idx) => {
    const activeCls = idx === detailGalleryPhotoIndex ? "ring-2 ring-green-600 border-green-600" : "border-gray-200";
    return `
      <button type="button" onclick="openDetailGalleryLightbox(${idx})" class="rounded-lg overflow-hidden border ${activeCls} bg-gray-50">
        <img src="${adminAttr(publicImageSrc(item.url))}" alt="${adminAttr(item.name || `Photo ${idx + 1}`)}" class="w-full h-14 object-cover">
      </button>
    `;
  }).join("");
}

function selectDetailGalleryPhoto(index = 0) {
  if (!detailGalleryPhotos.length) return;
  const next = Number(index);
  if (!Number.isFinite(next)) return;
  detailGalleryPhotoIndex = Math.max(0, Math.min(detailGalleryPhotos.length - 1, next));
  const property = findPropertyForUi(activeDetailPropertyId) || {};
  const active = detailGalleryPhotos[detailGalleryPhotoIndex] || detailGalleryPhotos[0];
  const hero = document.getElementById("detail-gallery-hero-img");
  if (hero && active?.url) {
    hero.src = publicImageSrc(active.url);
    hero.alt = getDisplayPhotoLabel(active, detailGalleryPhotoIndex, property) || property.title || "Property photo";
  }
  const count = document.getElementById("detail-gallery-count-label");
  if (count) {
    const label = translateListingLabel(detailGalleryPhotos.length === 1 ? "Photo" : "Photos");
    count.textContent = `${detailGalleryPhotoIndex + 1}/${detailGalleryPhotos.length} ${label}`;
  }
  document.querySelectorAll("[data-detail-gallery-thumb]").forEach((button) => {
    const isActive = Number(button.getAttribute("data-detail-gallery-thumb")) === detailGalleryPhotoIndex;
    button.classList.toggle("border-green-500", isActive);
    button.classList.toggle("border-gray-200", !isActive);
    button.setAttribute("aria-current", isActive ? "true" : "false");
  });
}

function openDetailGalleryLightbox(index = 0) {
  if (!detailGalleryPhotos.length) {
    toast(translateListingLabel("No gallery photos available for this listing yet."));
    return;
  }
  const next = Number(index);
  if (Number.isFinite(next)) {
    detailGalleryPhotoIndex = Math.max(0, Math.min(detailGalleryPhotos.length - 1, next));
  } else {
    detailGalleryPhotoIndex = 0;
  }
  renderDetailGalleryLightbox();
  openModal("detail-photo-modal");
}

function shiftDetailGalleryPhoto(direction = 1) {
  if (!detailGalleryPhotos.length) return;
  const delta = Number(direction) || 0;
  if (!delta) return;
  detailGalleryPhotoIndex = (detailGalleryPhotoIndex + delta + detailGalleryPhotos.length) % detailGalleryPhotos.length;
  renderDetailGalleryLightbox();
}

function filterCommercial() {
  const q = (document.getElementById("commercial-q-f")?.value || "").toLowerCase().trim();
  const dRaw = document.getElementById("commercial-district-f")?.value || "";
  const d = dRaw;
  const radiusKm = getRadiusKmFromSelect("commercial-radius-f");
  const nearState = getNearMeSearchState("commercial");
  const type = (document.getElementById("commercial-type-f")?.value || "").toLowerCase().trim();
  const min = parseInt(document.getElementById("commercial-min-price-f")?.value || "0", 10);
  const max = parseInt(document.getElementById("commercial-price-f")?.value || "0", 10);
  const minSize = parseFloat(document.getElementById("commercial-size-f")?.value || "0");
  const sort = document.getElementById("commercial-sort-f")?.value || "newest";
  let list = getPublicListings().filter((p) => normalizeType(p.type) === "commercial");
  list = list.filter((p) => {
    const text = getPropertySearchText(p);
    const sizeNum = numericValue(p.size);
    const qMatch = !q || text.includes(q);
    const dMatch = nearState ? propertyMatchesNearMe(p, nearState, radiusKm || nearState.radiusKm) : matchDistrictRadius(p, d, radiusKm);
    const tMatch = !type || text.includes(type);
    const minMatch = !min || p.price >= min;
    const maxMatch = !max || p.price <= max;
    const sizeMatch = !minSize || sizeNum >= minSize;
    return qMatch && dMatch && tMatch && minMatch && maxMatch && sizeMatch;
  });
  if (sort === "price_asc") list.sort((a, b) => a.price - b.price);
  if (sort === "price_desc") list.sort((a, b) => b.price - a.price);
  if (sort === "size_desc") list.sort((a, b) => numericValue(b.size) - numericValue(a.size));
  if (sort === "newest") list.sort(sortListingsByNewest);
  if (nearState) list = decorateAndSortNearMeResults(list, nearState);
  renderGrid("commercial-grid", list);
  setMapMarkers("map-commercial", list);
  return list;
}

