function sortProps(page, order) {
  const gridMap = { sale: "sale-grid", rent: "rent-grid", students: "student-grid", commercial: "commercial-grid", land: "land-grid" };
  const key = page === "students" ? "student" : page;
  const list = getPublicListings().filter((p) => normalizeType(p.type) === key);
  if (order === "price_asc") list.sort((a, b) => a.price - b.price);
  if (order === "price_desc") list.sort((a, b) => b.price - a.price);
  if (order === "newest") {
    list.sort(sortListingsByNewest);
  }
  renderGrid(gridMap[page], list);
}

async function toggleSave(id) {
  const key = String(id);
  if (!authState?.user || !authState?.token) {
    setPendingSavePropertyId(key);
    openSavePropertyPrompt(key);
    trackEvent("property_save_auth_required", { property_id: id });
    return;
  }
  if (!findPropertyForUi(key)) {
    toast("This property is not available to save yet.");
    return;
  }
  const wasSaved = isPropertySaved(key);
  const existing = Array.from(savedIds).find((value) => String(value) === key);
  if (wasSaved && existing !== undefined) {
    savedIds.delete(existing);
    siteMetrics.propertySaves[String(id)] = Math.max(0, (parseInt(siteMetrics.propertySaves[String(id)] || 0, 10) || 0) - 1);
  } else {
    savedIds.add(key);
    siteMetrics.propertySaves[String(id)] = (parseInt(siteMetrics.propertySaves[String(id)] || 0, 10) || 0) + 1;
  }
  refreshSavedUi(id);

  try {
    await syncSavedPropertyToServer(key, !wasSaved);
    toast(wasSaved ? "Removed from saved" : "Property saved to your account");
    trackEvent(wasSaved ? "property_unsave" : "property_save", { property_id: id });
  } catch (e) {
    if (wasSaved) savedIds.add(key);
    else savedIds.delete(key);
    siteMetrics.propertySaves[String(id)] = Math.max(
      0,
      (parseInt(siteMetrics.propertySaves[String(id)] || 0, 10) || 0) + (wasSaved ? 1 : -1)
    );
    refreshSavedUi(id);
    toast(`Saved property update failed: ${e.message || "error"}`);
  }
}

function updateDetailSaveButton(id) {
  const btn = document.getElementById("detail-save-btn");
  if (!btn || String(activeDetailPropertyId || "") !== String(id || "")) return;
  btn.className = getDetailSaveButtonClasses(id);
  btn.innerHTML = getDetailSaveButtonContent(id);
  btn.setAttribute("aria-pressed", isPropertySaved(id) ? "true" : "false");
}

function formatUgxAmount(value) {
  const num = Math.max(0, Math.round(Number(value) || 0));
  return `USh ${num.toLocaleString()}`;
}

function formatMortgageAmount(value, currency = "UGX") {
  const normalizedCurrency = String(currency || "UGX").toUpperCase();
  const num = Math.max(0, Math.round(Number(value) || 0));
  if (normalizedCurrency === "USD") return `USD ${num.toLocaleString()}`;
  return formatUgxAmount(num);
}

function formatMortgageUpdatedAtLabel(value) {
  if (!value) return DEFAULT_MORTGAGE_RATE_UPDATED_AT;
  const dt = new Date(value);
  if (Number.isNaN(dt.getTime())) return String(value);
  const localeMap = { en: "en-GB", lg: "en-UG", sw: "sw-KE", ac: "en-UG", ny: "en-UG", rn: "en-UG", sm: "en-UG", am: "am-ET", ar: "ar" };
  const hasTime = String(value).includes("T");
  return dt.toLocaleString(localeMap[currentLang] || "en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    ...(hasTime ? { hour: "2-digit", minute: "2-digit" } : {})
  });
}

function hydrateMortgageProvidersFromApi(data, options = {}) {
  const checkedAt = data?.refreshedAt || options.checkedAt || new Date().toISOString();
  MORTGAGE_RATE_LAST_CHECKED_RAW = checkedAt;
  const providers = Array.isArray(data?.providers) ? data.providers : [];
  if (!providers.length) {
    MORTGAGE_RATE_UPDATED_RAW = data?.updatedAt || MORTGAGE_RATE_UPDATED_RAW || DEFAULT_MORTGAGE_RATE_UPDATED_AT;
    MORTGAGE_RATE_UPDATED_AT = formatMortgageUpdatedAtLabel(MORTGAGE_RATE_UPDATED_RAW);
    return false;
  }
  const normalized = providers.map((provider) => mergeAuditedMortgageProvider({
    id: provider.id || provider.key || provider.providerKey || provider.name || "provider",
    name: provider.name || provider.provider_name || "Provider",
    residentialRate: provider.residentialRate ?? provider.residential_rate ?? null,
    commercialRate: provider.commercialRate ?? provider.commercial_rate ?? null,
    landRate: provider.landRate ?? provider.land_rate ?? null,
    minDepositPct: {
      residential: provider.minDepositPct?.residential ?? provider.min_deposit_residential ?? 20,
      commercial: provider.minDepositPct?.commercial ?? provider.min_deposit_commercial ?? 20,
      land: provider.minDepositPct?.land ?? provider.min_deposit_land ?? 20,
      default: provider.minDepositPct?.default
        ?? provider.minDepositPct?.residential
        ?? provider.min_deposit_residential
        ?? 20
    },
    maxYears: {
      residential: provider.maxYears?.residential ?? provider.max_years_residential ?? 20,
      commercial: provider.maxYears?.commercial ?? provider.max_years_commercial ?? 20,
      land: provider.maxYears?.land ?? provider.max_years_land ?? 20,
      default: provider.maxYears?.default
        ?? provider.maxYears?.residential
        ?? provider.max_years_residential
        ?? 20
    },
    arrangementFeePct: provider.arrangementFeePct ?? provider.arrangement_fee_pct ?? 1.5,
    sourceLabel: provider.sourceLabel ?? provider.source_label ?? "Mortgage source",
    sourceUrl: provider.sourceUrl ?? provider.source_url ?? "#",
    logoUrl: provider.logoUrl ?? provider.logo_url ?? "",
    sourceNote: provider.sourceNote ?? provider.source_note ?? "",
    sourceVerifiedAt: provider.sourceVerifiedAt ?? provider.source_verified_at ?? null
  }));

  MORTGAGE_PROVIDERS = mergeAuditedMortgageProviderList(normalized);
  MORTGAGE_RATE_UPDATED_RAW = data.updatedAt || DEFAULT_MORTGAGE_RATE_UPDATED_AT;
  MORTGAGE_RATE_UPDATED_AT = formatMortgageUpdatedAtLabel(MORTGAGE_RATE_UPDATED_RAW);
  return true;
}

async function loadMortgageRates(showToastOnRefresh = false) {
  try {
    const checkedAt = new Date().toISOString();
    const response = await apiRequest("/api/mortgage-rates");
    hydrateMortgageProvidersFromApi(response?.data || {}, { checkedAt });
    renderMortgageFinder();
    if (showToastOnRefresh) toast(mortgageTr("dataRefreshed"));
  } catch (error) {
    // Keep static fallback rates when API is unavailable.
    MORTGAGE_RATE_LAST_CHECKED_RAW = new Date().toISOString();
    renderMortgageFinder();
    if (showToastOnRefresh) toast(mortgageTr("dataRefreshFail"));
  }
}

function mortgageProviderKey(provider = {}) {
  return String(provider.id || provider.key || provider.providerKey || provider.name || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function mortgageProviderBrand(provider = {}) {
  const key = mortgageProviderKey(provider);
  const name = String(provider.name || provider.provider_name || provider.providerName || key || "").toLowerCase();
  const alias = (key.includes("stanbic") || name.includes("stanbic") ? "stanbic" : "")
    || (key.includes("housing-finance") || key === "hfb" || name.includes("housing finance") ? "hfb" : "")
    || (key.includes("dfcu") || name.includes("dfcu") ? "dfcu" : "")
    || (key.includes("kcb") || name.includes("kcb") ? "kcb" : "")
    || (key.includes("ncba") || name.includes("ncba") ? "ncba" : "")
    || (key.includes("centenary") || name.includes("centenary") ? "centenary" : "")
    || (key.includes("baroda") || name.includes("baroda") ? "baroda" : "")
    || (key.includes("absa") || name.includes("absa") ? "absa" : "")
    || key;
  const brand = MORTGAGE_PROVIDER_BRANDS[alias] || {};
  const logoUrl = provider.logoUrl || provider.logo_url || "";
  const fallbackName = brand.shortName || String(provider.name || provider.provider_name || "Bank").replace(/\s+Bank\s+Uganda$/i, "").trim();
  const initials = fallbackName
    .split(/\s+/)
    .map((part) => part[0])
    .join("")
    .slice(0, 4)
    .toUpperCase() || "BK";
  return {
    key: alias || key,
    shortName: fallbackName,
    initials,
    logoUrl,
    bg: brand.bg || "#f8fafc",
    border: brand.border || "#d1d5db",
    text: brand.text || "#374151"
  };
}

function renderMortgageProviderLogo(provider = {}, options = {}) {
  const brand = mortgageProviderBrand(provider);
  const size = options.size === "lg" ? "h-14 min-w-[86px] max-w-[104px] px-2" : options.size === "sm" ? "h-9 min-w-[54px] max-w-[72px] px-2" : "h-11 min-w-[68px] max-w-[88px] px-2";
  const imgSize = options.size === "lg" ? "max-w-[76px] max-h-[42px]" : options.size === "sm" ? "max-w-[46px] max-h-[26px]" : "max-w-[58px] max-h-[32px]";
  const fallbackSize = options.size === "lg" ? "text-xs" : options.size === "sm" ? "text-[9px]" : "text-[10px]";
  const label = `${provider.name || brand.shortName || "Bank"} logo`;
  const image = brand.logoUrl
    ? `<img src="${adminAttr(brand.logoUrl)}" alt="${adminAttr(label)}" loading="lazy" referrerpolicy="no-referrer" class="${imgSize} hidden object-contain" onload="this.classList.remove('hidden');this.previousElementSibling.classList.add('hidden');" onerror="this.remove();">`
    : "";
  return `
    <span role="img" aria-label="${adminAttr(label)}" data-mortgage-logo="${adminAttr(brand.key)}" class="${size} shrink-0 rounded-2xl border flex items-center justify-center overflow-hidden shadow-sm" style="background:${adminAttr(brand.bg)};border-color:${adminAttr(brand.border)};color:${adminAttr(brand.text)}">
      <span data-mortgage-logo-text class="${fallbackSize} font-black leading-none tracking-normal text-center whitespace-nowrap overflow-hidden text-ellipsis">${adminEscape(brand.shortName || brand.initials)}</span>
      ${image}
    </span>`;
}

function mergeAuditedMortgageProvider(provider = {}) {
  const audited = AUDITED_MORTGAGE_PROVIDER_BY_ID[mortgageProviderKey(provider)];
  if (!audited) return provider;
  return {
    ...provider,
    residentialRate: audited.residentialRate,
    commercialRate: audited.commercialRate,
    landRate: audited.landRate,
    minDepositPct: {
      ...provider.minDepositPct,
      ...audited.minDepositPct
    },
    maxYears: {
      ...provider.maxYears,
      ...audited.maxYears
    },
    arrangementFeePct: audited.arrangementFeePct ?? provider.arrangementFeePct,
    sourceLabel: audited.sourceLabel || provider.sourceLabel,
    sourceUrl: audited.sourceUrl || provider.sourceUrl,
    sourceNote: audited.sourceNote || provider.sourceNote,
    sourceVerifiedAt: audited.sourceVerifiedAt || provider.sourceVerifiedAt
  };
}

function mergeAuditedMortgageProviderList(providers = []) {
  const mergedProviders = [];
  const seenProviderKeys = new Set();

  for (const provider of providers) {
    const mergedProvider = mergeAuditedMortgageProvider(provider);
    const key = mortgageProviderKey(mergedProvider);
    if (!key) continue;
    seenProviderKeys.add(key);
    mergedProviders.push(mergedProvider);
  }

  for (const provider of DEFAULT_MORTGAGE_PROVIDERS) {
    const key = mortgageProviderKey(provider);
    if (seenProviderKeys.has(key)) continue;
    seenProviderKeys.add(key);
    mergedProviders.push(mergeAuditedMortgageProvider({ ...provider }));
  }

  return mergedProviders;
}

function mortgageProviderByKey(key = "") {
  const normalized = mortgageProviderKey({ id: key });
  return MORTGAGE_PROVIDERS.find((provider) => mortgageProviderKey(provider) === normalized) || null;
}

function hydrateMortgageProviderSelect() {
  const select = document.getElementById("mortgage-lead-provider");
  if (!select) return;
  const current = selectedMortgageProviderKey || select.value || "";
  select.innerHTML = [
    `<option value="">${adminEscape(mortgageTr("genericProviderOption"))}</option>`,
    ...MORTGAGE_PROVIDERS.map((provider) => {
      const key = mortgageProviderKey(provider);
      return `<option value="${adminAttr(key)}">${adminEscape(provider.name || key)}</option>`;
    })
  ].join("");
  if (current && mortgageProviderByKey(current)) {
    select.value = mortgageProviderKey({ id: current });
  } else {
    select.value = "";
    selectedMortgageProviderKey = "";
  }
}

